      const n=String(schemeItemDrawerQ['检验项名称']||'').trim();
      if(c) rows = rows.filter(r=> String(r['检验项编码']||'').includes(c));
      if(n) rows = rows.filter(r=> String(r['检验项名称']||'').includes(n));
