      if(!hit){ ElMessage.warning(inbound ? '请选择库位' : '请选择领用去向'); return; }
      const rows = slocDispRows.value.slice();
      slocMove(rows, inbound ? '样品入库' : '领用检验', hit, true, {});
      slocDispVisible.value = false;
