      const head = { 培训类型: types.join('、'), 培训内容: txt('培训内容'), 培训时间: txt('培训时间'), 培训地点: txt('培训地点'), 备注: txt('备注') };
      const lineData = r=> ({ 工号: r['工号'], 姓名: r['姓名'], 部门: r['部门'], 培训结果: String(r['培训结果']||'').trim(), 附件: r['附件']||'' });
