        if(f.name==='采购订单') return whBiz==='销售发货' && formModel['配送类型']==='直发业务（贸易）';
        if(f.name==='关联销售备货单') return whBiz==='销售发货' || whBiz==='销售预出货';
        if(f.name==='关联销售预出货单') return whBiz==='销售发货';
