    function parseQtyUnit(text, defUnit){
      const m = String(text||'').trim().match(/^(\d+(?:\.\d+)?)\s*\/?\s*(.*)$/);
      let u = (m && m[2]) ? m[2] : (defUnit||'');
      if(u==='分') u = '分钟';
      if(u==='时') u = '小时';
      return { n: m ? m[1] : '', u: u };
    }
