      const id = pageId.value || '';
      if(id==='po' || id==='so' || id==='wwpo' || id==='mat-medium' || id==='lg-dispatch' || id==='pkg-craft') return true;
      return id.startsWith('wh-') && id!=='wh-so-prep';
