    const driftColRows = ref([]);
    const driftPointRows = ref([]); // 兼容旧抽屉入口，新口径不再维护采样点
    const newDriftImpurity = ()=> ({ 是否主峰:'否', 典型保留时间:'', 定性结构:'', 标准结果值:'', UCL:'', LCL:'' });
    const newDriftRrtRule = ()=> ({ 时间范围起:'', 时间范围止:'', 下限符号:'-', 下限数值:'', 上限符号:'+', 上限数值:'' });
    const newDriftMat = ()=> ({ 物料编码:'', 物料名称:'' });
    const newDriftCol = ()=> ({ 色谱柱型号:'' });
    const addDriftImpurity = ()=> { driftImpurityRows.value.push(newDriftImpurity()); };
    const removeDriftImpurity = (i)=> { driftImpurityRows.value.splice(i, 1); };
    const addDriftRrtRule = ()=> { driftRrtRows.value.push(newDriftRrtRule()); };
    const removeDriftRrtRule = (i)=> { driftRrtRows.value.splice(i, 1); };
    function removeDriftRrtRules(){
      if(!driftRrtSelected.value.length){ ElMessage.warning('请先勾选要删除的行'); return; }
      const set = new Set(driftRrtSelected.value);
      driftRrtRows.value = driftRrtRows.value.filter(r=> !set.has(r));
      driftRrtSelected.value = [];
    }
    const addDriftMat = ()=> { driftMatRows.value.push(newDriftMat()); };
    const removeDriftMat = (i)=> { driftMatRows.value.splice(i, 1); };
    const addDriftCol = ()=> { driftColRows.value.push(newDriftCol()); };
    const removeDriftCol = (i)=> { driftColRows.value.splice(i, 1); };
    function driftSignedOffset(sign, val){
      const n = driftNum(val);
      if(n==null) return null;
      return (sign==='-' ? -1 : 1) * Math.abs(n);
    }
    function driftFmtSigned(sign, val){
      const t = String(val==null?'':val).trim();
      if(!t) return '';
      return (sign==='-' ? '-' : '+') + t;
    }
    function driftRrtSummary(rows){
      const list = (rows||[]).map(r=>{
        const a = driftFmtSigned(r.下限符号||'-', r.下限数值);
        const b = driftFmtSigned(r.上限符号||'+', r.上限数值);
        return (a && b) ? (a+'~'+b) : '';
      }).filter(Boolean);
      return list.length ? [...new Set(list)].join('、') : '';
    }
    function driftPickRrtRule(rules, tr){
      const list = rules||[];
      if(!list.length) return null;
      if(tr==null) return list[0];
      const hit = list.find(r=>{
        const a = driftNum(r.时间范围起), b = driftNum(r.时间范围止);
        if(a==null && b==null) return true;
        if(a!=null && tr < a) return false;
        if(b!=null && tr > b) return false;
        return true;
      });
      return hit || list[0];
    }
    function driftRangeByRrt(tr, rules, fallbackLo, fallbackHi){
      const rule = driftPickRrtRule(rules, tr);
      if(rule){
        const loOff = driftSignedOffset(rule.下限符号||'-', rule.下限数值);
        const hiOff = driftSignedOffset(rule.上限符号||'+', rule.上限数值);
        if(tr!=null && loOff!=null && hiOff!=null) return { lo: tr + loOff, hi: tr + hiOff };
      }
      const lo = driftNum(fallbackLo), hi = driftNum(fallbackHi);
      if(lo!=null || hi!=null) return { lo: lo==null ? tr : lo, hi: hi==null ? tr : hi };
      return { lo: tr, hi: tr };
    }
    const driftMatOptions = ()=> ((MOCK['mat-list']||{}).main||[]).filter(r=> String(r['启用状态']||'启用')==='启用');
    function onDriftMatPick(row){
      if(!row) return;
      const m = driftMatOptions().find(x=> x['物料编码']===row.物料编码);
      row.物料名称 = m ? (m['物料名称']||'') : '';
    }
    const driftColTypeOptions = ()=>{
      // 型号主数据来自色谱柱台账左侧型号列表（types）；无型号字典时回落台账行去重
      const bag = MOCK['np-0208-01'] || {};
      const models = (bag.types || []).map(t=> String(t['名称']||t['色谱柱型号']||'').trim()).filter(Boolean);
      if(models.length) return [...new Set(models)];
      return [...new Set((bag.main || []).map(r=> String(r['色谱柱型号']||'').trim()).filter(Boolean))];
    };
    function onDriftMainPeak(row){
      if(row['是否主峰']!=='是') return;
      const mains = driftImpurityRows.value.filter(r=> r['是否主峰']==='是');
      if(mains.length <= 2) return;
      // 支持双主峰：超过 2 条时，取消本次勾选并提示
      row['是否主峰'] = '否';
      ElMessage.warning('最多支持双主峰（2 条）');
    }
    function driftBag(){
      if(!MOCK[DRIFT_PAGE]) MOCK[DRIFT_PAGE]={ main:[] };
      const b = MOCK[DRIFT_PAGE];
      if(!Array.isArray(b.main)) b.main = [];
      // 旧版 GC/LC 页签数据迁移到单列表 main
      [['tab-1','GC'],['tab-2','LC']].forEach(([t, cat])=>{
        if(!Array.isArray(b[t]) || !b[t].length) return;
        b[t].forEach(r=>{
          if(!r) return;
          if(!r['规则分类']) r['规则分类'] = cat;
          if(!(r['适用检验类型']) && r['使用检验类型']) r['适用检验类型'] = r['使用检验类型'];
          if(!(r['使用检验类型']) && r['适用检验类型']) r['使用检验类型'] = r['适用检验类型'];
          if(!b.main.some(x=> x && (x.id===r.id || x['规则编码']===r['规则编码']))) b.main.push(r);
        });
        b[t] = [];
      });
      return b;
    }
    function driftRowsOf(){ return driftBag().main; }
    function driftInspList(v){
      if(Array.isArray(v)) return v.map(x=> String(x||'').trim()).filter(Boolean);
      return String(v==null?'':v).split(/[、,，]/).map(x=> x.trim()).filter(Boolean);
    }
    function driftNum(v){
      const t = String(v==null?'':v).trim();
      if(t==='' || t==='—') return null;
      const n = Number(t);
      return Number.isFinite(n) ? n : null;
    }
    function resetDriftForm(){
      driftFormTab.value = 'rrt';
      driftImpurityRows.value = [newDriftImpurity(), newDriftImpurity()];
      driftRrtRows.value = [newDriftRrtRule()];
      driftRrtSelected.value = [];
      driftNewUCL.value = ''; driftNewLCL.value = '';
      driftFilterMin.value = ''; driftFilterMax.value = '';
      driftMatRows.value = [newDriftMat()];
      driftColRows.value = [newDriftCol()];
      formModel['规则分类'] = 'GC';
      formModel['TR规则'] = '按固定值不叠加';
      formModel['适用检验类型'] = [];
      formModel['使用检验类型'] = [];
      formSwitch['启用状态'] = true;
    }
    function fillDriftForm(row, isCopy){
      resetDriftForm();
      formModel['规则编码'] = isCopy ? '' : (row['规则编码']||'');
      formModel['规则名称'] = row['规则名称']||'';
      formModel['规则分类'] = row['规则分类']||'GC';
      formModel['TR规则'] = row['TR规则']||'按固定值不叠加';
      formModel['适用检验类型'] = driftInspList(row['适用检验类型']||row['使用检验类型']);
      formModel['使用检验类型'] = formModel['适用检验类型'];
      formModel['备注'] = row['备注']==='—' ? '' : (row['备注']||'');
      formSwitch['启用状态'] = row['启用状态']!=='禁用';
      const imps = (row._impurities && row._impurities.length) ? row._impurities : (row._known||[]);
      driftImpurityRows.value = imps.length ? imps.map(r=> ({
        是否主峰: r['是否主峰']||'否',
        典型保留时间: r['典型保留时间']||'',
        定性结构: r['定性结构']||'',
        标准结果值: r['标准结果值']||'',
        UCL: (r.UCL && typeof r.UCL==='object') ? (r.UCL.val||'') : (r.UCL||''),
        LCL: (r.LCL && typeof r.LCL==='object') ? (r.LCL.val||'') : (r.LCL||'')
      })) : [newDriftImpurity()];
      const rrts = row._rrtRules || [];
      if(rrts.length){
        driftRrtRows.value = rrts.map(r=> ({
          时间范围起: r.时间范围起||'', 时间范围止: r.时间范围止||'',
          下限符号: r.下限符号||'-', 下限数值: r.下限数值||'',
          上限符号: r.上限符号||'+', 上限数值: r.上限数值||''
        }));
      } else {
        // 兼容旧数据：规则级偏差范围下限/上限 → 一条全范围 RRT 规则
        const lo = String(row['偏差范围下限']||'').trim();
        const hi = String(row['偏差范围上限']||'').trim();
        if(lo || hi){
          const parseSigned = (s)=>{
            const t = String(s||'').trim();
            if(!t) return { sign:'+', val:'' };
            if(t.startsWith('-')) return { sign:'-', val: t.slice(1) };
            if(t.startsWith('+')) return { sign:'+', val: t.slice(1) };
            return { sign:'+', val: t };
          };
          const a = parseSigned(lo), b = parseSigned(hi);
          driftRrtRows.value = [{ 时间范围起:'0', 时间范围止:'999', 下限符号:a.sign, 下限数值:a.val, 上限符号:b.sign, 上限数值:b.val }];
        } else {
          driftRrtRows.value = [newDriftRrtRule()];
        }
      }
      driftRrtSelected.value = [];
      driftFilterMin.value = (row._filter && row._filter.min) || '';
      driftFilterMax.value = (row._filter && row._filter.max) || '';
      driftNewUCL.value = row._newUCL!=null ? String(row._newUCL) : ((row._ucl && row._ucl.val) || '');
      driftNewLCL.value = row._newLCL!=null ? String(row._newLCL) : ((row._lcl && row._lcl.val) || '');
      driftMatRows.value = (row._mats||[]).map(r=> ({ 物料编码:r['物料编码']||'', 物料名称:r['物料名称']||'' }));
      if(!driftMatRows.value.length) driftMatRows.value = [newDriftMat()];
      const cols = row._columns || row._cols || [];
      driftColRows.value = cols.map(c=> ({ 色谱柱型号: (c && c['色谱柱型号']) || c || '' }));
      if(!driftColRows.value.length) driftColRows.value = [newDriftCol()];
      if(!isCopy) formModel._editId = row.id;
    }
    function openDriftForm(mode, row){
      openForm(mode==='detail'?'detail':(mode==='edit'?'edit':(mode==='copy'?'copy':'add')));
      if(mode==='add') resetDriftForm();
      else fillDriftForm(row, mode==='copy');
    }
    // 漂移规则匹配：物料编码 + 色谱柱型号 + 检验类型；仅启用规则，创建时间倒序（多条时首条即最新）
    function driftMatchRules(matCode, colType, inspType){
      const list = driftRowsOf().filter(r=> r['启用状态']!=='禁用');
      const mc = String(matCode||'').trim(), ct = String(colType||'').trim(), it = String(inspType||'').trim();
      return list.filter(r=>{
        const mats = (r._mats||[]).map(m=> m['物料编码']);
        if(mc && !mats.includes(mc)) return false;
        const cols = (r._columns||r._cols||[]).map(c=> (c && c['色谱柱型号']) || c);
        if(ct && cols.length && !cols.includes(ct)) return false;
        if(it){
          const types = driftInspList(r['使用检验类型']||r['适用检验类型']);
          if(types.length && !types.includes(it)) return false;
        }
        return true;
      }).sort((a, b)=> String(b['创建时间']||'').localeCompare(String(a['创建时间']||'')));
    }
    function driftMatchRule(matCode, colType, inspType){
      return driftMatchRules(matCode, colType, inspType)[0] || null;
    }
    function driftRuleWindows(rule){
      if(!rule) return null;
      const rrtRules = rule._rrtRules || [];
      const imps = (rule._impurities||rule._known||[]).map(x=>{
        const tr = driftNum(x.典型保留时间);
        if(tr==null) return null;
        const range = driftRangeByRrt(tr, rrtRules, x.有效范围下限, x.有效范围上限);
        return {
          典型保留时间: tr,
          下限: range.lo==null ? tr : range.lo,
          上限: range.hi==null ? tr : range.hi,
          是否主峰: x.是否主峰==='是',
          定性结构: x.定性结构||'',
          标准结果值: String(x.标准结果值||'').trim(),
          UCL: (x.UCL && typeof x.UCL==='object') ? (x.UCL.val||'') : (x.UCL||''),
          LCL: (x.LCL && typeof x.LCL==='object') ? (x.LCL.val||'') : (x.LCL||'')
        };
      }).filter(Boolean);
      return imps.length ? imps : null;
    }
    function saveDriftForm(){
      const txt = k=> String(formModel[k]==null?'':formModel[k]).trim();
      const code = txt('规则编码'), name = txt('规则名称'), cat = txt('规则分类'), tr = txt('TR规则') || txt('典型保留时间规则');
      const inspArr = driftInspList(formModel['适用检验类型']||formModel['使用检验类型']);
      if(!code){ ElMessage.warning('请填写规则编码'); return; }
      if(!name){ ElMessage.warning('请填写规则名称'); return; }
      if(!cat){ ElMessage.warning('请选择规则分类'); return; }
      if(!tr){ ElMessage.warning('请选择 TR规则'); return; }
      if(!inspArr.length){ ElMessage.warning('请选择适用检验类型'); return; }
      const mats = driftMatRows.value.map(r=> ({ 物料编码:String(r.物料编码||'').trim(), 物料名称:String(r.物料名称||'').trim() })).filter(r=> r.物料编码);
      const cols = driftColRows.value.map(r=> ({ 色谱柱型号:String(r.色谱柱型号||'').trim() })).filter(r=> r.色谱柱型号);
      if(!mats.length){ ElMessage.warning('请至少添加一条适用物料'); return; }
      if(!cols.length){ ElMessage.warning('请至少添加一条色谱柱型号'); return; }
      if(new Set(mats.map(m=> m.物料编码)).size!==mats.length){ ElMessage.warning('适用物料不可重复'); return; }
      if(new Set(cols.map(c=> c.色谱柱型号)).size!==cols.length){ ElMessage.warning('色谱柱型号不可重复'); return; }
      const rrtRules = driftRrtRows.value.map(r=> ({
        时间范围起: String(r.时间范围起||'').trim(),
        时间范围止: String(r.时间范围止||'').trim(),
        下限符号: r.下限符号==='+' ? '+' : '-',
        下限数值: String(r.下限数值||'').trim(),
        上限符号: r.上限符号==='+' ? '+' : '-',
        上限数值: String(r.上限数值||'').trim()
      })).filter(r=> r.时间范围起 || r.时间范围止 || r.下限数值 || r.上限数值);
      for(const r of rrtRules){
        const a = driftNum(r.时间范围起), b = driftNum(r.时间范围止);
        if(a!=null && b!=null && a>b){ ElMessage.warning('时间范围起不可大于止'); return; }
        const loOff = driftSignedOffset(r.下限符号, r.下限数值);
        const hiOff = driftSignedOffset(r.上限符号, r.上限数值);
        if(loOff!=null && hiOff!=null && loOff>hiOff){ ElMessage.warning('RRT&TR差值范围下限不可大于上限'); return; }
      }
      const imps = driftImpurityRows.value.map(r=> {
        const tr = String(r.典型保留时间||'').trim();
        const trn = driftNum(tr);
        const range = driftRangeByRrt(trn, rrtRules, '', '');
        return {
          是否主峰: r.是否主峰==='是' ? '是' : '否',
          典型保留时间: tr,
          有效范围下限: (trn!=null && range.lo!=null) ? String(Number(range.lo.toFixed(4))) : '',
          有效范围上限: (trn!=null && range.hi!=null) ? String(Number(range.hi.toFixed(4))) : '',
          定性结构: String(r.定性结构||'').trim(),
          标准结果值: String(r.标准结果值||'').trim(),
          UCL: String(r.UCL||'').trim(),
          LCL: String(r.LCL||'').trim()
        };
      }).filter(r=> r.典型保留时间);
      if(imps.filter(r=> r.是否主峰==='是').length>2){ ElMessage.warning('已知杂质项目最多支持双主峰（2 条）'); return; }
      for(const r of imps){
        if(r.标准结果值 && driftNum(r.标准结果值)==null){ ElMessage.warning('标准结果值须为数字（典型保留时间 '+r.典型保留时间+'）'); return; }
      }
      const isAdd = formMode.value!=='edit';
      const list = driftRowsOf();
      for(const x of list){
        if(!isAdd && x.id===formModel._editId) continue;
        if(x['规则分类']===cat && x['规则编码']===code){ ElMessage.warning('规则编码「'+code+'」已存在'); return; }
        if(x['规则分类']===cat && x['规则名称']===name){ ElMessage.warning('规则名称「'+name+'」已存在'); return; }
        const xt = new Set(driftInspList(x['使用检验类型']||x['适用检验类型']));
        const xm = new Set((x._mats||[]).map(m=> m['物料编码']));
        const sameType = inspArr.every(t=> xt.has(t)) && [...xt].every(t=> inspArr.includes(t));
        const sameMat = mats.every(m=> xm.has(m.物料编码)) && [...xm].every(c=> mats.some(m=> m.物料编码===c));
        if(sameType && sameMat){ ElMessage.warning('适用检验类型 + 适用物料 组合与规则 '+x['规则编码']+' 重复'); return; }
      }
      const inspText = inspArr.join('、');
      const rrtText = driftRrtSummary(rrtRules) || '—';
      const firstRrt = rrtRules[0] || null;
      const payload = {
        规则编码: code, 规则名称: name, 规则分类: cat, TR规则: tr,
        使用检验类型: inspText, 适用检验类型: inspText,
        偏差范围: rrtText==='—' ? '' : rrtText, 'RRT&TR的偏差范围': rrtText,
        偏差范围下限: firstRrt ? driftFmtSigned(firstRrt.下限符号, firstRrt.下限数值) : '',
        偏差范围上限: firstRrt ? driftFmtSigned(firstRrt.上限符号, firstRrt.上限数值) : '',
        杂质个数: imps.length,
        适用物料: mats.map(m=> m.物料名称||m.物料编码).join('、') || '—',
        适用色谱柱: cols.map(c=> c.色谱柱型号).join('、') || '—',
        备注: txt('备注')||'—',
        启用状态: formSwitch['启用状态']===false ? '禁用' : '启用',
        _mats: mats, _columns: cols, _cols: cols, _impurities: imps, _rrtRules: rrtRules,
        _filter: { min: String(driftFilterMin.value||'').trim(), max: String(driftFilterMax.value||'').trim() },
        _newUCL: String(driftNewUCL.value||'').trim(), _newLCL: String(driftNewLCL.value||'').trim(),
        _known: imps.map(r=> Object.assign({}, r, { 创建方式:'手动', 创建时间: nowStamp() }))
      };
      if(isAdd){
        list.unshift(Object.assign({ id:'dr-'+Date.now() }, payload, { 创建人:'管理员', 创建时间: nowStamp() }));
      } else {
        const cur = list.find(r=> r.id===formModel._editId);
        if(!cur){ ElMessage.warning('未找到待编辑数据'); return; }
        Object.assign(cur, payload);
      }
      // 保存成功后按规则字段同步 GC / LC 台账的分类与表头列
      const _savedRule = isAdd ? list[0] : list.find(r=> r.id===formModel._editId);
      const _sync = syncChromLedgerByRule(_savedRule);
      formVisible.value = false; bumpStore();
      const _base = isAdd ? ('已新增漂移规则 '+code) : '保存成功';
      if(_sync.pageId && (_sync.added + _sync.updated + _sync.removed) > 0){
        const _pn = _sync.pageId === 'np-0208-04' ? 'GC台账' : 'LC台账';
        ElMessage.success(_base + '；已按规则更新' + _pn + '分类（派生展示，本次涉及 ' + (_sync.added + _sync.updated) + ' 项' + (_sync.removed ? '，清理 ' + _sync.removed : '') + '）');
      } else {
        ElMessage.success(_base);
      }
      if(_sync.note) ElMessage.warning('台账同步提示：' + _sync.note);
    }
    function deleteDriftRows(idsOpt){
      const ids = new Set(idsOpt || selectedIds.value);
      if(!ids.size){ ElMessage.warning('请先勾选要删除的规则'); return; }
      const list = driftRowsOf();
      const used = list.filter(r=> ids.has(r.id) && r._ref);
      if(used.length){ ElMessage.warning('此数据正在使用，不可删除'); return; }
      ElementPlus.ElMessageBox.confirm('确认删除所选的 '+ids.size+' 条规则？','批量删除',{type:'warning'}).then(()=>{
        for(let i=list.length-1;i>=0;i--){ if(ids.has(list[i].id)) list.splice(i,1); }
        selectedIds.value=[]; bumpStore(); ElMessage.success('已删除 '+ids.size+' 条规则');
      }).catch(()=>{});
    }
    function onDriftToolbar(btn){
      if(btn.name==='新增'){ openDriftForm('add'); return true; }
      if(btn.name==='批量删除'){ deleteDriftRows(); return true; }
      if(btn.name==='导入' || btn.name==='导入数据'){ importVisible.value=true; return true; }
      if(btn.name==='导出' || btn.name==='导出数据'){ exportVisible.value=true; return true; }
      return false;
    }

    /** 谱图识别（np-0208-03）：对齐 OLED「图谱识别」——单列表；源文件取自图谱文件台账；按 物料编码 + 色谱柱型号（+ 检验类型）匹配漂移规则；识别 + 计算 */
    const SPI_PAGE = 'np-0208-03';
    const SPI_YN = ['是','否'];
    const isSpiForm = computed(()=> pageId.value===SPI_PAGE && ['add','edit'].includes(formMode.value));
    const SPI_FIELD_KEYS = ['检验类型','源文件','文件名称','规则分类','物料编码','物料名称','物料规格','物料种类','色谱柱型号','色谱柱编号','仪器编号','仪器名称','批号','漂移规则','备注'];
    function spiBag(){
      if(!MOCK[SPI_PAGE]) MOCK[SPI_PAGE] = {};
      const b = MOCK[SPI_PAGE];
      if(!Array.isArray(b.main)) b.main = [];
      // 旧版 GC/LC 页签缓存字段口径不同（采样点 / 谱图流水…），直接丢弃
      ['tab-1','tab-2'].forEach(t=>{ if(b[t]) delete b[t]; });
      return b;
    }
    function spiRowsOf(){ return spiBag().main; }

// ===== 谱图识别 识别+计算（移植自 OLED spectrum-calc.js，漂移规则取 np-0208-02）=====
    const spectrumPeaks = ref([]);
    const spectrumCalcDone = ref(false);
    // 本次识别是否「未匹配到规则方案」（用于列表上方常驻提示，避免只靠一句 toast）
    const spectrumNoRule = ref(false);
    const spectrumNoteVisible = ref(true);
    const spectrumCols = [
      { prop: '谱图峰号', label: '谱图峰号', req: true, tag: '识别填充', tagType: 'primary', width: 96, editable: false },
      { prop: '谱图保留时间', label: '谱图保留时间', req: true, tag: '识别填充', tagType: 'primary', width: 130, editable: true },
      { prop: '谱图峰面积', label: '谱图峰面积', req: true, tag: '识别填充', tagType: 'primary', width: 120, editable: true },
      { prop: '检验项名称', label: '检验项名称', req: false, tag: '自动带出', tagType: 'success', width: 120, editable: false },
      { prop: '是否主峰', label: '是否主峰', req: true, tag: '自动判断', tagType: 'warning', width: 96, type: 'select' },
      { prop: '参考峰', label: '参考峰', req: true, tag: '自动判断', tagType: 'info', width: 176, type: 'select-ref' },
      { prop: '相对保留时间', label: '相对保留时间', req: true, tag: '自动计算', tagType: 'primary', width: 130, editable: true },
      { prop: '对应典型保留时间', label: '对应典型保留时间', req: false, tag: '自动匹配', tagType: 'success', width: 168, type: 'select-tr' },
      { prop: '有效取值范围', label: '有效取值范围', req: false, tag: '自动带入', tagType: 'primary', width: 150, editable: false },
      { prop: '对应定性结构', label: '对应定性结构', req: false, tag: '自动匹配', tagType: 'success', width: 130, editable: false },
      { prop: '典型保留时间', label: '典型保留时间', req: false, tag: '新杂可填', tagType: 'warning', width: 130, type: 'tr-new' },
      { prop: '是否锁定', label: '是否锁定', req: false, tag: '默认为否', tagType: 'info', width: 96, type: 'select' },
      { prop: '是否新杂', label: '是否新杂', req: false, tag: '自动匹配', tagType: 'success', width: 96, type: 'select' },
      { prop: '杂质指标', label: '杂质指标', req: false, tag: '自动代入', tagType: 'primary', width: 150, editable: false },
      { prop: '杂质偏差结论', label: '杂质偏差结论', req: false, tag: '自动判断', tagType: 'warning', width: 112, editable: false },
    ];
    // 参考峰：相对保留时间的计算基准（默认主峰；逐行独立选择，改一行只重算该行，不影响其他行）
    const spectrumRefPeak = ref('');
    const spectrumRefOptions = computed(()=> (spectrumPeaks.value || []).map(r=> ({
      value: String(r.谱图峰号 || ''),
      label: String(r.谱图峰号 || '') + (String(r.是否主峰 || '') === '是' ? '（主峰）' : '')
    })).filter(o=> o.value));
    // 主峰峰号：优先「是否主峰＝是」的行中峰面积最大者，其次整表峰面积最大者
    function spectrumMainPeakNoOf(rows){
      const list = (rows || []).filter(r=> String((r && r.谱图峰号) || '').trim());
      if(!list.length) return '';
      const mains = list.filter(r=> String(r.是否主峰 || '') === '是');
      const pool = mains.length ? mains : list;
      const peak = pool.reduce((a, b)=> (Number(b.谱图峰面积) || 0) > (Number(a.谱图峰面积) || 0) ? b : a, pool[0]);
      return String(peak.谱图峰号 || '').trim();
    }
    // 参考峰折算因子（口径 A）：f = 参考峰典型保留时间 ÷ 参考峰谱图保留时间
    // 参考峰的典型保留时间取该行「对应典型保留时间」首值（参考峰必须是已定住的峰），缺失时回退主峰典型保留时间
    function spectrumFactorOf(refNo, allPeaks, mainTR, mainPeakNo){
      const no = String(refNo || '').trim();
      const list = allPeaks || [];
      const refRow = list.find(p=> String(p.谱图峰号 || '') === no)
        || list.find(p=> String(p.谱图峰号 || '') === String(mainPeakNo)) || {};
      const rt = Number(refRow.谱图保留时间);
      let refTR = driftNum(String(refRow.对应典型保留时间 || '').split(',')[0]);
      if(refTR == null) refTR = mainTR;
      if(!Number.isFinite(rt) || !rt || refTR == null) return 1;
      return refTR / rt;
    }
    // 单行计算（纯函数）：按该行自己的「参考峰」算相对保留时间与匹配结果
    function spectrumCalcRow(basis, allPeaks, wins, newLim, mainTR, mainPeakNo){
      const rt = Number(basis.谱图保留时间);
      const area = Number(basis.谱图峰面积);
      const refNo = String(basis.参考峰 || '').trim() || String(mainPeakNo || '');
      const factor = spectrumFactorOf(refNo, allPeaks, mainTR, mainPeakNo);
      const rrt = Number.isFinite(rt) ? Number((rt * factor).toFixed(4)) : null;
      const base = {
        谱图峰号: String(basis.谱图峰号 || ''),
        谱图保留时间: Number.isFinite(rt) ? rt.toFixed(3) : String(basis.谱图保留时间 || ''),
        谱图峰面积: Number.isFinite(area) ? area.toFixed(4) : String(basis.谱图峰面积 || ''),
        检验项名称: String(basis.检验项名称 || '').trim(),
        是否主峰: String(basis.是否主峰 || '') === '是' ? '是' : '否',
        参考峰: refNo,
        相对保留时间: rrt == null ? '—' : rrt.toFixed(4),
        对应典型保留时间: '',
        对应定性结构: '',
        典型保留时间: String(basis.典型保留时间 || '').trim(),
        有效取值范围: '',
        是否锁定: '否',
        是否新杂: '否',
        杂质指标: '—',
        杂质偏差结论: '—',
        匹配异常说明: '/',
        _rrt: rrt,
        _qualified: false
      };
      if(rrt == null) return base;
      // 逐一判断该峰的相对保留时间是否落在某典型保留时间的有效取值范围内
      const hits = (wins || []).filter(w=> rrt >= w.下限 - 1e-9 && rrt <= w.上限 + 1e-9);
      if(!hits.length){
        // 不在任何有效取值范围内 → 不参与自动匹配，无法匹配到结果值（按新杂处理）
        base.匹配异常说明 = '超出有效范围';
        base.是否新杂 = '是';
        base.典型保留时间 = String(basis.典型保留时间 || '').trim();
        base.杂质指标 = 'UCL<' + newLim.ucl + '，LCL>' + newLim.lcl;
        base.杂质偏差结论 = (Number.isFinite(area) && area > newLim.ucl) ? '异常' : '正常';
        return base;
      }
      const w = hits[0];
      base.对应典型保留时间 = hits.map(h=> h.典型保留时间.toFixed(3)).join(',');
      base.对应定性结构 = w.定性结构 || '';
      // 检验项名称：优先沿用手工值，否则取匹配到的定性结构；主峰无结构时由后续统一补「主峰N」
      if(!base.检验项名称 && w.定性结构) base.检验项名称 = String(w.定性结构 || '').trim();
      base.典型保留时间 = '';
      base.有效取值范围 = hits.map(h=> h.下限.toFixed(4) + '~' + h.上限.toFixed(4)).join(' / ');
      base.是否锁定 = (w.是否主峰 || (w.定性结构 && w.定性结构 === basis.定性结构)) ? '是' : '否';
      base.杂质指标 = spectrumImpIndexText(w);
      // 已定性（主峰，或唯一命中带定性结构的典型保留时间）：身份已确定，不需要参考峰作尺子 → 该字段留空
      const qualified = !basis._refManual && (
        String(basis.是否主峰 || '') === '是'
        || (hits.length === 1 && !!String(w.定性结构 || '').trim())
      );
      base._qualified = !!qualified;
      if(qualified) base.参考峰 = '';
      if(hits.length > 1){
        base.匹配异常说明 = '重复匹配（' + base.对应典型保留时间 + '）';
        base.是否锁定 = '否';
        base.杂质偏差结论 = '正常';
        return base;
      }
      base.杂质偏差结论 = '正常';
      return base;
    }
    // 已定住：匹配到典型保留时间（对应典型保留时间有值）且未被判定为新杂
    function spectrumRowSettled(row){
      if(!row) return false;
      const tr = String(row.对应典型保留时间 || '').trim();
      if(!tr || tr === '—') return false;
      return String(row.是否新杂 || '') !== '是';
    }
    // 找参考峰：先按「已定性峰」确定方向（比较保留时间距离），再沿该方向取紧邻的可用峰作尺子
    //   1）方向侧按保留时间由近到远扫：遇到新杂 → 跳过继续；遇到未算完（无典型保留时间）→ 本轮阻塞，等它算完
    //   2）方向侧全被跳过（全新杂/无峰）→ 换反方向；仍无 → 返回空（本轮不处理）
    //   3）没有任何已定性峰时，左右各取最近可用峰比距离，等距取保留时间更小的一侧
    // usableNos：已算完且非新杂、可作尺子的峰号；qualifiedRows：已定性峰行；newImpNos：已判定为新杂的峰号
    function spectrumPickRefRow(row, rows, usableNos, qualifiedRows, newImpNos){
      const curRt = Number(row && row.谱图保留时间);
      if(!Number.isFinite(curRt)) return null;
      const curNo = String((row && row.谱图峰号) || '').trim();
      const cand = (rows || []).filter(r=>{
        if(!r) return false;
        const no = String(r.谱图峰号 || '').trim();
        if(!no || no === curNo) return false;
        return Number.isFinite(Number(r.谱图保留时间));
      });
      const sideScan = rightSide => {
        const list = cand
          .filter(r=> rightSide ? Number(r.谱图保留时间) > curRt : Number(r.谱图保留时间) < curRt)
          .sort((a, b)=> Math.abs(Number(a.谱图保留时间) - curRt) - Math.abs(Number(b.谱图保留时间) - curRt));
        for(const r of list){
          const no = String(r.谱图峰号 || '').trim();
          if(newImpNos && newImpNos.has(no)) continue;            // 新杂 → 跳过，继续朝同方向找
          if(!usableNos || !usableNos.has(no)) return { blocked: true, row: null };  // 未算完 → 等它算完
          return { blocked: false, row: r };
        }
        return { blocked: false, row: null };
      };
      // 1) 方向：离得最近的已定性峰
      const quals = (qualifiedRows || []).filter(r=> String((r && r.谱图峰号) || '').trim() !== curNo
        && Number.isFinite(Number(r && r.谱图保留时间)));
      if(quals.length){
        const q = quals.reduce((a, b)=> Math.abs(Number(b.谱图保留时间) - curRt) < Math.abs(Number(a.谱图保留时间) - curRt) ? b : a, quals[0]);
        const dirRight = Number(q.谱图保留时间) > curRt;
        const main = sideScan(dirRight);
        if(main.row) return main.row;
        if(main.blocked) return null;              // 方向侧有未算完的峰 → 本轮先跳过
        const other = sideScan(!dirRight);
        return other.row || null;
      }
      // 2) 无已定性峰：左右各取最近可用峰比距离，等距取左
      const l = sideScan(false), r2 = sideScan(true);
      if(l.row && r2.row){
        const dl = curRt - Number(l.row.谱图保留时间);
        const dr = Number(r2.row.谱图保留时间) - curRt;
        return dl <= dr ? l.row : r2.row;
      }
      return l.row || r2.row || null;
    }
    // 当前峰与参考峰之间紧挨着的那一个峰（朝参考峰方向的下一个峰）；新版方向式取尺已内联在 pick 中，此函数保留备用
    function spectrumNeighborTowards(row, refRow, rows){
      const curRt = Number(row && row.谱图保留时间);
      const refRt = Number(refRow && refRow.谱图保留时间);
      if(!Number.isFinite(curRt) || !Number.isFinite(refRt)) return null;
      const curNo = String((row && row.谱图峰号) || '').trim();
      const lo = Math.min(curRt, refRt);
      const hi = Math.max(curRt, refRt);
      const between = (rows || []).filter(r=>{
        if(!r || String(r.谱图峰号 || '').trim() === curNo) return false;
        const rt = Number(r.谱图保留时间);
        return Number.isFinite(rt) && rt > lo && rt < hi;
      });
      if(!between.length) return null;
      const sorted = between.slice().sort((a, b)=> Number(a.谱图保留时间) - Number(b.谱图保留时间));
      return refRt > curRt ? sorted[0] : sorted[sorted.length - 1];
    }
    // 自动推导参考峰：主峰为种子 → 每轮为未定住的峰取「最近已定住峰」作尺子 → 算完即加入种子，直到无进展
    // 手动指定的行不参与推导（冻结），数值最后用手动尺子覆盖；_autoRef 始终保留算法值，供「交回自动」恢复
    function spectrumAutoAssignRefs(rows, wins, newLim, mainTR, mainPeakNo, manualMap, lockedNos){
      const noOf = r=> String((r && r.谱图峰号) || '').trim();
      const mainNo = String(mainPeakNo || '').trim();
      const list = (rows || []).map(r=> Object.assign({}, r, { _autoRef: '', _refManual: false }));
      const apply = (row, refNo)=>{
        const calc = spectrumCalcRow(Object.assign({}, row, { 参考峰: refNo }), list, wins, newLim, mainTR, mainPeakNo);
        Object.assign(row, calc, { _autoRef: calc._qualified ? '' : refNo });
        return row;
      };
      // 第 0 轮：锁定峰保留页面原值（不重算、不重匹配），其余以主峰为基准，得到初始三类划分
      list.forEach(r=>{
        if(lockedNos && lockedNos.has(noOf(r))){ r._locked = true; return; }
        apply(r, mainNo);
      });
      const collect = ()=>{
        const usable = new Set();     // 可作尺子：已算完且非新杂
        const newImp = new Set();     // 新杂：跳过，不阻挡
        list.forEach(r=>{
          const no = noOf(r);
          if(!no) return;
          if(spectrumRowSettled(r)) usable.add(no);
          if(String(r.是否新杂 || '') === '是') newImp.add(no);
        });
        const quals = list.filter(r=> r._qualified);
        return { usable, newImp, quals };
      };
      // 逐轮扩散：每轮按「最近已定性峰定方向 → 沿该方向取紧邻可用峰」为未定住的峰找尺子
      const maxRound = Math.max(4, list.length * 4);
      for(let round = 0; round < maxRound; round++){
        let progressed = false;
        const ctx = collect();
        list.forEach(r=>{
          const no = noOf(r);
          if(!no || r._qualified || r._refManual || r._locked) return;
          if(ctx.usable.has(no)) return;      // 已定住的不在阶段 1 改，留到阶段 2 统一重取
          const ref = spectrumPickRefRow(r, list, ctx.usable, ctx.quals, ctx.newImp);
          if(!ref) return;                    // 方向侧有未算完的峰 → 本轮跳过，等下一轮
          const refNo = noOf(ref);
          if(String(r._autoRef || '') === refNo) return;
          apply(r, refNo);
          progressed = true;
        });
        if(!progressed) break;
      }
      // 阶段 2：扩散收敛后，按最终「已定住」集合为每一行重取参考峰（就近规则统一生效）
      // 阶段 1 只决定「哪些峰已定住」，参考峰仍是第 0 轮的主峰基准；这里统一改成就近尺子，
      // 否则参考峰列会全部显示主峰。用阶段 1 结束时的快照计算，保证结果与遍历顺序无关。
      const snap = list.map(r=> Object.assign({}, r));
      const ctx2 = {
        usable: new Set(snap.filter(r=> spectrumRowSettled(r)).map(noOf).filter(Boolean)),
        newImp: new Set(snap.filter(r=> String(r.是否新杂 || '') === '是').map(noOf).filter(Boolean)),
        quals: snap.filter(r=> r._qualified)
      };
      list.forEach((r, i)=>{
        if(r._refManual) return;
        if(r._locked) return;              // 锁定峰整体冻结
        if(r._qualified) return;           // 已定性 → 参考峰留空，不找尺子
        const no = noOf(r);
        if(!no || no === mainNo) return;   // 主峰作全局基准，参考峰保留自身
        const ref = spectrumPickRefRow(snap[i], snap, ctx2.usable, ctx2.quals, ctx2.newImp);
        if(!ref) return;
        const refNo = noOf(ref);
        if(String(r._autoRef || '') === refNo) return;
        const calc = spectrumCalcRow(Object.assign({}, snap[i], { 参考峰: refNo }), snap, wins, newLim, mainTR, mainPeakNo);
        Object.assign(r, calc, { _autoRef: refNo });
      });
      // 手动指定行：按手动参考峰覆盖数值（不影响 _autoRef，也不回溯其他行）
      list.forEach(r=>{
        const manual = manualMap ? manualMap[noOf(r)] : '';
        if(!manual) return;
        const calc = spectrumCalcRow(Object.assign({}, r, { 参考峰: String(manual), _refManual: true }), list, wins, newLim, mainTR, mainPeakNo);
        Object.assign(r, calc, { _refManual: true });
      });
      return list;
    }
    // 「对应典型保留时间」下拉选项：当前规则方案内已配置的典型保留时间（唯一值、升序），label 带定性结构
    function spectrumTROptions(curVal){
      const wins = spectrumWindows() || [];
      const map = new Map();
      wins.forEach(w=>{
        const tr = Number(w.典型保留时间);
        if(!Number.isFinite(tr)) return;
        const key = tr.toFixed(3);
        if(map.has(key)) return;
        const ds = String(w.定性结构 || '').trim();
        const mainTag = (w.是否主峰 && ds.indexOf('主峰') < 0) ? ' · 主峰' : '';
        map.set(key, { value: key, label: key + (ds ? '（' + ds + '）' : '') + mainTag });
      });
      const list = Array.from(map.values()).sort((a, b)=> Number(a.value) - Number(b.value));
      const cur = String(curVal == null ? '' : curVal).trim();
      // 当前值不在规则方案内（如重复匹配的多值、或规则已改）时补一项，避免下拉显示空白
      if(cur && !map.has(cur)) list.unshift({ value: cur, label: cur + '（当前值）' });
      return list;
    }
    // 手动选择「对应典型保留时间」：同步带出该时间对应的有效取值范围 / 定性结构 / 杂质指标
    function setSpectrumTypicalTR(row, val){
      if(!row) return;
      const rows = spectrumPeaks.value || [];
      const idx = rows.findIndex(r=> String(r.谱图峰号 || '') === String(row.谱图峰号 || ''));
      if(idx < 0) return;
      const v = String(val == null ? '' : val).trim();
      const wins = spectrumWindows() || [];
      const next = Object.assign({}, rows[idx]);
      if(!v){
        Object.assign(next, {
          对应典型保留时间: '',
          有效取值范围: '',
          对应定性结构: '',
          典型保留时间: next.典型保留时间 || '',
          是否锁定: '否',
          是否新杂: '是',
          杂质指标: '—',
          匹配异常说明: '未匹配到'
        });
      } else {
        const win = wins.find(w=> Number(w.典型保留时间).toFixed(3) === v);
        const struct = win ? (win.定性结构 || '') : '';
        Object.assign(next, {
          对应典型保留时间: v,
          有效取值范围: win ? (Number(win.下限).toFixed(4) + '~' + Number(win.上限).toFixed(4)) : '',
          对应定性结构: struct,
          检验项名称: String(next.检验项名称 || '').trim() || struct,
          典型保留时间: '',
          是否锁定: win && win.是否主峰 ? '是' : '否',
          是否新杂: '否',
          杂质指标: win ? spectrumImpIndexText(win) : '—',
          匹配异常说明: win ? '/' : '未匹配到'
        });
      }
      spectrumPeaks.value = rows.map((r, i)=> i === idx ? next : r);
      applySpectrumOrderAnomaly(spectrumPeaks.value);
      ElMessage.success('峰 ' + String(row.谱图峰号 || '') + (v ? (' 的对应典型保留时间已设为 ' + v) : ' 的对应典型保留时间已清空'));
    }
    // 顺序异常：跨行判断，任一行的参考峰/匹配结果变动后需整表重扫（仅刷新「顺序异常」标记）
    function applySpectrumOrderAnomaly(rows){
      let lastTr = null;
      (rows || []).forEach(r=>{
        if(!r) return;
        // 先清掉上一次的顺序异常标记，回到本行自身匹配结论
        if(r.匹配异常说明 === '顺序异常') r.匹配异常说明 = '/';
        const tr = r.对应典型保留时间 && r.对应典型保留时间 !== '—'
          ? driftNum(String(r.对应典型保留时间).split(',')[0]) : null;
        if(tr == null) return;
        if(lastTr != null && tr < lastTr && r.匹配异常说明 === '/') r.匹配异常说明 = '顺序异常';
        lastTr = tr;
      });
    }
    // 逐行改参考峰：选具体峰＝手动指定（本行冻结，不参与自动推导）；选「自动判定」＝交回算法
    function setSpectrumRefPeak(row, val){
      if(!row) return;
      const rows = spectrumPeaks.value || [];
      const idx = rows.findIndex(r=> String(r.谱图峰号 || '') === String(row.谱图峰号 || ''));
      if(idx < 0) return;
      const cur = rows[idx];
      const v = String(val || '').trim();
      const wins = spectrumWindows();
      let next;
      let msg;
      if(!v){
        // 交回自动判定：恢复自动推导给出的参考峰（算法值）；已定性的行保持为空，其余按当前整表就近取
        const noOf = r=> String((r && r.谱图峰号) || '').trim();
        let refNo = String(cur._autoRef || '').trim();
        if(!refNo && !cur._qualified){
          const usable = new Set();
          const newImp = new Set();
          rows.forEach(r=>{
            if(spectrumRowSettled(r)) usable.add(noOf(r));
            if(String(r.是否新杂 || '') === '是') newImp.add(noOf(r));
          });
          const quals = rows.filter(r=> r._qualified);
          const ref = spectrumPickRefRow(cur, rows, usable, quals, newImp);
          refNo = ref ? noOf(ref) : '';
        }
        next = Object.assign({}, cur, { 参考峰: refNo, _refManual: false });
        msg = '峰 ' + String(cur.谱图峰号 || '') + ' 已交回自动判定，参考峰＝峰 ' + (refNo || '—');
      } else {
        next = Object.assign({}, cur, { 参考峰: v, _refManual: true });
        const isMain = String(cur.是否主峰 || '') === '是' || String(cur.谱图峰号 || '') === v;
        msg = '峰 ' + String(cur.谱图峰号 || '') + ' 参考峰手动指定为峰 ' + v + (isMain ? '（主峰）' : '');
      }
      spectrumRefPeak.value = String(next.参考峰 || '');
      if(spectrumCalcDone.value && wins.length){
        const all = rows.map((r, i)=> i === idx ? next : Object.assign({}, r));
        const mainPeakNo = spectrumMainPeakNoOf(all);
        const mainWin = wins.find(w=> w.是否主峰) || wins[wins.length - 1];
        const mainTR = driftNum(mainWin && mainWin.典型保留时间);
        const calc = spectrumCalcRow(next, all, wins, spectrumDemoNewLimits(), mainTR, mainPeakNo);
        Object.assign(next, calc, { _autoRef: next._autoRef, _refManual: next._refManual });
      }
      spectrumPeaks.value = rows.map((r, i)=> i === idx ? next : r);
      applySpectrumOrderAnomaly(spectrumPeaks.value);
      if(!spectrumCalcDone.value || !wins.length){
        ElMessage.success(msg + '；点击「识别 + 计算」后按该参考峰计算相对保留时间');
      } else {
        ElMessage.success(msg + '，仅本行相对保留时间与匹配结果已重算');
      }
    }
    const spectrumNoteGroups = [
      { title: '数据备注 · 数据列表', items: [
        { no: '1', name: '数据源', desc: '1、点击【识别+计算】后，自动生成行数据' },
        { no: '2', name: '排序', desc: '1、根据「谱图保留时间」正序（由小 → 大）' },
      ]},
      { title: '数据备注 · 字段识别', items: [
        { no: '1', name: '谱图峰号', desc: '1、根据文件，识别自动填充，不可修改（编号）\n2、取文件积分结果表「序号」列（部分仪器为表格第一列），按顺序展示' },
        { no: '1-1', name: '字段映射', desc: '1、谱图峰号 ← 序号（表格第一列）\n2、谱图保留时间 ← 保留时间 min / 保留时间(分钟)\n3、谱图峰面积 ← 相对峰面积 % / %面积\n4、识别结果固定挂在该源文件下，重复识别结果一致' },
        { no: '2', name: '谱图保留时间', desc: '1、根据文件，识别自动填充，可修改，输入，数字' },
        { no: '3', name: '谱图峰面积', desc: '1、根据文件，识别自动填充，可修改，输入，数字' },
        { no: '3-1', name: '检验项名称', desc: '1、位于「谱图峰面积」右侧\n2、匹配到定性结构时自动带出；主峰无结构时按保留时间升序补「主峰1 / 主峰2…」\n3、只读，不可手工修改' },
        { no: '4', name: '是否主峰', desc: '1、自动判断：识别该数据内最大的「谱图峰面积」默认为「是」，其余默认均为「否」\n2、支持修改，下拉「是/否」，支持多主峰（支持选择多个主峰）' },
        { no: '5', name: '参考峰', desc: '1、先定方向：在「已定性」峰（是否主峰＝是，或唯一匹配到带定性结构的典型保留时间）中取保留时间离本行最近的那个，据此判断本行应朝左还是朝右找尺子\n   1）例：8 号峰已定性为主峰1，7 号峰用它作参考；6 号峰右侧最近的已定性峰仍是 8，故 6 号峰取紧邻的 7 号峰作参考\n   2）若 6 号峰左侧也存在已定性峰（如 3 号峰）且保留时间距离更近，则方向改为朝左，参考峰取紧邻的 5 号峰（不是直接跳到 3 号峰）\n2、再取尺子：沿该方向按保留时间由近到远扫，遇到已判定为新杂的峰跳过继续往外找；遇到还没算完（无典型保留时间）的峰则本轮先跳过、等它算完再来；取到的第一个可用峰即参考峰\n3、扩散收敛后整表按同一规则统一重取（以收敛末快照计算），结果与遍历顺序无关；主峰行保留自身作全局基准；已定性的行参考峰留空并标注「已定性」\n4、手动指定优先：下拉选具体峰＝手动指定该行参考峰（冻结、不参与自动推导、重新计算不覆盖）；选「自动判定」＝交回算法，恢复该行自动推导出的参考峰（已定性的行保持为空）\n5、参考峰的典型保留时间取该行「对应典型保留时间」首值；切换参考峰仅影响该行「相对保留时间」及其下游范围判断，不改变「是否主峰 / 是否锁定」；「顺序异常」为跨行判断，整表重扫' },
        { no: '6', name: '相对保留时间', desc: '1、自动计算，= 各「谱图保留时间」× 参考峰典型保留时间 ÷ 参考峰谱图保留时间\n   1）参考峰：由「参考峰」字段给出（自动推导或手动指定）；参考峰自身的相对保留时间＝其典型保留时间\n2、计算完成后，支持手动修改，数字\n3、计算完成后，逐一比对该值是否落在「对应典型保留时间」的有效取值范围内' },
        { no: '7', name: '对应典型保留时间', desc: '1、范围判断（匹配前置条件）：先判断本峰的相对保留时间是否落在「漂移规则设置」内某一典型保留时间的有效取值范围（= 典型保留时间 − 偏差量 ~ 典型保留时间 + 偏差量）内\n   1）不在任何有效取值范围内：该峰不参与自动匹配，本字段为空，匹配异常说明＝「超出有效范围」，是否新杂默认「是」\n   2）落在有效取值范围内：仅在命中的范围内执行下述自动匹配\n2、是否主峰：\n   1）是（主峰）：自动匹配「漂移规则设置」内主峰典型保留时间；且「是否锁定」默认为「是」\n   2）否（非主峰）：\n      a. 已定性结构：若谱图内已存在定性结构名称，且「漂移规则设置」内也存在此定性结构名称，自动匹配对应的典型保留时间；且「是否锁定」默认为「是」\n      b. 非已定性结构：下拉手动选择，选项为当前规则方案内已配置的典型保留时间（同时显示对应定性结构，主峰项标注「主峰」）；选中后自动带出该时间的有效取值范围、对应定性结构与杂质指标，是否新杂置「否」；清空则该行按「未匹配到」处理（有效范围与定性结构清空、是否新杂置「是」）' },
        { no: '8', name: '有效取值范围', desc: '1、根据匹配到的典型保留时间，按「漂移规则设置 · RRT&TR偏差规则」中命中的时间范围与差值范围计算（典型保留时间 ± 差值）\n2、未匹配到（含超出有效范围）时为空' },
        { no: '9', name: '对应定性结构', desc: '1、谱图内已存在化学式名称\n   1）自动将谱图内的化学式名称进行填充\n2、只读展示，不可手工修改：值由匹配到的典型保留时间自动带出；在「对应典型保留时间」下拉切换后同步刷新' },
        { no: '9-1', name: '典型保留时间', desc: '1、位于「对应定性结构」右侧；与「对应典型保留时间」不同\n2、仅「是否新杂＝是」时可手工输入数字（占位「输入，数字」）\n3、非新杂时不可填（占位「非新杂不可填」），匹配成功后本字段清空' },
        { no: '10', name: '是否锁定', desc: '1、主峰：默认为「是」，不可修改\n2、谱图内存在已定性结构，且台账内也存在此定性结构：默认为「是」，不可修改\n3、锁定后，点击重新计算时该峰整体冻结：对应典型保留时间不重新匹配，参考峰与相对保留时间也保持不变，仅作为其他峰的尺子' },
        { no: '11', name: '是否新杂', desc: '1、自动匹配，可修改\n2、超出有效取值范围而未参与匹配的峰，默认「是」' },
        { no: '12', name: '杂质指标', desc: '1、匹配到典型保留时间：带入该杂质的 UCL/LCL\n2、未匹配到：带入「漂移规则设置」的新杂质项目通用指标' },
        { no: '13', name: '新杂偏差结论', desc: '1、若为新杂，则根据「预警设置」的 UCL/LCL 进行判断，若超出则为「是」，否则为「否」\n2、若非新杂，则不判断，显示「/」' },
      ]},
      { title: '状态备注 · 匹配异常说明', items: [
        { no: '1', name: '异常说明', desc: '1、超出有效范围：相对保留时间不在任何典型保留时间的有效取值范围内，该峰不参与自动匹配，对应典型保留时间/对应定性结构为空，是否新杂默认为「是」\n2、未匹配到：有效取值范围内已无可用候选（如候选均被锁定峰占用），对应典型保留时间为空\n3、重复匹配：两个或两个以上，对应典型保留时间重复，保留时间拼接展示\n4、顺序异常：当前峰的对应典型保留时间，小于上一峰的对应典型保留时间\n5、/：匹配到唯一一个，或手动更改后匹配到唯一一个对应典型保留时间' },
      ]},
      { title: '功能备注', items: [
        { no: '1', name: '识别+计算', desc: '1、上述基本信息必须全部存在值，才可点击，否则不可点击\n2、点击完成后，自动填充下述的色谱识别信息的数据列表内\n3、计算顺序：① 主峰为种子，全表先按主峰基准算一轮，得到「已定住 / 已定性 / 新杂」三类划分；② 逐轮为未定的峰找尺子——先在已定性峰里取保留时间最近者定方向，再沿该方向由近到远取紧邻的可用峰（新杂跳过、未算完的本轮等）；③ 按尺子算相对保留时间并判断落在哪条典型保留时间的有效取值范围内；④ 命中即定住、加入下一轮可用的尺子集合；⑤ 收敛后整表按同一规则统一重取参考峰\n4、超出有效范围的峰不进入自动匹配，最终无匹配结果值' },
        { no: '2', name: '重新计算', desc: '1、校验：锁定峰的对应典型保留时间不可重复（已判为新增列的锁定峰不占用列）；重复时拦截并提示具体值，不执行计算\n2、以页面当前数据为基准，不重新读取源文件；未锁定的峰清空上次结果（是否新杂 / 对应典型保留时间 / 相对保留时间 / 参考峰 / 对应定性结构）后重新推导\n3、例外：未锁定峰中「已有组分名且本来就是新增列」的结果留着、不再换算；但若它的名字能对上台账、或被选为本次主峰，仍按台账那一列重新钉一次\n4、主峰只在未锁定的峰里找：先取组分名带「主峰」的，没有再取浓度（谱图峰面积）最大的；全部峰都锁定时没有主峰，重算停止并提示「浓度为空或主峰不存在」\n5、锁定峰按锁定前性质继续约束其他峰：① 无组分名且非新增列 → 可当尺子、占用就近列；② 有组分名但非新增列 → 改记成新增列、不能当尺子、原就近列仍占用；③ 已是新增列 → 不占用列、不能当尺子，别的峰越过它继续往外找尺子\n6、收尾：锁定峰的参考峰清空（参考关系仍在，只是不再显示最后拿哪一峰做除法）；仍有就近时间的锁定峰做一次顺序检查，若小于前面某个非新增列的时间则改判新增列、时间收 4 位小数，没有就近时间的锁定峰不再改数字\n7、台账按当前所选规则方案重新取；该台账已不存在时提示「未匹配到对应的数据台账」' },
        { no: '3', name: '保存校验', desc: '1、对应典型保留时间有值的组分峰，不可为新杂' },
        { no: '4', name: '保存', desc: '1、按固定值不叠加：生成数据台账，且不增加典型保留时间\n2、按批次新杂滚动叠加：生成数据台账同时，需将本次新杂项目自动添加至典型保留时间内展示\n3、首批次新杂滚动增加，其余批次不叠加：判断该批次是否为数据台账内的首批次数据，若是，将本次新杂项目自动添加至典型保留时间内；若否，则不添加' },
      ]},
    ];
    function specTagStyle(t){
      const m = {
        primary: { background: '#e8f0fa', color: '#004098' },
        warning: { background: '#fff7e6', color: '#d46b08' },
        success: { background: '#f6ffed', color: '#389e0d' },
        info: { background: '#f2f3f5', color: '#4e5969' },
        danger: { background: '#fff1f0', color: '#f5222d' },
      };
      return m[t] || m.info;
    }

    function spectrumImpIndexText(win){
      if(!win) return '—';
      const ucl = String(win.UCL==null?'':win.UCL).trim();
      const lcl = String(win.LCL==null?'':win.LCL).trim();
      if(!ucl && !lcl) return '—';
      return (ucl?('UCL<' + ucl):'') + (ucl && lcl?'，':'') + (lcl?('LCL>' + lcl):'');
    }

    // 识别核心（纯计算，不依赖表单）：按源文件积分结果 + 规则方案算出峰表；供「识别 + 计算」与列表「详情」懒生成峰表共用
    function spectrumRuleWindowsOf(ruleName){
      const rule = spectrumRuleByName(ruleName);
      return (rule && driftRuleWindows(rule)) || [];
    }
    function spectrumWindows(ruleName){
      // 未选择规则方案 / 规则未维护典型保留时间明细时不参与自动匹配（不再用演示窗口兜底）
      const nm = arguments.length ? ruleName : formModel['漂移规则'];
      return spectrumRuleWindowsOf(nm);
    }
    function spectrumDemoNewLimits(ruleName){
      const nm = arguments.length ? ruleName : formModel['漂移规则'];
      const rule = spectrumRuleByName(nm);
      const ucl = driftNum(rule && rule._newUCL);
      const lcl = driftNum(rule && rule._newLCL);
      return { ucl: ucl==null?0.12:ucl, lcl: lcl==null?0.10:lcl };
    }
    // 源文件解析出的积分结果（固定挂在文件台账行 `_peaks` 上）：序号 / 保留时间 / 相对峰面积%
    function spectrumSourcePeaks(fileId){
      const f = spectrumFileById(arguments.length ? fileId : formModel._srcFileId);
      const rows = (f && Array.isArray(f._peaks)) ? f._peaks : [];
      return rows.map(p=> ({
        谱图峰号: String(p.序号 == null ? '' : p.序号),
        谱图保留时间: Number(p.保留时间),
        谱图峰面积: Number(p.相对峰面积 == null ? p.峰面积 : p.相对峰面积)
      })).filter(p=> Number.isFinite(p.谱图保留时间) && Number.isFinite(p.谱图峰面积));
    }
    function spectrumComputeRows(peaks, ruleName, manualMap){
      const mainPeak = peaks.reduce((a,b)=> b.谱图峰面积 > a.谱图峰面积 ? b : a, peaks[0]);
      const mainPeakNo = String(mainPeak.谱图峰号 || '');
      const wins = spectrumWindows(ruleName);
      const baseRows = peaks.map(p=> ({
        谱图峰号: String(p.谱图峰号 || ''),
        谱图保留时间: Number(p.谱图保留时间),
        谱图峰面积: Number(p.谱图峰面积),
        检验项名称: String(p.检验项名称 || '').trim(),
        是否主峰: p === mainPeak ? '是' : '否',
        参考峰: '',
        相对保留时间: '—',
        对应典型保留时间: '',
        对应定性结构: '',
        典型保留时间: String(p.典型保留时间 || '').trim(),
        有效取值范围: '',
        是否锁定: '否',
        是否新杂: '否',
        杂质指标: '—',
        杂质偏差结论: '—',
        匹配异常说明: '/',
        _rrt: null
      }));
      // 未匹配到规则方案：仅回填识别结果，不对匹配类字段做任何推断
      if(!wins.length){
        const rows = baseRows.map(r=> Object.assign(r, {
          参考峰: (manualMap && manualMap[r.谱图峰号]) || mainPeakNo,
          相对保留时间: '—',
          对应典型保留时间: '—',
          对应定性结构: '—',
          典型保留时间: '',
          有效取值范围: '—',
          是否锁定: '否',
          是否新杂: '—',
          杂质指标: '—',
          杂质偏差结论: '—',
          匹配异常说明: '未匹配到规则方案',
          _rrt: null,
          _autoRef: mainPeakNo,
          _refManual: !!(manualMap && manualMap[r.谱图峰号])
        }));
        return { rows, noRule: true, mainPeakNo };
      }
      const mainWin = wins.find(w=> w.是否主峰) || wins[wins.length - 1];
      const mainTR = driftNum(mainWin && mainWin.典型保留时间);
      const newLim = spectrumDemoNewLimits(ruleName);
      // 参考峰自动推导：主峰为种子 → 未定住的峰取「最近已定住峰」作尺子 → 算完即加入种子集合，逐轮扩散
      const rows = spectrumAutoAssignRefs(baseRows, wins, newLim, mainTR, mainPeakNo, manualMap || {});
      applySpectrumOrderAnomaly(rows);
      fillSpectrumItemNames(rows);
      return { rows, noRule: false, mainPeakNo };
    }
    // 主峰行无检验项名称时补「主峰1 / 主峰2…」（按谱图保留时间升序）
    function fillSpectrumItemNames(rows){
      let n = 0;
      (rows || []).slice().sort((a, b)=> (Number(a.谱图保留时间) || 0) - (Number(b.谱图保留时间) || 0)).forEach(r=>{
        if(String(r.是否主峰 || '') !== '是') return;
        if(String(r.检验项名称 || '').trim()) return;
        n += 1;
        r.检验项名称 = '主峰' + n;
      });
      (rows || []).forEach(r=>{
        if(String(r.检验项名称 || '').trim()) return;
        const struct = String(r.对应定性结构 || '').trim();
        if(struct && struct !== '—') r.检验项名称 = struct;
      });
    }
    function runSpectrumCalc(){
      spectrumNoRule.value = false;
      const peaks = spectrumSourcePeaks();
      if(!peaks.length){
        ElMessage.warning('请先选择源文件（图谱文件台账）：未读取到该文件的积分结果（峰号 / 保留时间 / 相对峰面积）');
        return;
      }
      // 手动指定的参考峰（上一轮指定过、且参考峰号仍存在于本次识别结果内）：作为锚点保留，重算不覆盖
      const manualMap = {};
      (spectrumPeaks.value || []).forEach(r=>{
        if(!r || !r._refManual) return;
        const no = String(r.谱图峰号 || '').trim();
        const ref = String(r.参考峰 || '').trim();
        if(no && ref && peaks.find(x=> String(x.谱图峰号 || '') === ref)) manualMap[no] = ref;
      });
      const res = spectrumComputeRows(peaks, formModel['漂移规则'], manualMap);
      spectrumRefPeak.value = res.mainPeakNo;
      spectrumPeaks.value = res.rows;
      spectrumCalcDone.value = true;
      spectrumNoRule.value = res.noRule;
      if(res.noRule){
        ElMessage.warning('已识别 ' + peaks.length + ' 个峰；未匹配到规则方案（需选择物料与色谱柱型号，或维护对应漂移规则）');
        return;
      }
      const outCount = res.rows.filter(r=> r.匹配异常说明==='超出有效范围').length;
      const settledCount = res.rows.filter(r=> spectrumRowSettled(r)).length;
      ElMessage.success('已识别 ' + res.rows.length + ' 个峰并完成相对保留时间计算（参考峰自动推导，' + settledCount + ' 个峰已定住，' + outCount + ' 个峰超出有效取值范围）');
    }

    // 重新计算（锁定版）：以页面当前数据为基准，只重算未锁定的峰；
    // 锁定峰保留已确认结果、按锁定前性质继续约束其他峰（当尺子 / 占用就近列），收尾再清参考峰与做顺序检查
    function recalcSpectrum(){
      const cur = (spectrumPeaks.value || []).map(r=> Object.assign({}, r));
      if(!cur.length){ ElMessage.warning('请先点击「识别 + 计算」生成识别结果'); return; }
      const wins = spectrumWindows();
      if(!wins.length){
        ElMessage.warning('未匹配到对应的数据台账（当前规则方案内没有可用的典型保留时间配置），无法重新计算');
        return;
      }
      const noOf = r=> String((r && r.谱图峰号) || '').trim();
      const isLocked = r=> String(r.是否锁定 || '') === '是';
      const isNew = r=> String(r.是否新杂 || '') === '是';
      const nameOf = r=> String((r && (r.检验项名称 || r.对应定性结构)) || '').trim();
      const trOf = r=> String(r.对应典型保留时间 || '').trim();
      const numOr = (v, d)=> Number.isFinite(Number(v)) ? Number(v) : d;

      // ① 锁定峰占用的「就近列」不可重复（已经是新增列的锁定峰不占列）
      const usedTR = new Set();
      const dup = [];
      cur.filter(r=> isLocked(r) && !isNew(r)).forEach(r=>{
        const tr = trOf(r);
        if(!tr || tr === '—') return;
        if(usedTR.has(tr)) dup.push(tr); else usedTR.add(tr);
      });
      if(dup.length){
        ElMessage.error('锁定峰的对应典型保留时间不可重复（' + Array.from(new Set(dup)).join('、') + '），请先调整后再重新计算');
        return;
      }

      // ② 主峰只在未锁定的峰里找：先取组分名带「主峰」的，没有再取浓度（峰面积）最大的
      const unlocked = cur.filter(r=> !isLocked(r));
      if(!unlocked.length){
        ElMessage.warning('浓度为空或主峰不存在（所有峰都已锁定，选不出主峰），重新计算已停止');
        return;
      }
      const namedMain = unlocked.filter(r=> nameOf(r).indexOf('主峰') >= 0);
      const pool = namedMain.length ? namedMain : unlocked;
      const mainRow = pool.reduce((a, b)=> numOr(b.谱图峰面积, 0) > numOr(a.谱图峰面积, 0) ? b : a, pool[0]);
      const mainPeakNo = noOf(mainRow);
      // 主峰的基准值：优先按它的组分名在台账里对到的那一列；对不上再用台账主峰列
      const mainWinNamed = nameOf(mainRow)
        ? wins.find(w=> String(w.定性结构 || '').trim() === nameOf(mainRow))
        : null;
      const mainWin = mainWinNamed || wins.find(w=> w.是否主峰) || wins[wins.length - 1];
      const mainTR = driftNum(mainWin && mainWin.典型保留时间);
      const newLim = spectrumDemoNewLimits();

      // ③ 未锁峰的保留例外：已有组分名且本来就是新增列 → 结果留着、不再换算
      //    但若它名字能对上台账、或它被选为本次主峰 → 按台账重新钉一次（走正常计算）
      const winByName = name => name ? wins.find(w=> String(w.定性结构 || '').trim() === name) : null;
      const preserved = new Map();
      cur.filter(r=> !isLocked(r) && nameOf(r) && isNew(r)).forEach(r=>{
        const no = noOf(r);
        const canRepin = !!winByName(nameOf(r)) || no === mainPeakNo;
        if(!canRepin) preserved.set(no, r);
      });

      // ④ 参与计算的行：未锁定且非保留（清空重算） + 全部锁定行（沿用页面值）
      const blank = r=> ({
        谱图峰号: noOf(r),
        谱图保留时间: numOr(r.谱图保留时间, 0),
        谱图峰面积: numOr(r.谱图峰面积, 0),
        检验项名称: String(r.检验项名称 || '').trim(),
        是否主峰: noOf(r) === mainPeakNo ? '是' : '否',
        参考峰: '',
        相对保留时间: '—',
        对应典型保留时间: '',
        对应定性结构: '',
        典型保留时间: String(r.是否新杂 || '') === '是' ? String(r.典型保留时间 || '').trim() : '',
        有效取值范围: '',
        是否锁定: '否',
        是否新杂: '否',
        杂质指标: '—',
        杂质偏差结论: '—',
        匹配异常说明: '/',
        _rrt: null,
        _qualified: false
      });
      const calcRows = [];
      const lockedNos = new Set();
      cur.forEach(r=>{
        const no = noOf(r);
        if(isLocked(r)){
          const b = Object.assign({}, r, { _locked: true, 是否主峰: '否', _rrt: driftNum(r.相对保留时间) });
          if(isNew(r)){
            b._lockKind = 'new';       // 已是新增列：不占就近列、不能当尺子
          } else if(nameOf(r)){
            b.是否新杂 = '是';          // 有组分名但不是新增列 → 改记成新增列，不能当尺子，就近列仍占用
            b._lockKind = 'named';
          } else {
            b._lockKind = 'plain';     // 无组分名、非新增列 → 可当尺子，就近列占用
          }
          calcRows.push(b);
          lockedNos.add(no);
          return;
        }
        if(preserved.has(no)) return;
        calcRows.push(blank(r));
      });

      // ⑤ 按方向式规则重推参考峰与匹配（锁定行冻结）
      const manualMap = {};
      cur.forEach(r=>{
        if(!isLocked(r) && r._refManual && String(r.参考峰 || '').trim()){
          manualMap[noOf(r)] = String(r.参考峰).trim();
        }
      });
      const rows = spectrumAutoAssignRefs(calcRows, wins, newLim, mainTR, mainPeakNo, manualMap, lockedNos);

      // ⑥ 合并保留行（原样回填，保持原行序）
      const byNo = new Map(rows.map(r=> [noOf(r), r]));
      const merged = cur.map(r=> preserved.has(noOf(r)) ? Object.assign({}, r) : (byNo.get(noOf(r)) || r));

      // ⑦ 收尾：锁定峰清空「参考峰」（参考关系仍在，只是不再显示最后拿哪一峰做除法）；
      //    仍有就近时间的锁定峰做一次顺序检查——小于前面某个非新增列的时间时，改判新增列并收 4 位小数
      const finalRows = merged.map(r=> Object.assign({}, r));
      finalRows.forEach(r=>{ if(isLocked(r)) r.参考峰 = ''; });
      let lastTR = null;
      finalRows.forEach(r=>{
        const tr = driftNum(trOf(r));
        if(tr == null) return;
        if(isLocked(r) && lastTR != null && tr < lastTR){
          r.是否新杂 = '是';
          r.对应典型保留时间 = Number(tr).toFixed(4);
        }
        if(String(r.是否新杂 || '') !== '是') lastTR = tr;
      });
      applySpectrumOrderAnomaly(finalRows);
      fillSpectrumItemNames(finalRows);
      spectrumPeaks.value = finalRows;
      spectrumCalcDone.value = true;
      spectrumNoRule.value = false;
      const outCount = finalRows.filter(r=> r.匹配异常说明 === '超出有效范围').length;
      ElMessage.success('已按页面当前数据重新计算（仅重算未锁定峰，锁定峰 ' + lockedNos.size + ' 个保留原结果），' +
        (finalRows.length - outCount) + ' 个峰参与匹配，' + outCount + ' 个峰超出有效取值范围');
    }
    function resetSpectrumCalc(){ spectrumPeaks.value = []; spectrumCalcDone.value = false; spectrumNoRule.value = false; spectrumNoteVisible.value = true; spectrumRefPeak.value = ''; }

// ===== 图谱识别 · 源文件（MOCK['spectrum-file'] 图谱文件台账）=====
    // 图谱文件一次上传一条记录；被图谱识别任务引用后置「已使用」，不可被再次选择
    const specFilePickVisible = ref(false);
    const specFilePickId = ref('');
    const specFileKw = ref('');
    const specFileStatus = ref('未使用');
    const specFilePreviewVisible = ref(false);
    const specFilePreviewRow = ref(null);
    const qrSpecPreviewVisible = ref(false);
    const qrSpecPreviewSampleNo = ref('');
    const qrSpecPreviewFiles = ref([]);

    function spectrumFileRows(){
      return (((MOCK['spectrum-file'] || {}).main) || []).slice();
    }
    function specPeaksOf(row){
      const list = (row && Array.isArray(row._peaks)) ? row._peaks : [];
      return list.map(p=> ({
        峰号: String(p.序号 == null ? '' : p.序号),
        保留时间: Number(p.保留时间),
        相对峰面积: Number(p.相对峰面积 == null ? p.峰面积 : p.相对峰面积)
      })).filter(p=> Number.isFinite(p.保留时间));
    }
    function specPolylineOf(row, height){
      const list = specPeaksOf(row);
      if(!list.length) return '';
      const h = height || 190;
      const maxRt = Math.max(...list.map(p=> p.保留时间)) || 1;
      const maxA = Math.max(...list.map(p=> p.相对峰面积)) || 1;
      const X = rt => 40 + (rt / maxRt) * 660;
      const Y = a => h - Math.max(3, Math.sqrt(Math.max(a, 0) / maxA) * (h - 45));
      const pts = ['40,'+h];
      list.forEach((p, i)=>{
        const x = X(p.保留时间), y = Y(p.相对峰面积);
        const nextX = (i < list.length - 1) ? X(list[i + 1].保留时间) : 700;
        const half = Math.max(2.5, (nextX - x) * 0.18);
        pts.push((x - half).toFixed(1) + ',' + h);
        pts.push(x.toFixed(1) + ',' + y.toFixed(1));
        pts.push((x + half).toFixed(1) + ',' + h);
      });
      pts.push('700,'+h);
      return pts.join(' ');
    }
    function qrIssueSampleSpectra(row){
      const no = String((row && row['样品编号']) || '').trim();
      const lot = String((row && row['物料批号']) || '').trim();
      const files = spectrumFileRows();
      let list = files.filter(f=> {
        const sn = String(f['样本编号'] || f['样品编号'] || '').trim();
        return no && sn && sn === no;
      });
      if(!list.length && lot){
        list = files.filter(f=> String(f['批号'] || '').trim() === lot);
      }
      if(!list.length && files.length){
        list = files.slice(0, Math.min(3, files.length)).map((f, i)=> Object.assign({}, f, {
          id: String(f.id || 'sf') + '-qr-' + (no || 'x') + '-' + i,
          样本编号: no || f['样本编号'] || '',
          批号: lot || f['批号'] || '',
          _demoBound: true
        }));
      }
      return list;
    }
    function openQrIssueSpecPreview(row){
      const no = String((row && row['样品编号']) || '').trim();
      if(!no){ ElMessage.warning('请先选择样品编号'); return; }
      qrSpecPreviewSampleNo.value = no;
      qrSpecPreviewFiles.value = qrIssueSampleSpectra(row);
      qrSpecPreviewVisible.value = true;
    }
    const SPECTRUM_LEDGER_UPLOAD_DEMOS = [
      { name:'TL-A026 25I27-15-熔料 M 客户方法.pdf', mat:'OLED-HOST-BL-01', lot:'25I27-15', col:'P-7101B', inst:'EQ-HPLC-01', path:'/data/LIMS/图谱/HPLC3/TL-A026 25I27-15-熔料 M 客户方法.pdf' },
      { name:'TL-A026 25I27-16-熔料 M 客户方法.pdf', mat:'OLED-HOST-BL-01', lot:'25I27-16', col:'P-7101B', inst:'EQ-HPLC-01', path:'/data/LIMS/图谱/HPLC3/TL-A026 25I27-16-熔料 M 客户方法.pdf' },
      { name:'HPLC-2.pdf', mat:'OLED-HOST-RD-01', lot:'20250412', col:'BEH-C18-130A', inst:'EQ-HPLC-01', path:'/data/LIMS/图谱/品质/HPLC/HPLC-2.pdf' },
      { name:'HPLC-3.pdf', mat:'OLED-DOP-BL-01', lot:'20250416', col:'Amide-1.7', inst:'EQ-HPLC-01', path:'/data/LIMS/图谱/品质/HPLC/HPLC-3.pdf' },
      { name:'HPLC-4.pdf', mat:'OLED-DOP-RD-01', lot:'20250418', col:'Gow-mac592', inst:'EQ-HPLC-01', path:'/data/LIMS/图谱/品质/HPLC/HPLC-4.pdf' }
    ];
    function pickSpectrumLedgerUpload(){
      const used = new Set((((MOCK['spectrum-file']||{}).main)||[]).map(r=> String(r['文件名']||'')));
      const hit = SPECTRUM_LEDGER_UPLOAD_DEMOS.find(d=> !used.has(d.name)) || SPECTRUM_LEDGER_UPLOAD_DEMOS[0];
      if(!hit){ ElMessage.warning('暂无可选演示文件'); return; }
      const src = spectrumFileRows().find(r=> r['文件名']===hit.name) || {};
      formModel['上传文件'] = hit.name;
      formModel['文件名'] = hit.name;
      formModel['文件路径'] = hit.path || src['文件路径'] || ('/data/LIMS/图谱/' + hit.name);
      formModel['物料编码'] = hit.mat;
      formModel['批号'] = hit.lot;
      formModel['仪器编号'] = hit.inst;
      formModel['色谱柱型号'] = hit.col;
      formModel['上传时间'] = nowStamp().slice(0, 16);
      formModel._peaks = Array.isArray(src._peaks) ? JSON.parse(JSON.stringify(src._peaks)) : [];
      formModel['图谱使用状态'] = '未使用';
      ElMessage.success('Demo：已选择文件「'+hit.name+'」并自动带出字段');
    }
    function saveSpectrumFileForm(){
      const fields = activeFormFields.value || [];
      if(!qcCheckRequired(fields)) return;
      if(!String(formModel['文件名']||'').trim()){ ElMessage.warning('请先上传文件'); return; }
      const bag = (MOCK['spectrum-file'] = MOCK['spectrum-file'] || {});
      const list = (bag.main = bag.main || []);
      const name = String(formModel['文件名']||'').trim();
      if(list.some(r=> String(r['文件名']||'')===name)){ ElMessage.warning('文件名「'+name+'」已存在'); return; }
      const row = {
        id: 'sf-' + Date.now().toString(36),
        图谱使用状态: '未使用',
        物料编码: formModel['物料编码'] || '',
        批号: formModel['批号'] || '',
        仪器编号: formModel['仪器编号'] || '',
        色谱柱型号: formModel['色谱柱型号'] || '',
        上传时间: formModel['上传时间'] || nowStamp().slice(0, 16),
        文件名: name,
        文件路径: formModel['文件路径'] || '',
        样本编号: formModel['样本编号'] || '',
        _peaks: Array.isArray(formModel._peaks) ? JSON.parse(JSON.stringify(formModel._peaks)) : []
      };
      list.unshift(row);
      formVisible.value = false;
      bumpStore();
      ElMessage.success('已新增图谱文件，可在谱图识别中选择');
    }
    function spectrumFileById(fileId){
      const id = String(fileId || '').trim();
      if(!id) return null;
      return (((MOCK['spectrum-file'] || {}).main) || []).find(r=> String(r.id || '') === id) || null;
    }
    function spectrumFileStatusOf(row){
      return String((row && row['图谱使用状态']) || '未使用') === '已使用' ? '已使用' : '未使用';
    }
    const spectrumFilePickRows = computed(()=>{
      storeTick.value;
      const kw = String(specFileKw.value || '').trim().toLowerCase();
      const st = String(specFileStatus.value || '').trim();
      return spectrumFileRows()
        .filter(r=> !st || spectrumFileStatusOf(r) === st)
        .sort((a, b)=> (spectrumFileStatusOf(a) === '未使用' ? 0 : 1) - (spectrumFileStatusOf(b) === '未使用' ? 0 : 1))
        .filter(r=>{
          if(!kw) return true;
          const text = [r['文件名'], r['物料编码'], r['批号'], r['仪器编号'], r['色谱柱型号'], r['文件路径']]
            .map(v=> String(v || '')).join(' ');
          return text.toLowerCase().includes(kw);
        });
    });
    function openSpectrumFilePick(){
      if(formMode.value==='detail') return;
      if(!String(formModel['检验类型'] || '').trim()){
        ElMessage.warning('请先选择检验类型，再选择源文件');
        return;
      }
      specFileKw.value = '';
      specFileStatus.value = '未使用';
      specFilePickId.value = String(formModel._srcFileId || '');
      specFilePickVisible.value = true;
    }
    function onSpectrumFileRowPick(row){
      if(!row) return;
      if(spectrumFileStatusOf(row) === '已使用'){ ElMessage.warning('该图谱文件已被使用，不可重复选择'); return; }
      specFilePickId.value = String(row.id || '');
    }
    // 预览弹窗：按文件固定的 _peaks 生成谱图与峰表（同一文件每次一致）
    const specPreviewPeaks = computed(()=> specPeaksOf(specFilePreviewRow.value));
    const specPreviewPolyline = computed(()=> specPolylineOf(specFilePreviewRow.value, 220));
    function previewSpectrumFile(row){
      if(!row) return;
      specFilePreviewRow.value = row;
      specFilePreviewVisible.value = true;
    }
    function confirmSpectrumFilePick(){
      const row = spectrumFileRows().find(r=> String(r.id || '') === String(specFilePickId.value || ''));
      if(!row){ ElMessage.warning('请选择一条源文件'); return; }
      if(spectrumFileStatusOf(row) === '已使用'){ ElMessage.warning('该图谱文件已被使用，不可重复选择'); return; }
      applySpectrumSourceFile(row);
      specFilePickVisible.value = false;
    }
    // 选中源文件 → 文件名称 / 批号 / 仪器编号+仪器名称 / 色谱柱型号 / 物料四要素
    function applySpectrumSourceFile(row){
      if(!row) return;
      formModel._srcFileId = String(row.id || '');
      formModel['源文件'] = row['文件名'] || '';
      formModel['文件名称'] = row['文件名'] || '';
      formModel['批号'] = row['批号'] || '';
      formModel['仪器编号'] = row['仪器编号'] || '';
      const inst = (((MOCK['instrument'] || {}).main) || [])
        .find(r=> String(r['仪器编号'] || '') === String(row['仪器编号'] || ''));
      formModel['仪器名称'] = inst ? (inst['仪器名称'] || '') : '';
      formModel['色谱柱型号'] = row['色谱柱型号'] || '';
      const matCode = String(row['物料编码'] || '').trim();
      if(matCode){
        formModel._matFromFile = '1';
        formModel['物料编码'] = matCode;
        fillSpectrumMaterial(matCode);
      } else {
        // 源文件无物料信息：物料编码改由手动选择，其余三项仍按所选编码自动带出
        formModel._matFromFile = '';
        formModel['物料编码'] = '';
        formModel['物料名称'] = '';
        formModel['物料规格'] = '';
        formModel['物料种类'] = '';
      }
      if(!spectrumColumnCodeOptions().includes(String(formModel['色谱柱编号'] || '').trim())) formModel['色谱柱编号'] = '';
      syncSpectrumDriftName();
    }
    function spectrumMatByCode(matCode){
      const code = String(matCode || '').trim();
      if(!code) return null;
      const m = (((MOCK['mat-list'] || {}).main) || []).find(r=> String(r['物料编码'] || '') === code);
      if(m) return m;
      // 漂移规则「适用物料」里维护但物料列表尚未建档的编码：回落规则内的物料名称
      for(const r of driftRowsOf()){
        const hit = (r._mats || []).find(x=> String(x['物料编码'] || '') === code);
        if(hit) return { 物料编码: code, 物料名称: hit['物料名称'] || '', 物料规格: hit['物料规格'] || '', 物料种类: hit['物料种类'] || '' };
      }
      return null;
    }
    function fillSpectrumMaterial(matCode){
      const m = spectrumMatByCode(matCode);
      formModel['物料名称'] = m ? (m['物料名称'] || '') : '';
      formModel['物料规格'] = m ? (m['物料规格'] || '') : '';
      formModel['物料种类'] = m ? (m['物料种类'] || '') : '';
      return m;
    }
    // 色谱柱编号候选：按所选型号过滤色谱柱台账（报废柱不可选）
    function spectrumColumnCodeOptions(){
      const model = String(formModel['色谱柱型号'] || '').trim();
      if(!model) return [];
      return colRowsOf()
        .filter(r=> String(r['色谱柱型号'] || '').trim() === model && String(r['使用状态'] || '') !== '报废')
        .map(r=> String(r['色谱柱编号'] || '').trim())
        .filter(Boolean);
    }
    // 漂移规则匹配：物料编码命中 + 色谱柱型号命中（未选型号时仅按物料匹配）；仅启用规则，创建时间倒序
    // 漂移规则匹配（沿用 driftMatchRules：物料编码 + 色谱柱型号 + 检验类型；仅启用规则，创建时间倒序，多条取最新）
    function spectrumDriftRuleRows(){
      const mat = String(formModel['物料编码'] || '').trim();
      if(!mat) return [];
      return driftMatchRules(mat, formModel['色谱柱型号'], formModel['检验类型']);
    }
    function spectrumDriftNameOptions(){
      const out = [];
      spectrumDriftRuleRows().forEach(r=>{
        const n = String(r['规则名称'] || '').trim();
        if(n && !out.includes(n)) out.push(n);
      });
      if(!out.length){
        // 未匹配到规则时仍允许手动改选其他启用规则
        driftRowsOf().forEach(r=>{
          if(String(r['启用状态'] || '启用') === '禁用') return;
          const n = String(r['规则名称'] || '').trim();
          if(n && !out.includes(n)) out.push(n);
        });
      }
      const cur = String(formModel['漂移规则'] || '').trim();
      if(cur && !out.includes(cur)) out.unshift(cur);
      return out;
    }

    // 规则分类：始终跟随「漂移规则」所指规则方案（drift-rule）的「规则分类」，全场景只读
    function spectrumRuleByName(ruleName){
      const nm = String(ruleName || '').trim();
      if(!nm) return null;
      return driftRowsOf().find(r=> String(r['规则名称'] || '').trim() === nm) || null;
    }
    function spectrumRuleCategoryPlaceholder(){
      const nm = String(formModel['漂移规则'] || '').trim();
      if(!nm) return '未匹配到规则方案';
      return spectrumRuleByName(nm) ? '规则方案未维护规则分类' : '未匹配到规则方案';
    }
    function syncSpectrumRuleCategory(){
      const rule = spectrumRuleByName(formModel['漂移规则']);
      formModel['规则分类'] = rule ? String(rule['规则分类'] || '').trim() : '';
    }
    // 匹配多条时取最新一条（创建时间倒序首位）
    function syncSpectrumDriftName(){
      const hits = spectrumDriftRuleRows();
      formModel['漂移规则'] = hits.length ? String(hits[0]['规则名称'] || '').trim() : '';
      syncSpectrumRuleCategory();
    }
    function onSpectrumInspTypeChange(){
      const hadFile = !!String(formModel._srcFileId || '').trim();
      formModel['源文件'] = '';
      formModel._srcFileId = '';
      formModel['文件名称'] = '';
      formModel['批号'] = '';
      formModel['仪器编号'] = '';
      formModel['仪器名称'] = '';
      formModel['漂移规则'] = '';
      formModel['规则分类'] = '';
      if(String(formModel._matFromFile || '').trim()){
        formModel['物料编码'] = '';
        formModel['物料名称'] = '';
        formModel['物料规格'] = '';
        formModel['物料种类'] = '';
      }
      formModel._matFromFile = '';
      resetSpectrumCalc();
      if(hadFile) ElMessage.info('已切换检验类型，请重新选择源文件');
    }
    function onSpectrumMaterialChange(){
      const code = String(formModel['物料编码'] || '').trim();
      formModel._matFromFile = '';
      if(!code){
        formModel['物料名称'] = '';
        formModel['物料规格'] = '';
        formModel['物料种类'] = '';
        formModel['漂移规则'] = '';
        formModel['规则分类'] = '';
        return;
      }
      fillSpectrumMaterial(code);
      syncSpectrumDriftName();
    }
    function onSpectrumColumnModelChange(){
      const code = String(formModel['色谱柱编号'] || '').trim();
      if(code && !spectrumColumnCodeOptions().includes(code)) formModel['色谱柱编号'] = '';
      syncSpectrumDriftName();
    }

    // ===== 列表行：汇总字段 / 峰表懒生成 / 保存 / 删除 =====
    function spiCleanPeaks(rows){ return (rows || []).map(p=> JSON.parse(JSON.stringify(p))); }
    function spiApplySummary(row, peaks){
      const list = peaks || [];
      const news = list.filter(p=> p.是否新杂==='是');
      const bad = list.filter(p=> p.杂质偏差结论==='异常');
      row['杂质个数'] = list.filter(p=> p.是否主峰!=='是').length;
      row['新杂个数'] = news.length;
      row['是否存在新杂'] = news.length ? '是' : '否';
      row['杂质偏差结论'] = bad.length ? '异常' : '正常';
      row['异常描述'] = bad.map(p=> '峰'+p.谱图峰号+'（保留时间 '+p.谱图保留时间+'）峰面积 '+p.谱图峰面积+'，超出 '+p.杂质指标).join('；') || '—';
    }
    // 兼容下游（GC/LC 台账等）读取的别名字段
    function spiApplyAlias(row){
      row['谱图流水'] = row['谱图编号'] || '';
      row['漂移规则名称'] = row['漂移规则'] || '';
      row['使用状态'] = row['使用状态'] || '启用';
    }
    // 已识别但尚未落峰表的历史/种子行：按源文件积分结果 + 漂移规则重算一次并固化到行上（同一文件每次结果一致）
    function spiEnsurePeaks(rowLike){
      const row = rowLike && (spiRowsOf().find(r=> r.id===rowLike.id) || rowLike);
      if(!row || (Array.isArray(row._peaks) && row._peaks.length)) return row;
      if(String(row['识别状态']||'')==='待识别') return row;
      const peaks = spectrumSourcePeaks(row._srcFileId);
      if(!peaks.length) return row;
      const res = spectrumComputeRows(peaks, row['漂移规则'] === '—' ? '' : row['漂移规则'], {});
      row._peaks = spiCleanPeaks(res.rows);
      spiApplySummary(row, row._peaks);
      return row;
    }
    function spiNextNo(){
      const maxNo = spiRowsOf().reduce((m, r)=> Math.max(m, parseInt(String(r['谱图编号']||'').replace(/\D/g,''), 10)||0), 0);
      return 'SP-' + String(maxNo + 1).padStart(5, '0');
    }
    function openSpiForm(mode, row){
      openForm(mode);
      SPI_FIELD_KEYS.forEach(k=>{ formModel[k] = ''; });
      formModel._srcFileId = ''; formModel._matFromFile = '';
      resetSpectrumCalc();
      if(mode!=='edit' || !row) return;
      const full = spiEnsurePeaks(row) || row;
      SPI_FIELD_KEYS.forEach(k=>{ const v = full[k]; formModel[k] = (v===undefined || v===null || v==='—') ? '' : v; });
      formModel._editId = full.id;
      // 回填源文件引用与物料来源，保证「源文件 / 物料编码」的只读口径与新增时一致
      formModel._srcFileId = full._srcFileId || '';
      formModel._matFromFile = full._matFromFile || '';
      if(!String(formModel['源文件']||'').trim()){
        const sf = spectrumFileById(formModel._srcFileId);
        if(sf) formModel['源文件'] = sf['文件名'] || '';
      }
      // 历史行缺物料规格/种类时按物料编码补齐
      if(String(formModel['物料编码']||'').trim() && !String(formModel['物料规格']||'').trim()) fillSpectrumMaterial(formModel['物料编码']);
      // 规则分类按当前规则方案重算，保证与规则主数据一致（历史脏值不保留）
      syncSpectrumRuleCategory();
      spectrumPeaks.value = spiCleanPeaks(full._peaks);
      spectrumCalcDone.value = spectrumPeaks.value.length > 0;
    }
    function openSpectrumMatPick(){
      if(formMode.value==='detail') return;
      if(String(formModel._matFromFile||'').trim()) return;     // 源文件已带出物料：锁定
      openIoPick('mat', 'spiMat', '物料编码');
    }
    function applySpiMatPick(r){
      formModel['物料编码'] = r['物料编码'] || '';
      onSpectrumMaterialChange();
      ioPickVisible.value = false;
    }
    function saveSpiForm(){
      const txt = k=> String(formModel[k]==null ? '' : formModel[k]).trim();
      if(!txt('检验类型')){ ElMessage.warning('请选择检验类型'); return; }
      const srcId = txt('_srcFileId');
      if(!srcId || !spectrumFileById(srcId)){ ElMessage.warning('请选择源文件（图谱文件台账）'); return; }
      if(!txt('物料编码')){ ElMessage.warning('请选择物料编码'); return; }
      if(!txt('色谱柱型号')){ ElMessage.warning('请选择色谱柱型号'); return; }
      if(!txt('色谱柱编号')){ ElMessage.warning('请选择色谱柱编号'); return; }
      const peaks = spectrumPeaks.value || [];
      // 保存校验：对应典型保留时间有值的组分峰，不可为新杂
      const bad = peaks.find(p=> String(p.对应典型保留时间||'').trim() && p.对应典型保留时间!=='—' && p.是否新杂==='是');
      if(bad){ ElMessage.warning('峰'+bad.谱图峰号+' 已有对应典型保留时间，是否新杂不可为「是」'); return; }
      const list = spiRowsOf();
      const isAdd = formMode.value!=='edit';
      const payload = {};
      SPI_FIELD_KEYS.forEach(k=>{ payload[k] = txt(k) || '—'; });
      payload._srcFileId = srcId;
      payload._matFromFile = txt('_matFromFile') ? '1' : '';
      payload._peaks = spiCleanPeaks(peaks);
      spiApplySummary(payload, payload._peaks);
      let added = 0;
      const rule = spectrumRuleByName(txt('漂移规则'));
      if(isAdd){
        const no = spiNextNo();
        const row = Object.assign({ id:'sp-'+Date.now(), 谱图编号: no }, payload, { 识别状态: spectrumCalcDone.value ? '已识别' : '待识别', 创建人:'张三', 创建时间: nowStamp() });
        spiApplyAlias(row);
        // 按「TR规则」把本次新杂叠加到漂移规则典型保留时间（固定值不叠加；按批次叠加；首批次叠加其余批次不叠加）
        const tr = rule && rule['TR规则'];
        const firstBatch = !list.some(r=> r['漂移规则']===txt('漂移规则') && r['批号']!==payload['批号']);
        const news = peaks.filter(p=> p.是否新杂==='是' && String(p.相对保留时间||'').trim() && p.相对保留时间!=='—');
        if(rule && news.length && (tr==='按批次新增自动叠加' || tr==='按批次新建流动叠加' || (tr==='首批次新建流动叠加，其余批次不叠加' && firstBatch))){
          if(!Array.isArray(rule._impurities)) rule._impurities = (rule._known||[]).slice();
          news.forEach(p=>{
            const t = String(p.相对保留时间);
            if(rule._impurities.some(k=> String(k['典型保留时间'])===t)) return;
            const lo = driftNum(t), d = 0.002;
            const range = driftRangeByRrt(lo, rule._rrtRules||[], lo==null?'':(lo-d).toFixed(4), lo==null?'':(lo+d).toFixed(4));
            rule._impurities.push({
              是否主峰:'否', 典型保留时间:t,
              有效范围下限: range.lo==null?'':Number(range.lo.toFixed(4)), 有效范围上限: range.hi==null?'':Number(range.hi.toFixed(4)),
              定性结构:'', 标准结果值:'', UCL: String(rule._newUCL||''), LCL: String(rule._newLCL||'')
            });
            added++;
          });
          rule._known = rule._impurities;
          rule['杂质个数'] = rule._impurities.length;
        }
        list.unshift(row);
        ElMessage.success('图谱识别任务已新增 '+no + (added ? '，'+added+' 个新杂已添加到漂移规则「'+rule['规则名称']+'」' : ''));
      } else {
        const cur = list.find(r=> r.id===formModel._editId);
        if(!cur){ ElMessage.warning('未找到待编辑图谱'); return; }
        Object.assign(cur, payload);
        cur['识别状态'] = spectrumCalcDone.value ? (cur['识别状态']==='待识别' ? '已识别' : cur['识别状态']) : cur['识别状态'];
        spiApplyAlias(cur);
        ElMessage.success('图谱识别任务已保存');
      }
      // 示例图谱文件固定保持「未使用」：保存识别任务不占用文件，同一份图谱可反复选取识别
      formVisible.value = false;
      bumpStore();
    }
    // 重新识别：复用「编辑」的回填与弹窗，再按源文件积分结果重跑识别计算
    function reRecognizeSpi(row){
      const sf = spectrumFileById(row._srcFileId);
      if(!sf){ ElMessage.warning('该记录未关联源文件，无法重新识别'); return; }
      openSpiForm('edit', row);
      nextTick(()=>{ if(pageId.value===SPI_PAGE) runSpectrumCalc(); });
    }
    function deleteSpiRows(rowsArg){
      const list = spiRowsOf();
      const rows = Array.isArray(rowsArg) ? rowsArg : list.filter(r=> selectedIds.value.includes(r.id));
      if(!rows.length){ ElMessage.warning('请先勾选要删除的数据'); return; }
      const ids = new Set(rows.map(r=> r.id));
      ElementPlus.ElMessageBox.confirm(rows.length===1 ? '确认删除图谱识别任务 '+(rows[0]['谱图编号']||'')+'？删除后不可恢复。' : '确认删除所选的 '+rows.length+' 条图谱识别任务？不影响漂移规则内的典型保留时间。', rows.length===1 ? '删除确认' : '批量删除', { confirmButtonText:'确认删除', cancelButtonText:'取消', type:'warning' }).then(()=>{
        for(let i = list.length - 1; i >= 0; i--){ if(ids.has(list[i].id)) list.splice(i, 1); }
        selectedIds.value = selectedIds.value.filter(id=> !ids.has(id));
        bumpStore();
        ElMessage.success(rows.length===1 ? '图谱识别任务已删除' : '已删除 '+rows.length+' 条数据');
      }).catch(()=>{});
    }
    function onSpiToolbar(btn){
      if(btn.name==='新增'){ openSpiForm('add'); return true; }
      if(btn.name==='导入' || btn.name==='导入数据'){ importVisible.value = true; return true; }
      if(btn.name==='导出' || btn.name==='导出数据'){ exportVisible.value = true; return true; }
      if(btn.name==='批量删除'){ deleteSpiRows(); return true; }
      return false;
    }

    /** GC / LC 台账（np-0208-04 / np-0208-05）：左侧分类由漂移规则派生（物料 × 色谱柱型号），右侧台账按漂移规则典型保留时间动态生成列 */
    const chromLedgerDim = ref('峰面积%');
    // 维度口径：峰面积% = _rt[TR].a（相对峰面积）；峰面积 = a × 10000（绝对峰面积）；保留时间 = _rt[TR].t；组合项按「峰面积% / 峰面积 / 保留时间」三段展示
    const CHROM_LEDGER_DIM_PAIRS = '峰面积%&峰面积&保留时间';
    const CHROM_LEDGER_DIMS = ['峰面积%','峰面积','保留时间',CHROM_LEDGER_DIM_PAIRS];
    function isChromLedgerPage(){ return !!CHROM_LEDGER_PAGES[pageId.value]; }
    function chromLedgerKindOf(pid){ return CHROM_LEDGER_PAGES[pid] || ''; }
    function chromLedgerPageByRuleCategory(cat){
      const c = String(cat || '').trim().toUpperCase();
      return Object.keys(CHROM_LEDGER_PAGES).find(pid=> CHROM_LEDGER_PAGES[pid]===c) || '';
    }
    function chromLedgerPctText(v){
      // 列表只展示数值本身，不带 % 后缀（单位由维度名称体现）
      const s = (v && v.a != null && v.a !== '') ? String(v.a).trim() : '';
      return s || '—';
    }
    function chromLedgerAreaText(v){
      const pct = parseFloat(v && v.a);
      return Number.isFinite(pct) ? String(+(pct * 10000).toFixed(1)) : '—';
    }
    function chromLedgerCell(row, rt){
      const v = (row._rt && row._rt[rt]) || {};
      const dim = chromLedgerDim.value;
      if(dim==='峰面积') return chromLedgerAreaText(v);
      if(dim==='保留时间') return v.t || '—';
      if(dim===CHROM_LEDGER_DIM_PAIRS) return [chromLedgerPctText(v), chromLedgerAreaText(v), (v.t || '—')].join(' / ');
      return chromLedgerPctText(v);
    }
    // 页签＝报检单类型（本页固定 8 类，不随规则裁剪）
    function chromLedgerTabDefs(){ return ((CFG.pages['np-0208-04'] || {}).tabs) || []; }
    // 台账页签：由「启用 + 规则分类 + 适用检验类型」命中；无命中时回退全部页签（仅供分类同步判断，不影响页签展示）
    function chromLedgerPageTabs(pid){
      const defs = chromLedgerTabDefs();
      const want = chromLedgerKindOf(pid || pageId.value);
      if(!want) return defs;
      const used = new Set();
      driftRowsOf().forEach(r=>{
        if(String(r['启用状态'] || '启用') !== '启用') return;
        if(String(r['规则分类'] || '').trim().toUpperCase() !== want) return;
        driftInspList(r['使用检验类型'] || r['适用检验类型']).forEach(lb=> used.add(lb));
      });
      const hit = defs.filter(t=> used.has(t.label));
      return hit.length ? hit : defs;
    }
    // 规则「适用检验类型」→ 台账页签；为空 / 匹配不到时覆盖全部页签
    function chromLedgerTabsOfRule(rule){
      const defs = chromLedgerTabDefs();
      const used = driftInspList((rule && (rule['使用检验类型'] || rule['适用检验类型'])) || '');
      if(!used.length) return { tabs: defs.map(t=> t.name), fallbackAll: true };
      const hit = defs.filter(t=> used.includes(t.label)).map(t=> t.name);
      return { tabs: hit.length ? hit : defs.map(t=> t.name), fallbackAll: !hit.length };
    }
    // 规则的「适用物料 × 色谱柱型号」展开为台账分类（名称＝物料编码/型号；无型号时退化为物料编码）
    function chromLedgerCatsOfRule(rule){
      const mats = (Array.isArray(rule && rule._mats) ? rule._mats : [])
        .filter(m=> String((m || {})['物料编码'] || '').trim());
      const cols = (rule && (rule._columns || rule._cols)) || [];
      const models = (Array.isArray(cols) ? cols : [])
        .map(c=> String((c && c['色谱柱型号']) || c || '').trim()).filter(Boolean);
      const matList = ((MOCK['mat-list'] || {}).main) || [];
      const out = [];
      mats.forEach(m=>{
        const code = String(m['物料编码'] || '').trim();
        const master = matList.find(r=> String(r['物料编码'] || '') === code) || {};
        (models.length ? models : ['']).forEach(md=>{
          out.push({
            物料编码: code,
            物料名称: String(m['物料名称'] || master['物料名称'] || '').trim(),
            物料规格: String(master['物料规格'] || '').trim(),
            色谱柱型号: md,
            名称: md ? (code + '/' + md) : code,
          });
        });
      });
      return out;
    }
    // 台账左栏分类：启用且规则分类匹配的漂移规则派生 + 本页手工「新增分类」
    function chromLedgerManualCats(pid, tab){
      const bag = MOCK[pid] || {};
      const t = String(tab || '').trim();
      return (Array.isArray(bag.manualCats) ? bag.manualCats : []).filter(c=> !t || String(c.tab || '') === t);
    }
    function chromLedgerDerivedTypes(pid, tab){
      const want = chromLedgerKindOf(pid);
      const t = String(tab || '').trim();
      const out = [];
      driftRowsOf().forEach(r=>{
        if(String(r['启用状态'] || '启用') !== '启用') return;
        if(String(r['规则分类'] || '').trim().toUpperCase() !== want) return;
        // 分类按页签独立：规则「适用检验类型」命中当前页签才展示（未填写时覆盖全部页签）
        if(t){ const ti = chromLedgerTabsOfRule(r); if(ti.tabs.length && !ti.tabs.includes(t)) return; }
        chromLedgerCatsOfRule(r).forEach(c=>{
          const id = 'rtcat::' + c.物料编码 + '::' + c.色谱柱型号;
          if(out.some(x=> x.id === id)) return;
          out.push({
            id, tab: t,
            编码: c.物料编码, 名称: c.名称, 上级字典: '', 备注: '', 系统开发: false, 分组节点: false,
            物料编码: c.物料编码, 物料名称: c.物料名称, 物料规格: c.物料规格, 色谱柱型号: c.色谱柱型号,
            ruleCode: String(r['规则编码'] || ''), ruleName: String(r['规则名称'] || ''),
          });
        });
      });
      chromLedgerManualCats(pid, t).forEach(c=>{
        const code = String(c.物料编码 || '').trim();
        if(!code) return;
        const model = String(c.色谱柱型号 || '').trim();
        const id = String(c.id || ('rtcat::' + code + '::' + model));
        if(out.some(x=> x.id === id || (x.物料编码===code && String(x.色谱柱型号||'')===model))) return;
        out.push({
          id, tab: t,
          编码: code, 名称: c.名称 || (model ? (code + '/' + model) : code),
          上级字典: '', 备注: '', 系统开发: false, 分组节点: false,
          物料编码: code, 物料名称: c.物料名称 || '', 物料规格: c.物料规格 || '', 色谱柱型号: model,
          ruleCode: String(c.ruleCode || ''), ruleName: String(c.ruleName || ''),
          _manual: true,
        });
      });
      return out;
    }
    // 当前页分类（左栏数据源）：台账页取规则派生分类，其余 dict-split 页取 dictTypes
    function curDictTypes(){
      if(isChromLedgerPage()){
        storeTick.value;
        return chromLedgerDerivedTypes(pageId.value, activeTab.value);
      }
      return dictTypes.value;
    }
    // 台账行是否归属某分类：物料（编码优先，退化为名称）+ 色谱柱型号（行无型号字段时不限）
    function chromLedgerRowOfType(r, t){
      const code = String(r['物料编码'] || '').trim();
      const matOk = code ? code === String(t.物料编码 || '') : String(r['物料名称'] || '') === String(t.物料名称 || '');
      const model = String(r['色谱柱型号'] || '').trim();
      return matOk && (!model || !t.色谱柱型号 || model === t.色谱柱型号);
    }
    // 同步分类：新增 / 更新 / 清理（编辑后不再命中的旧分类、规则改分类后的另一页旧分类）
    function syncChromLedgerByRule(rule){
      const res = { pageId:'', added:0, updated:0, removed:0, tabs:0, note:'' };
      if(!rule) return res;
      const pid = chromLedgerPageByRuleCategory(rule['规则分类']);
      const ruleCode = String(rule['规则编码'] || '').trim() || String(rule['规则名称'] || '').trim();
      // 规则改分类（GC↔LC）时，先清掉另一个台账页里属于本规则的分类
      Object.keys(CHROM_LEDGER_PAGES).forEach(other=>{
        if(other === pid) return;
        const bag = MOCK[other];
        if(!bag || !Array.isArray(bag.types)) return;
        const before = bag.types.length;
        bag.types = bag.types.filter(t=> String(t.ruleCode || '') !== ruleCode);
        res.removed += before - bag.types.length;
      });
      if(!pid){
        res.note = '规则分类为「' + (String(rule['规则分类'] || '').trim() || '未设置') + '」，仅 GC / LC 分类会同步到台账';
        return res;
      }
      res.pageId = pid;
      const cats = chromLedgerCatsOfRule(rule);
      if(!cats.length){
        res.note = '规则未配置「适用物料」，无法生成台账分类';
        return res;
      }
      const bag = MOCK[pid] = MOCK[pid] || {};
      const types = bag.types = bag.types || [];
      const tabInfo = chromLedgerTabsOfRule(rule);
      const visible = chromLedgerPageTabs(pid).map(t=> t.name);
      const realTabs = tabInfo.tabs.filter(n=> visible.includes(n));
      if(!realTabs.length){
        res.note = '规则的「适用检验类型」与当前台账页签无交集，未生成分类';
        return res;
      }
      tabInfo.tabs = realTabs;
      res.tabs = realTabs.length;
      const prefix = pid === 'np-0208-04' ? 'gc' : 'lc';
      const want = new Set(cats.map(c=> c.物料编码 + '|' + c.色谱柱型号));
      const stamp = Date.now();
      tabInfo.tabs.forEach(tab=>{
        for(let i = types.length - 1; i >= 0; i--){
          const t = types[i];
          if(String(t.tab || '') !== tab) continue;
          if(String(t.ruleCode || '') !== ruleCode) continue;
          if(!want.has(String(t.物料编码 || '') + '|' + String(t.色谱柱型号 || ''))){ types.splice(i, 1); res.removed++; }
        }
        cats.forEach((c, ci)=>{
          const hit = types.find(t=> String(t.tab || '') === tab
            && String(t.物料编码 || '') === c.物料编码
            && String(t.色谱柱型号 || '') === c.色谱柱型号);
          if(hit){
            Object.assign(hit, {
              编码: c.物料编码, 名称: c.名称,
              物料名称: c.物料名称 || hit.物料名称 || '',
              物料规格: c.物料规格 || hit.物料规格 || '',
              ruleCode, ruleName: String(rule['规则名称'] || ''),
            });
            res.updated++;
          } else {
            types.push({
              id: 'cc-' + prefix + '-' + tab + '-' + ruleCode + '-' + stamp + '-' + ci,
              tab,
              编码: c.物料编码, 名称: c.名称,
              上级字典: '', 备注: '', 系统开发: false, 分组节点: false,
              物料编码: c.物料编码, 物料名称: c.物料名称, 物料规格: c.物料规格, 色谱柱型号: c.色谱柱型号,
              ruleCode, ruleName: String(rule['规则名称'] || ''),
            });
            res.added++;
          }
        });
      });
      return res;
    }
    // 表头：当前台账页 + 当前页签下命中规则的典型保留时间（升序去重）；无明细回退默认 7 列
    function chromLedgerRtList(){
      const pid = pageId.value;
      const want = chromLedgerKindOf(pid);
      if(!want) return CHROM_LEDGER_RT_LIST.slice();
      storeTick.value;                                  // 规则增删改后随 storeTick 重算列
      const tab = String(activeTab.value || '').trim();
      const set = new Set();
      driftRowsOf().forEach(r=>{
        if(String(r['规则分类'] || '').trim().toUpperCase() !== want) return;
        if(String(r['启用状态'] || '启用') !== '启用') return;
        const tabInfo = chromLedgerTabsOfRule(r);
        if(tab && tabInfo.tabs.length && !tabInfo.tabs.includes(tab)) return;
        (Array.isArray(r._impurities) ? r._impurities : []).forEach(x=>{
          const tr = driftNum(x && x['典型保留时间']);
          if(tr != null) set.add(tr.toFixed(3));
        });
      });
      const arr = Array.from(set).sort((a, b)=> Number(a) - Number(b));
      return arr.length ? arr : CHROM_LEDGER_RT_LIST.slice();
    }
    // 表头用：典型保留时间 → 定性结构（取「启用 + 规则分类匹配」规则的 _impurities，先到先得）
    function chromLedgerRtStructureMap(){
      const want = chromLedgerKindOf(pageId.value);
      if(!want) return {};
      storeTick.value;
      const map = {};
      driftRowsOf().forEach(r=>{
        if(String(r['启用状态'] || '启用') !== '启用') return;
        if(String(r['规则分类'] || '').trim().toUpperCase() !== want) return;
        (Array.isArray(r._impurities) ? r._impurities : []).forEach(x=>{
          const tr = driftNum(x && x['典型保留时间']);
          if(tr == null) return;
          const key = tr.toFixed(3);
          const st = String((x && x['定性结构']) || '').trim();
          if(!(key in map) || (!map[key] && st)) map[key] = st;
        });
      });
      return map;
    }
    // 关联查询：勾选行 → 跳转谱图识别（单列表），按批号过滤
    function chromLedgerRelQuery(){
      const rows = tableData.value.filter(r=> selectedIds.value.includes(r.id));
      if(!rows.length){ ElMessage.warning('请先勾选数据'); return; }
      const nos = [...new Set(rows.map(r=> r['批号']).filter(Boolean))];
      loadPage(SPI_PAGE);
      setTimeout(()=>{
        resetQueryModel();
        query['批号'] = nos.join('、');
        pageNum.value = 1;
        ElMessage.success('已跳转谱图识别，按所选 '+nos.length+' 个批号过滤');
      }, 0);
    }
    function onChromLedgerToolbar(btn){
      if(btn.name==='关联查询'){ chromLedgerRelQuery(); return true; }
      if(btn.name==='导出数据'){ exportVisible.value = true; return true; }
      return false;
    }
    // 行操作：编辑（批号只读）/ 删除
    const chromLedgerEditVisible = ref(false);
    const chromLedgerEditForm = reactive({ 批号:'', 杂质个数:0, 新杂个数:0, 是否存在新杂:'否', 杂质偏差结论:'正常' });
    let chromLedgerEditId = '';
    function openChromLedgerEdit(row){
      chromLedgerEditId = row.id;
      Object.assign(chromLedgerEditForm, {
        批号: row['批号'], 杂质个数: row['杂质个数'], 新杂个数: row['新杂个数'],
        是否存在新杂: row['是否存在新杂'], 杂质偏差结论: row['杂质偏差结论']
      });
      chromLedgerEditVisible.value = true;
    }
    function saveChromLedgerEdit(){
      const bag = MOCK[pageId.value] = MOCK[pageId.value] || {};
      const tab = (tabView.value||{}).name || 'main';
      const cur = (bag[tab]||[]).find(r=> r.id===chromLedgerEditId);
      if(cur){
        cur['杂质个数'] = Number(chromLedgerEditForm.杂质个数)||0;
        cur['新杂个数'] = Number(chromLedgerEditForm.新杂个数)||0;
        cur['是否存在新杂'] = chromLedgerEditForm.是否存在新杂;
        cur['杂质偏差结论'] = chromLedgerEditForm.杂质偏差结论;
        bumpStore();
      }
      chromLedgerEditVisible.value = false;
      ElMessage.success('台账数据已保存');
    }
    // 左侧分类 · 新增分类（规则编号 + 物料 + 色谱柱型号）
    const chromCatAddVisible = ref(false);
    const chromCatAddForm = reactive({ 规则编码:'', 规则名称:'', 物料编码:'', 物料名称:'', 物料规格:'', 色谱柱型号:'' });
    const chromCatMatOptions = computed(()=>{
      const code = String(chromCatAddForm.规则编码 || '').trim();
      if(!code) return [];
      const rule = driftRowsOf().find(r=> String(r['规则编码'] || '') === code);
      if(!rule) return [];
      const matList = ((MOCK['mat-list'] || {}).main) || [];
      const out = [];
      (Array.isArray(rule._mats) ? rule._mats : []).forEach(m=>{
        const c = String((m || {})['物料编码'] || '').trim();
        if(!c || out.some(x=> x.code === c)) return;
        const master = matList.find(r=> String(r['物料编码'] || '') === c) || {};
        out.push({
          code: c,
          name: String(m['物料名称'] || master['物料名称'] || '').trim(),
          spec: String(master['物料规格'] || '').trim(),
        });
      });
      return out;
    });
    const chromCatColOptions = computed(()=> driftColTypeOptions());
    function openChromCatAdd(){
      if(!isChromLedgerPage()) return;
      Object.assign(chromCatAddForm, { 规则编码:'', 规则名称:'', 物料编码:'', 物料名称:'', 物料规格:'', 色谱柱型号:'' });
      chromCatAddVisible.value = true;
    }
    function clearChromCatRule(){
      Object.assign(chromCatAddForm, { 规则编码:'', 规则名称:'', 物料编码:'', 物料名称:'', 物料规格:'', 色谱柱型号:'' });
    }
    function openChromCatDriftPick(){
      openIoPick('chromDriftRule', 'chromCat', '漂移规则编号');
    }
    function applyChromCatDriftPick(row){
      if(!row) return;
      const code = String(row['规则编码'] || '').trim();
      chromCatAddForm.规则编码 = code;
      chromCatAddForm.规则名称 = String(row['规则名称'] || '').trim();
      chromCatAddForm.物料编码 = '';
      chromCatAddForm.物料名称 = '';
      chromCatAddForm.物料规格 = '';
      chromCatAddForm.色谱柱型号 = '';
    }
    function onChromCatMatChange(code){
      const hit = chromCatMatOptions.value.find(m=> m.code === code);
      chromCatAddForm.物料名称 = hit ? (hit.name || '') : '';
      chromCatAddForm.物料规格 = hit ? (hit.spec || '') : '';
    }
    function saveChromCatAdd(){
      const ruleCode = String(chromCatAddForm.规则编码 || '').trim();
      const mat = String(chromCatAddForm.物料编码 || '').trim();
      const model = String(chromCatAddForm.色谱柱型号 || '').trim();
      if(!ruleCode){ ElMessage.warning('请选择漂移规则编号'); return; }
      if(!mat){ ElMessage.warning('请选择物料编码'); return; }
      const tab = String(activeTab.value || '').trim();
      const pid = pageId.value;
      const exists = chromLedgerDerivedTypes(pid, tab).some(t=>
        String(t.ruleCode || '') === ruleCode
        && String(t.物料编码 || '') === mat
        && String(t.色谱柱型号 || '') === model
      ) || chromLedgerManualCats(pid, tab).some(t=>
        String(t.ruleCode || '') === ruleCode
        && String(t.物料编码 || '') === mat
        && String(t.色谱柱型号 || '') === model
      );
      if(exists){ ElMessage.warning('「规则 + 物料 + 色谱柱型号」组合已存在'); return; }
      // 同页签下同物料/型号分类节点已存在时不再重复挂树（规则不同也共用同一节点）
      const sameNode = chromLedgerDerivedTypes(pid, tab).some(t=>
        String(t.物料编码 || '') === mat && String(t.色谱柱型号 || '') === model
      );
      if(sameNode){ ElMessage.warning('左侧已存在分类「' + (model ? (mat + '/' + model) : mat) + '」'); return; }
      const bag = (MOCK[pid] = MOCK[pid] || {});
      const list = (bag.manualCats = Array.isArray(bag.manualCats) ? bag.manualCats : []);
      list.push({
        id: 'rtcat::' + mat + '::' + model,
        tab,
        物料编码: mat,
        物料名称: chromCatAddForm.物料名称 || '',
        物料规格: chromCatAddForm.物料规格 || '',
        色谱柱型号: model,
        名称: model ? (mat + '/' + model) : mat,
        ruleCode,
        ruleName: chromCatAddForm.规则名称 || '',
      });
      bumpStore();
      chromCatAddVisible.value = false;
      ElMessage.success('已新增分类「' + (model ? (mat + '/' + model) : mat) + '」');
    }
    function onChromLedgerRowOp(op, row){
      if(op.name==='编辑'){ openChromLedgerEdit(row); return true; }
      if(op.name==='删除'){
        ElementPlus.ElMessageBox.confirm('确认删除台账数据 '+row['批号']+'？','删除确认',{
          confirmButtonText:'确认删除', cancelButtonText:'取消', type:'warning'
        }).then(()=>{
          const bag = MOCK[pageId.value] = MOCK[pageId.value] || {};
          const tab = (tabView.value||{}).name || 'main';
          bag[tab] = (bag[tab]||[]).filter(r=> r.id!==row.id);
          selectedIds.value = selectedIds.value.filter(id=> id!==row.id);
          bumpStore();
          ElMessage.success('台账数据已删除');
        }).catch(()=>{});
        return true;
      }
      return false;
    }

    /** 持续改进：提案主单；关闭 / 删除 / 编辑联动子级「改进处理」中同提案编号的数据 */
    const CI_PAGE = 'np-0209-01', CI_SUB_PAGE = 'np-0209-02';
    const CI_OPERATOR = '张三';
    const CI_DEPTS = ['产品部','生产部','质量管理部','研发中心','设备部','仓储物流部','安环部'];
    const CI_USERS = [
      { 工号:'U1001', 姓名:'张三', 部门:['产品部'] },
      { 工号:'U1002', 姓名:'李四', 部门:['生产部'] },
      { 工号:'U1003', 姓名:'王五', 部门:['质量管理部'] },
      { 工号:'U1004', 姓名:'赵敏', 部门:['研发中心','产品部'] },
      { 工号:'U1005', 姓名:'陈晨', 部门:['生产部'] },
      { 工号:'U1006', 姓名:'刘洋', 部门:['设备部'] },
      { 工号:'U1007', 姓名:'周倩', 部门:['质量管理部'] },
      { 工号:'U1008', 姓名:'孙浩', 部门:['仓储物流部'] },
      { 工号:'U1009', 姓名:'郑宇航', 部门:['安环部','生产部'] },
    ];
    const CI_MULTI = ['小组成员','责任部门'];
    const CI_REQUIRED = ['提案编号','提案人','提案部门','提案日期','持续改进项目','现有状况描述','改进后状况和改进目标','小组组长','小组成员','责任部门'];
    const CI_FIELDS = [...CI_REQUIRED, '备注'];
    function ciRows(){ return ((MOCK[CI_PAGE] = MOCK[CI_PAGE] || { main: [] }).main = (MOCK[CI_PAGE].main || [])); }
    function ciSubEach(fn){
      const bag = MOCK[CI_SUB_PAGE];
      if(!bag || typeof bag!=='object') return;
      Object.keys(bag).forEach(k=>{ if(Array.isArray(bag[k])) fn(bag, k); });
    }
    function ciSubPrune(pred){ ciSubEach((bag, k)=>{ bag[k] = bag[k].filter(r=> !pred(r)); }); }
    function nextCiNo(){
      const max = ciRows().reduce((m, r)=> Math.max(m, parseInt(String(r['提案编号']||'').replace(/\D/g,''), 10) || 0), 0);
      return String(max + 1).padStart(6, '0');
    }
    function ciDeptsOf(name){ const u = CI_USERS.find(x=> x.姓名===name); return u ? u.部门 : CI_DEPTS; }
    function ciFormOptions(f){
      if(['提案人','小组组长','小组成员'].includes(f.name)) return CI_USERS.map(u=> ({ value:u.姓名, label:u.工号+' / '+u.姓名 }));
      if(f.name==='提案部门') return ciDeptsOf(formModel['提案人']).map(d=> ({ value:d, label:d }));
      if(f.name==='责任部门') return CI_DEPTS.map(d=> ({ value:d, label:d }));
      return null;
    }
    function onCiProposerChange(){
      const ds = ciDeptsOf(formModel['提案人']);
      formModel['提案部门'] = ds.length===1 ? ds[0] : (ds.includes(formModel['提案部门']) ? formModel['提案部门'] : '');
    }
    function openCiForm(mode, row){
      if(mode==='edit' && (row||{})['改进状态']!=='待发起'){ ElMessage.warning('仅待发起状态可编辑'); return; }
      openForm(mode);
      if(mode==='edit'){
        CI_FIELDS.forEach(k=>{ formModel[k] = CI_MULTI.includes(k) ? splitDun(row[k]) : (row[k]==='—' ? '' : (row[k]||'')); });
        formModel._editId = row.id;
        return;
      }
      Object.assign(formModel, { 提案编号: nextCiNo(), 提案人: CI_OPERATOR, 提案日期: nowStamp().slice(0,10), 小组成员: [], 责任部门: [] });
      onCiProposerChange();
    }
    function saveCiForm(){
      const miss = CI_REQUIRED.find(k=> CI_MULTI.includes(k) ? !(formModel[k]||[]).length : !String(formModel[k]||'').trim());
      if(miss){ ElMessage.warning((CI_MULTI.includes(miss) || ['提案人','提案部门','提案日期','小组组长'].includes(miss) ? '请选择' : '请输入') + miss); return; }
      const list = ciRows();
      const no = String(formModel['提案编号']).trim();
      if(list.some(r=> r['提案编号']===no && r.id!==formModel._editId)){ ElMessage.warning('提案编号已存在，请刷新后重新生成'); return; }
      const payload = {};
      CI_FIELDS.forEach(k=>{ payload[k] = CI_MULTI.includes(k) ? formModel[k].join('、') : String(formModel[k]||'').trim(); });
      if(formMode.value==='add'){
        list.unshift({ id:'ci-'+Date.now(), 改进状态:'待发起', ...payload, 创建时间: nowStamp(), 创建人: CI_OPERATOR });
        ElMessage.success('持续改进已新增');
      } else {
        const cur = list.find(r=> r.id===formModel._editId);
        if(!cur){ ElMessage.warning('未找到待编辑的数据'); return; }
        if(cur['改进状态']!=='待发起'){ ElMessage.warning('仅待发起状态可编辑'); return; }
        Object.assign(cur, payload);
        ciSubEach((bag, k)=> bag[k].forEach(r=>{
          if(r['提案编号']!==cur['提案编号']) return;
          CI_FIELDS.forEach(f=>{ if(f!=='责任部门' && f in r) r[f] = cur[f]; });
        }));
        ciSyncStatus(cur);
        ElMessage.success('已保存，改进处理内的数据已同步修改');
      }
      formVisible.value = false;
      bumpStore();
    }
    const canCloseCi = computed(()=>{
      if(pageId.value!==CI_PAGE || !selectedIds.value.length) return false;
      const ids = new Set(selectedIds.value);
      const rows = ciRows().filter(r=> ids.has(r.id));
      return rows.length>0 && rows.every(r=> r['改进状态']==='待发起');
    });
    const canDeleteCi = computed(()=>{
      if(pageId.value!==CI_PAGE || !selectedIds.value.length) return false;
      const ids = new Set(selectedIds.value);
      const rows = ciRows().filter(r=> ids.has(r.id));
      return rows.length>0 && rows.every(r=> r['改进状态']==='待发起' || r['改进状态']==='已关闭');
    });
    function confirmCiLaunch(row){
      const cur = ciRows().find(r=> r.id===(row||{}).id);
      if(!cur){ ElMessage.warning('未找到要确认发起的数据'); return; }
      if(cur['改进状态']!=='待发起'){ ElMessage.warning('仅待发起状态可确认发起'); return; }
      const no = cur['提案编号'] || '';
      ElementPlus.ElMessageBox.confirm('确认对提案「'+no+'」发起？发起后改进状态变为执行中。', '确认发起', { type:'warning' }).then(()=>{
        cur['改进状态'] = '执行中';
        ciSyncStatus(cur);
        bumpStore();
        ElMessage.success('提案「'+no+'」已确认发起，改进状态为执行中');
      }).catch(()=>{});
    }
    function closeCiRows(){
      const ids = new Set(selectedIds.value);
      const rows = ciRows().filter(r=> ids.has(r.id));
      if(!rows.length){ ElMessage.warning('请先勾选数据'); return; }
      if(!canCloseCi.value){ ElMessage.warning('仅改进状态为「待发起」的数据可关闭'); return; }
      ElementPlus.ElMessageBox.confirm('确认关闭所选的 '+rows.length+' 条持续改进？关闭后改进处理内未完成的数据将全部自动删除。', '关闭', { type:'warning' }).then(()=>{
        const nos = new Set(rows.map(r=> r['提案编号']));
        rows.forEach(r=>{ r['改进状态'] = '已关闭'; });
        ciSubPrune(r=> nos.has(r['提案编号']) && r['处理状态']!=='已完成');
        selectedIds.value = []; bumpStore();
        ElMessage.success('已关闭 '+rows.length+' 条持续改进');
      }).catch(()=>{});
    }
    function deleteCiRows(){
      const ids = new Set(selectedIds.value);
      if(!ids.size){ ElMessage.warning('请先勾选要删除的数据'); return; }
      if(!canDeleteCi.value){ ElMessage.warning('仅改进状态为「待发起」或「已关闭」的数据可批量删除'); return; }
      ElementPlus.ElMessageBox.confirm('确认删除所选的 '+ids.size+' 条持续改进？改进处理内对应的数据将一并删除。', '批量删除', { type:'warning' }).then(()=>{
        const list = ciRows();
        const nos = new Set(list.filter(r=> ids.has(r.id)).map(r=> r['提案编号']));
        MOCK[CI_PAGE].main = list.filter(r=> !ids.has(r.id));
        ciSubPrune(r=> nos.has(r['提案编号']));
        selectedIds.value = []; bumpStore();
        ElMessage.success('已删除 '+ids.size+' 条数据');
      }).catch(()=>{});
    }
    function ciRelQuery(){
      const rows = tableData.value.filter(r=> selectedIds.value.includes(r.id));
      if(!rows.length){ ElMessage.warning('请先勾选数据'); return; }
      const nos = rows.map(r=> r['提案编号']);
      const set = new Set(nos);
      const toDone = !cipPendingRows().some(r=> set.has(r['提案编号'])) && cipDoneList().some(r=> set.has(r['提案编号']));
      loadPage(CI_SUB_PAGE);
      setTimeout(()=>{
        if(toDone) activeTab.value = 'tab-2';
        query['提案编号'] = nos.join('、');
        pageNum.value = 1;
        ElMessage.success('已跳转改进处理'+(toDone ? '「已完成」' : '')+'，按所选 '+nos.length+' 个提案编号过滤');
      }, 0);
    }
    function ciQueryRows(list, containsKeys, exactKeys, dateKeys){
      const nos = splitDun(query['提案编号']);
      if(nos.length>1){
        const set = new Set(nos);
        list = list.filter(r=> set.has(r['提案编号']));
        containsKeys = containsKeys.filter(k=> k!=='提案编号');
      }
      list = applyContainsExactQuery(list, query, containsKeys, exactKeys);
      dateKeys.forEach(k=>{ list = applyDateRangeQuery(list, query, k); });
      return list;
    }
    /** 内审计划：关闭仅执行中；删除同步去掉内审实施同单号数据；编辑同步修改内审实施 */
    const IA_PAGE = 'np-0211-01', IA_EXEC = 'np-0211-03', IA_RECT = 'np-0211-04';
    const IA_FIELDS = ['内审单号','内审年度','审核日期','审核目的','审核准则','审核范围','审核组成员','审核附件','备注'];
    const IA_REQUIRED = ['内审单号','内审年度','审核目的'];
    const IA_MULTI = ['审核组成员'];
    const IA_SYNC = ['内审年度','审核日期','审核目的','审核准则','审核范围','审核组成员','备注','审核附件'];
    function iaRows(){ return ((MOCK[IA_PAGE] = MOCK[IA_PAGE] || { main: [] }).main = (MOCK[IA_PAGE].main || [])); }
    function iaEach(pid, fn){
      const bag = MOCK[pid];
      if(!bag || typeof bag!=='object') return;
      Object.keys(bag).forEach(k=>{ if(Array.isArray(bag[k])) bag[k].forEach(fn); });
    }
    function iaBagRows(pid){
      const out = [];
      iaEach(pid, r=> out.push(r));
      return out;
    }
    function iaPrune(pid, pred){
      const bag = MOCK[pid];
      if(!bag || typeof bag!=='object') return;
      Object.keys(bag).forEach(k=>{ if(Array.isArray(bag[k])) bag[k] = bag[k].filter(r=> !pred(r)); });
    }
    function nextIaNo(){
      const max = iaRows().reduce((m, r)=> Math.max(m, parseInt(String(r['内审单号']||'').replace(/\D/g,''), 10) || 0), 0);
      return String(max + 1).padStart(6, '0');
    }
    function iaFormOptions(f){
      if(f.name==='审核组成员') return CI_USERS.map(u=> ({ value:u.姓名, label:u.工号+' / '+u.姓名 }));
      return null;
    }
    function iaQueryRows(list){
      const nos = splitDun(query['内审单号']);
      if(nos.length>1){
        const set = new Set(nos);
        list = list.filter(r=> set.has(r['内审单号']));
      }
      list = applyContainsExactQuery(list, nos.length>1 ? Object.assign({}, query, { 内审单号:'' }) : query, ['内审单号','审核目的','审核组成员','创建人'], ['内审状态','内审年度']);
      ['审核日期','创建时间'].forEach(k=>{ list = applyDateRangeQuery(list, query, k); });
      return list;
    }
    function openIaForm(mode, row){
      openForm(mode==='copy' ? 'add' : mode);
      if(mode==='edit'){
        IA_FIELDS.forEach(k=>{ formModel[k] = IA_MULTI.includes(k) ? splitDun(row[k]) : (row[k]==='—' ? '' : (row[k]||'')); });
        formModel._editId = row.id;
        return;
      }
      const year = new Date().getFullYear()+'年';
      if(mode==='copy' && row){
        IA_FIELDS.forEach(k=>{ formModel[k] = IA_MULTI.includes(k) ? splitDun(row[k]) : (row[k]==='—' ? '' : (row[k]||'')); });
        formModel['内审单号'] = nextIaNo();
        delete formModel._editId;
        return;
      }
      Object.assign(formModel, { 内审单号: nextIaNo(), 内审年度: year, 审核日期:'', 审核目的:'', 审核准则:'', 审核范围:'', 审核组成员:[], 审核附件:'', 备注:'' });
    }
    function saveIaForm(){
      const miss = IA_REQUIRED.find(k=> IA_MULTI.includes(k) ? !(formModel[k]||[]).length : !String(formModel[k]||'').trim());
      if(miss){ ElMessage.warning((miss==='审核目的' ? '请输入' : '请选择')+miss); return; }
      const list = iaRows();
      const no = String(formModel['内审单号']).trim();
      if(!/^\d{6}$/.test(no)){ ElMessage.warning('内审单号须为 6 位数字流水'); return; }
      if(list.some(r=> r['内审单号']===no && r.id!==formModel._editId)){ ElMessage.warning('内审单号已存在，请刷新后重新生成'); return; }
      const payload = {};
      IA_FIELDS.forEach(k=>{ payload[k] = IA_MULTI.includes(k) ? (formModel[k]||[]).filter(Boolean).join('、') : String(formModel[k]||'').trim(); });
      if(formMode.value==='add'){
        list.unshift({ id:'ia-'+Date.now(), 内审状态:'执行中', ...payload, 创建时间: nowStamp(), 创建人: CI_OPERATOR });
        ElMessage.success('内审计划已新增');
      } else {
        const cur = list.find(r=> r.id===formModel._editId);
        if(!cur){ ElMessage.warning('未找到待编辑的数据'); return; }
        Object.assign(cur, payload);
        iaEach(IA_EXEC, r=>{
          if(r['内审单号']!==cur['内审单号']) return;
          IA_SYNC.forEach(f=>{ r[f] = cur[f]; });
        });
        ElMessage.success('已保存，内审实施内同单号数据已同步修改');
      }
      formVisible.value = false;
      bumpStore();
    }
    const canCloseIa = computed(()=>{
      if(pageId.value!==IA_PAGE || !selectedIds.value.length) return false;
      const ids = new Set(selectedIds.value);
      return iaRows().filter(r=> ids.has(r.id)).every(r=> r['内审状态']==='执行中');
    });
    function closeIaRows(){
      const ids = new Set(selectedIds.value);
      const rows = iaRows().filter(r=> ids.has(r.id));
      if(!rows.length){ ElMessage.warning('请先勾选数据'); return; }
      if(!canCloseIa.value){ ElMessage.warning('仅内审状态为「执行中」的数据可关闭'); return; }
      ElementPlus.ElMessageBox.confirm('确认关闭所选的 '+rows.length+' 条内审计划？关闭后状态将更改为已关闭。', '关闭', { type:'warning' }).then(()=>{
        rows.forEach(r=>{ r['内审状态'] = '已关闭'; });
        selectedIds.value = []; bumpStore();
        ElMessage.success('已关闭 '+rows.length+' 条内审计划');
      }).catch(()=>{});
    }
    function deleteIaRows(){
      const ids = new Set(selectedIds.value);
      if(!ids.size){ ElMessage.warning('请先勾选要删除的数据'); return; }
      ElementPlus.ElMessageBox.confirm('确认删除所选的 '+ids.size+' 条内审计划？内审实施内同单号数据将一并删除。', '批量删除', { type:'warning' }).then(()=>{
        const list = iaRows();
        const nos = new Set(list.filter(r=> ids.has(r.id)).map(r=> r['内审单号']));
        MOCK[IA_PAGE].main = list.filter(r=> !ids.has(r.id));
        iaPrune(IA_EXEC, r=> nos.has(r['内审单号']));
        selectedIds.value = []; bumpStore();
        ElMessage.success('已删除 '+ids.size+' 条数据');
      }).catch(()=>{});
    }
    const EA_PAGE = 'np-0211-02';
    const AUDIT_PAGE = { 'np-0211-02': '外审' };
    const EA_MULTI = ['负责人'];
    function isAuditPage(){ return !!AUDIT_PAGE[pageId.value]; }
    function auditPrefix(){ return AUDIT_PAGE[pageId.value] || '外审'; }
    function auditNoKey(){ return '审核单号'; }
    function auditExecKey(){ return auditPrefix()+'实施'; }
    function auditWhoKey(){ return auditPrefix()+'实施提交人'; }
    function auditWhenKey(){ return auditPrefix()+'实施提交时间'; }
    function auditFields(){ return [auditNoKey(),'审核方式','审核类型','客户名称','审核日期','审核内容描述','负责人','审核附件','需求资料','备注']; }
    function eaBag(){
      const pid = isAuditPage() ? pageId.value : EA_PAGE;
      return MOCK[pid] = MOCK[pid] || { 'tab-1':[], 'tab-2':[] };
    }
    function eaList(tab){ const b = eaBag(); if(!Array.isArray(b[tab])) b[tab] = []; return b[tab]; }
    function eaAll(){ return eaList('tab-1').concat(eaList('tab-2')); }
    function nextEaNo(){
      const max = eaAll().reduce((m, r)=> Math.max(m, parseInt(String(r[auditNoKey()]||'').replace(/\D/g,''), 10) || 0), 0);
      return String(max + 1).padStart(6, '0');
    }
    function eaFormOptions(f){
      if(f.name==='负责人') return CI_USERS.map(u=> ({ value:u.姓名, label:u.工号+' / '+u.姓名 }));
      return null;
    }
    function eaQuery(list, done){
      const noKey = auditNoKey();
      const nos = splitDun(query[noKey]);
      if(nos.length>1){
        const set = new Set(nos);
        list = list.filter(r=> set.has(r[noKey]));
      }
      const q = nos.length>1 ? Object.assign({}, query, { [noKey]:'' }) : query;
      const contains = [noKey,'客户名称','负责人','审核内容描述','创建人'].concat(done ? [auditWhoKey(),'实施说明'] : []);
      list = applyContainsExactQuery(list, q, contains, ['审核方式','审核类型']);
      ['审核日期','创建时间'].forEach(k=>{ list = applyDateRangeQuery(list, query, k); });
      if(done) list = applyDateRangeQuery(list, query, auditWhenKey());
      return list;
    }
    function openEaForm(mode, row){
      openForm(mode==='copy' ? 'add' : mode);
      const fields = auditFields();
      const fill = (src)=>{
        fields.forEach(k=>{ formModel[k] = EA_MULTI.includes(k) ? splitDun(src[k]) : (src[k]==='—' ? '' : (src[k]||'')); });
      };
      if(mode==='edit'){
        fill(row);
        formModel._editId = row.id;
        return;
      }
      if(mode==='copy' && row){
        fill(row);
        formModel[auditNoKey()] = nextEaNo();
        delete formModel._editId;
        return;
      }
      const blank = { 审核方式:'', 审核类型:'', 客户名称:'', 审核日期:'', 审核内容描述:'', 负责人:[], 需求资料:'', 审核附件:'', 备注:'' };
      blank[auditNoKey()] = nextEaNo();
      Object.assign(formModel, blank);
    }
    function saveEaForm(){
      if(!String(formModel['审核方式']||'').trim()){ ElMessage.warning('请选择审核方式'); return; }
      if(!String(formModel['审核类型']||'').trim()){ ElMessage.warning('请选择审核类型'); return; }
      const noKey = auditNoKey();
      const no = String(formModel[noKey]||'').trim();
      if(!/^\d{6}$/.test(no)){ ElMessage.warning(noKey+'须为 6 位数字流水'); return; }
      if(eaAll().some(r=> r[noKey]===no && r.id!==formModel._editId)){ ElMessage.warning(noKey+'已存在，请刷新后重新生成'); return; }
      const payload = {};
      auditFields().forEach(k=>{ payload[k] = EA_MULTI.includes(k) ? (formModel[k]||[]).filter(Boolean).join('、') : String(formModel[k]||'').trim(); });
      const label = auditPrefix()+'单';
      if(formMode.value==='add'){
        eaList('tab-1').unshift({ id:(auditPrefix()==='内审'?'ia':'ea')+'-'+Date.now(), 审核状态:'执行中', ...payload, 创建时间: nowStamp(), 创建人: CI_OPERATOR });
        ElMessage.success(label+'已新增');
      } else {
        const cur = eaList('tab-1').find(r=> r.id===formModel._editId);
        if(!cur){ ElMessage.warning('未找到待编辑的数据'); return; }
        Object.assign(cur, payload);
        ElMessage.success('已保存');
      }
      formVisible.value = false;
      bumpStore();
    }
    function deleteEaRows(){
      const ids = new Set(selectedIds.value);
      if(!ids.size){ ElMessage.warning('请先勾选要删除的数据'); return; }
      ElementPlus.ElMessageBox.confirm('确认删除所选的 '+ids.size+' 条'+auditPrefix()+'单？', '批量删除', { type:'warning' }).then(()=>{
        eaBag()['tab-1'] = eaList('tab-1').filter(r=> !ids.has(r.id));
        selectedIds.value = [];
        bumpStore();
        ElMessage.success('已删除 '+ids.size+' 条数据');
      }).catch(()=>{});
    }
    function openEaExec(row){
      openProcDlg({
        title: auditExecKey(), okText:'确定', keys:[],
        fields:[
          { name:'实施说明', type:'input', placeholder:'输入' },
          { name:'附件', type:'upload', half:true }
        ],
        onSubmit: submitEaExec
      }, row);
    }
    function submitEaExec(row, desc, files){
      const list = eaList('tab-1');
      const i = list.findIndex(r=> r.id===row.id);
      const label = auditPrefix()+'单';
      if(i<0){ ElMessage.warning('该'+label+'已不在待处理，请刷新后重试'); return; }
      const rec = list.splice(i, 1)[0];
      const patch = { 审核状态:'已完成', 实施说明: desc || '', 实施附件: files && files!=='—' ? files : '' };
      patch[auditWhoKey()] = CI_OPERATOR;
      patch[auditWhenKey()] = nowStamp();
      Object.assign(rec, patch);
      eaList('tab-2').unshift(rec);
      ElMessage.success(auditExecKey()+'已提交，'+label+' '+rec[auditNoKey()]+' 状态更新为已完成');
    }
    function onEaToolbar(btn){
      if(btn.name==='新增'){ openEaForm('add'); return true; }
      if(btn.name==='批量删除'){ deleteEaRows(); return true; }
      if(btn.name==='导出数据'){ exportVisible.value = true; return true; }
      return false;
    }
    const iaLinkVisible = ref(false);
    const iaLinkNos = ref([]);
    const iaLinkRows = computed(()=>{
      if(!iaLinkVisible.value) return [];
      const set = new Set(iaLinkNos.value);
      const count = pid => pid===IA_EXEC ? iaeLinkCount(set) : pid===IA_RECT ? iarAll().filter(r=> set.has(r['内审单号'])).length : iaBagRows(pid).filter(r=> set.has(r['内审单号'])).length;
      return [
        { 关联单据:'内审实施', page:IA_EXEC, 关联记录数: count(IA_EXEC) },
        { 关联单据:'内审整改', page:IA_RECT, 关联记录数: count(IA_RECT) }
      ];
    });
    function openIaLink(){
      const rows = tableData.value.filter(r=> selectedIds.value.includes(r.id));
      if(!rows.length){ ElMessage.warning('请先勾选数据'); return; }
      iaLinkNos.value = [...new Set(rows.map(r=> r['内审单号']))];
      iaLinkVisible.value = true;
    }
    function goIaLink(row){
      iaLinkVisible.value = false;
      const p = CFG.pages[row.page];
      const nos = iaLinkNos.value.slice();
      onSelectMenu(row.page);
      const tip = '已按内审单号 '+nos.join('、')+' 跳转至「'+(p && p.title || '')+'」';
      if(!p || p.stub){ ElMessage.info(tip+'，该模块原型待完善'); return; }
      const toDone = (row.page===IA_EXEC && !iaePendingRows().some(r=> nos.includes(r['内审单号'])) && iaeDoneList().some(r=> nos.includes(r['内审单号'])))
        || (row.page===IA_RECT && !iarTab('tab-1').some(r=> nos.includes(r['内审单号'])) && iarTab('tab-2').some(r=> nos.includes(r['内审单号'])));
      setTimeout(()=>{
        if(toDone) activeTab.value = 'tab-2';
        if(row.page===IA_RECT){ iarYearId.value = ''; iarYearKw.value = ''; }
        resetQueryModel();
        query['内审单号'] = nos.join('、');
        pageNum.value = 1;
        ElMessage.success(tip + (toDone ? '「已完成」' : ''));
      }, 80);
    }
    function onIaToolbar(btn){
      if(btn.name==='新增'){ openIaForm('add'); return true; }
      if(btn.name==='关联查询'){ openIaLink(); return true; }
      if(btn.name==='关闭'){ closeIaRows(); return true; }
      if(btn.name==='批量删除'){ deleteIaRows(); return true; }
      if(btn.name==='导出数据'){ exportVisible.value = true; return true; }
      return false;
    }
    const IAE_VIEW = ['内审单号','内审年度','审核日期','审核目的','审核准则','审核范围','审核组成员','备注','审核附件','创建时间','创建人'];
    function iaeDoneList(){ return ((MOCK[IA_EXEC]||{})['tab-2']) || []; }
    function iaeDoneRows(){
      const bag = MOCK[IA_EXEC] = MOCK[IA_EXEC] || {};
      if(!Array.isArray(bag['tab-2'])) bag['tab-2'] = [];
      return bag['tab-2'];
    }
    function iaePendingRows(){
      return iaRows().filter(p=> p['内审状态']==='执行中').map(p=>{
        const r = { id:'iae-p-'+p.id };
        IAE_VIEW.forEach(k=>{ r[k] = p[k] || ''; });
        return r;
      });
    }
    const iaePendingCount = computed(()=>{ storeTick.value; return iaePendingRows().length; });
    function iaeLinkCount(set){
      return iaePendingRows().filter(r=> set.has(r['内审单号'])).length + iaeDoneList().filter(r=> set.has(r['内审单号'])).length;
    }
    function iaeQuery(list, done){
      const nos = splitDun(query['内审单号']);
      if(nos.length>1){
        const set = new Set(nos);
        list = list.filter(r=> set.has(r['内审单号']));
      }
      const q = nos.length>1 ? Object.assign({}, query, { 内审单号:'' }) : query;
      const contains = ['内审单号','审核目的','审核准则','审核范围','审核组成员','创建人'].concat(done ? ['变更实施提交人','实施说明'] : []);
      list = applyContainsExactQuery(list, q, contains, ['内审年度']);
      ['审核日期','创建时间'].forEach(k=>{ list = applyDateRangeQuery(list, query, k); });
      if(done) list = applyDateRangeQuery(list, query, '变更实施提交时间');
      return list;
    }
    function openIaeExec(row){
      openProcDlg({
        title:'内审实施', okText:'确定', keys:[],
        fields:[
          { name:'实施说明', type:'input', required:true, placeholder:'输入' },
          { name:'附件', type:'upload', half:true }
        ],
        onSubmit: submitIaeExec
      }, row);
    }
    function submitIaeExec(row, desc, files){
      const p = iaRows().find(x=> x['内审单号']===row['内审单号']);
      if(!p || p['内审状态']!=='执行中'){ ElMessage.warning('该内审计划已不在执行中，请刷新后重试'); return; }
      const rec = { id:'iae-'+Date.now() };
      IAE_VIEW.forEach(k=>{ rec[k] = p[k] || ''; });
      Object.assign(rec, { 实施说明: desc, 实施附件: files, 变更实施提交人: CI_OPERATOR, 变更实施提交时间: nowStamp() });
      iaeDoneRows().unshift(rec);
      p['内审状态'] = '已完成';
      ElMessage.success('内审实施已提交，内审计划 '+p['内审单号']+' 状态更新为已完成');
    }
    function iaeRelQuery(){
      const rows = tableData.value.filter(r=> selectedIds.value.includes(r.id));
      if(!rows.length){ ElMessage.warning('请先勾选数据'); return; }
      const nos = [...new Set(rows.map(r=> r['内审单号']))];
      loadPage(IA_PAGE);
      setTimeout(()=>{
        query['内审单号'] = nos.join('、');
        pageNum.value = 1;
        ElMessage.success('已跳转内审计划，按所选 '+nos.length+' 个内审单号过滤');
      }, 0);
    }
    function onIaeToolbar(btn){
      if(btn.name==='关联查询'){ iaeRelQuery(); return true; }
      if(btn.name==='导出数据'){ exportVisible.value = true; return true; }
      return false;
    }

    const IAR_FIELDS = ['内审整改单号','内审单号','内审年度','体系名称','受审部门','部门负责人','事实陈述','不符合项条款-标准','不符合项条款-体系文件','审核员','审核日期','附件','备注'];
    const IAR_REQUIRED = ['内审整改单号','内审单号','内审年度','体系名称','受审部门','事实陈述'];
    const iarYearId = ref('');
    const iarYearKw = ref('');
    function iarBag(){
      const bag = MOCK[IA_RECT] = MOCK[IA_RECT] || {};
      ['tab-1','tab-2','closed'].forEach(k=>{ if(!Array.isArray(bag[k])) bag[k] = []; });
      if(Array.isArray(bag.main)) delete bag.main;
      return bag;
    }
    function iarTab(name){ return iarBag()[name]; }
    function iarAll(){ const bag = iarBag(); return [...bag['tab-1'], ...bag['tab-2'], ...bag.closed]; }
    function nextIarNo(){
      const max = iarAll().reduce((m, r)=> Math.max(m, parseInt(String(r['内审整改单号']||'').replace(/\D/g,''), 10) || 0), 0);
      return 'ZG' + String(max + 1).padStart(6, '0');
    }
    const iarYearNodes = computed(()=>{
      storeTick.value;
      const years = [...new Set(iarAll().map(r=> r['内审年度']).filter(Boolean))].sort((a, b)=> String(b).localeCompare(String(a)));
      const kw = String(iarYearKw.value || '').trim();
      return kw ? years.filter(y=> String(y).includes(kw)) : years;
    });
    function selectIarYear(year){ iarYearId.value = year; pageNum.value = 1; }
    function clearIarYear(){ iarYearId.value = ''; iarYearKw.value = ''; selectedIds.value = []; pageNum.value = 1; }
    const iarPendingCount = computed(()=>{ storeTick.value; return iarTab('tab-1').length; });
    function iarQuery(list, done){
      if(iarYearId.value) list = list.filter(r=> r['内审年度']===iarYearId.value);
      const nos = splitDun(query['内审单号']);
      if(nos.length>1){
        const set = new Set(nos);
        list = list.filter(r=> set.has(r['内审单号']));
      }
      const q = nos.length>1 ? Object.assign({}, query, { 内审单号:'' }) : query;
      const contains = ['内审整改单号','内审单号','体系名称','受审部门','部门负责人','事实陈述','不符合项条款-标准','不符合项条款-体系文件','审核员','创建人'].concat(done ? ['整改人','原因分析','整改措施','整改说明'] : []);
      list = applyContainsExactQuery(list, q, contains, ['内审年度']);
      ['审核日期','创建时间'].forEach(k=>{ list = applyDateRangeQuery(list, query, k); });
      if(done) list = applyDateRangeQuery(list, query, '整改完成时间');
      return list;
    }
    function iarFormOptions(f){
      if(f.name==='部门负责人' || f.name==='审核员') return CI_USERS.map(u=> ({ value:u.姓名, label:u.工号+' / '+u.姓名 }));
      if(f.name==='内审单号') return iaRows().map(r=> ({ value:r['内审单号'], label:r['内审单号']+' / '+(r['内审年度']||'') }));
      return null;
    }
    function openIarForm(mode, row){
      openForm(mode==='copy' ? 'add' : mode);
      if(mode==='edit'){
        IAR_FIELDS.forEach(k=>{ formModel[k] = row[k]==='—' ? '' : (row[k] || ''); });
        formModel._editId = row.id;
        return;
      }
      const year = new Date().getFullYear()+'年';
      if(mode==='copy' && row){
        IAR_FIELDS.forEach(k=>{ formModel[k] = row[k]==='—' ? '' : (row[k] || ''); });
        formModel['内审整改单号'] = nextIarNo();
        delete formModel._editId;
        return;
      }
      const blank = {};
      IAR_FIELDS.forEach(k=>{ blank[k] = ''; });
      Object.assign(formModel, blank, { 内审整改单号: nextIarNo(), 内审年度: year });
    }
    function saveIarForm(){
      const miss = IAR_REQUIRED.find(k=> !String(formModel[k] || '').trim());
      if(miss){ ElMessage.warning((['内审年度','内审单号','部门负责人','审核员'].includes(miss) ? '请选择' : '请输入') + miss); return; }
      const no = String(formModel['内审整改单号']).trim();
      if(!/^ZG\d{6}$/.test(no)){ ElMessage.warning('内审整改单号须为 ZG 加 6 位数字'); return; }
      if(iarAll().some(r=> r['内审整改单号']===no && r.id!==formModel._editId)){ ElMessage.warning('内审整改单号已存在，请刷新后重新生成'); return; }
      const payload = {};
      IAR_FIELDS.forEach(k=>{ payload[k] = String(formModel[k] || '').trim(); });
      if(formMode.value==='add'){
        iarTab('tab-1').unshift({ id:'iar-'+Date.now(), 整改状态:'待处理', ...payload, 创建时间: nowStamp(), 创建人: CI_OPERATOR });
        ElMessage.success('内审整改已新增');
      } else {
        const cur = iarTab('tab-1').find(r=> r.id===formModel._editId);
        if(!cur){ ElMessage.warning('仅待处理数据可编辑'); return; }
        Object.assign(cur, payload);
        ElMessage.success('已保存');
      }
      formVisible.value = false;
      bumpStore();
    }
    const canCloseIar = computed(()=> pageId.value===IA_RECT && (tabView.value||{}).name==='tab-1' && selectedIds.value.length>0);
    function closeIarRows(){
      const ids = new Set(selectedIds.value);
      const rows = iarTab('tab-1').filter(r=> ids.has(r.id));
      if(!rows.length){ ElMessage.warning('请先勾选待处理数据'); return; }
      ElementPlus.ElMessageBox.confirm('确认关闭所选的 '+rows.length+' 条内审整改？关闭后不再出现在待处理与已完成。', '关闭', { type:'warning' }).then(()=>{
        const bag = iarBag();
        bag['tab-1'] = bag['tab-1'].filter(r=> !ids.has(r.id));
        rows.forEach(r=>{ r['整改状态'] = '已关闭'; bag.closed.unshift(r); });
        selectedIds.value = [];
        bumpStore();
        ElMessage.success('已关闭 '+rows.length+' 条内审整改');
      }).catch(()=>{});
    }
    function deleteIarRows(){
      const ids = new Set(selectedIds.value);
      if(!ids.size){ ElMessage.warning('请先勾选要删除的数据'); return; }
      ElementPlus.ElMessageBox.confirm('确认删除所选的 '+ids.size+' 条内审整改？', '批量删除', { type:'warning' }).then(()=>{
        const bag = iarBag();
        bag['tab-1'] = bag['tab-1'].filter(r=> !ids.has(r.id));
        selectedIds.value = [];
        bumpStore();
        ElMessage.success('已删除 '+ids.size+' 条数据');
      }).catch(()=>{});
    }
    function openIarProcess(row){
      openProcDlg({
        title:'整改处理', okText:'确定', keys:[],
        fields:[
          { name:'原因分析', type:'input', required:true, placeholder:'输入' },
          { name:'整改措施', type:'input', required:true, placeholder:'输入' },
          { name:'整改说明', type:'input', placeholder:'输入' },
          { name:'附件', type:'upload', half:true }
        ],
        onSubmit: submitIarProcess
      }, row);
    }
    function submitIarProcess(row, desc, files, vals){
      const bag = iarBag();
      const idx = bag['tab-1'].findIndex(r=> r.id===row.id);
      if(idx<0){ ElMessage.warning('该整改单已不在待处理，请刷新后重试'); return; }
      const src = bag['tab-1'][idx];
      bag['tab-1'].splice(idx, 1);
      bag['tab-2'].unshift(Object.assign({}, src, {
        整改状态:'已完成',
        原因分析: (vals && vals['原因分析']) || desc,
        整改措施: (vals && vals['整改措施']) || '',
        整改说明: (vals && vals['整改说明']) || '',
        整改报告: files,
        整改完成时间: nowStamp(),
        整改人: CI_OPERATOR
      }));
      ElMessage.success('整改处理已提交，'+src['内审整改单号']+' 已进入已完成');
    }
    function onIarToolbar(btn){
      if(btn.name==='新增'){ openIarForm('add'); return true; }
      if(btn.name==='关闭'){ closeIarRows(); return true; }
      if(btn.name==='批量删除'){ deleteIarRows(); return true; }
      if(btn.name==='导出数据'){ exportVisible.value = true; return true; }
      return false;
    }

    function onCiToolbar(btn){
      if(btn.name==='新增'){ openCiForm('add'); return true; }
      if(btn.name==='关联查询'){ ciRelQuery(); return true; }
      if(btn.name==='关闭'){ closeCiRows(); return true; }
      if(btn.name==='批量删除'){ deleteCiRows(); return true; }
      if(btn.name==='导出数据'){ exportVisible.value = true; return true; }
      return false;
    }

    /** 改进处理：待处理由「执行中」的持续改进按责任部门拆分（一个部门一行）；已完成为各部门提交后的子级数据 */
    const CIP_PAGE = CI_SUB_PAGE;
    const CIP_KEYS = ['提案编号','提案人','提案部门','提案日期','持续改进项目','现有状况描述','改进后状况和改进目标','小组成员','小组组长','备注','创建时间','创建人'];
    const CIP_INFO_KEYS = ['提案编号','责任部门','提案人','提案部门','提案日期','小组组长','小组成员','持续改进项目','现有状况描述','改进后状况和改进目标'];
    const CIP_INFO_FULL = ['小组成员','持续改进项目','现有状况描述','改进后状况和改进目标'];
    function cipDoneList(){ return ((MOCK[CIP_PAGE]||{})['tab-2']) || []; }
    function cipDoneRows(){
      const bag = MOCK[CIP_PAGE] = MOCK[CIP_PAGE] || {};
      if(!Array.isArray(bag['tab-2'])) bag['tab-2'] = [];
      return bag['tab-2'];
    }
    const cipKey = (no, dept)=> no+'|'+dept;
    function cipDoneSet(){ return new Set(cipDoneList().map(r=> cipKey(r['提案编号'], r['责任部门']))); }
    function cipPendingRows(){
      const done = cipDoneSet();
      const out = [];
      ciRows().filter(p=> p['改进状态']==='执行中').forEach(p=>{
        splitDun(p['责任部门']).forEach(d=>{
          if(done.has(cipKey(p['提案编号'], d))) return;
          const r = { id:'cip-'+p.id+'-'+d, 处理状态:'待处理', 责任部门:d };
          CIP_KEYS.forEach(k=>{ r[k] = p[k]; });
          out.push(r);
        });
      });
      return out;
    }
    /** 所有责任部门均已提交 → 持续改进「已完成」；新增了未完成的责任部门 → 回到「执行中」；已关闭不变 */
    function ciSyncStatus(p){
      if(!p || !['执行中','已完成'].includes(p['改进状态'])) return false;
      const done = cipDoneSet();
      const depts = splitDun(p['责任部门']);
      const next = depts.length && depts.every(d=> done.has(cipKey(p['提案编号'], d))) ? '已完成' : '执行中';
      const changed = p['改进状态']!==next;
      p['改进状态'] = next;
      return changed;
    }
    const cipPendingCount = computed(()=>{ storeTick.value; return cipPendingRows().length; });
    function tabBadgeOf(t){
      if(pageId.value===CL_PAGE && t.name==='tab-1') return !clPendingCount.value ? '' : clPendingCount.value > 99 ? '99+' : String(clPendingCount.value);
      if(pageId.value===YS_PAGE && t.name==='tab-1') return !ysPendingCount.value ? '' : ysPendingCount.value > 99 ? '99+' : String(ysPendingCount.value);
      if(pageId.value===IA_EXEC && t.name==='tab-1'){
        const n = iaePendingCount.value;
        return !n ? '' : n > 99 ? '99+' : String(n);
      }
      if(isAuditPage()){
        storeTick.value;
        const n = eaList(t.name==='tab-2' ? 'tab-2' : 'tab-1').length;
        return !n ? '' : n > 99 ? '99+' : String(n);
      }
      if(pageId.value===IA_RECT && t.name==='tab-1'){
        const n = iarPendingCount.value;
        return !n ? '' : n > 99 ? '99+' : String(n);
      }
      if(pageId.value!==CIP_PAGE || t.name!=='tab-1' || !cipPendingCount.value) return '';
      return cipPendingCount.value > 99 ? '99+' : String(cipPendingCount.value);
    }
    /** 处理弹窗（改进处理 / 变更处理 / 抱怨处理共用）：上方只读信息 + 处理字段；未传 fields 时为「处理说明（必填）+ 处理附件」 */
    const procDlg = reactive({ visible:false, title:'', row:null, keys:[], full:[], fields:[], descLabel:'', fileLabel:'', placeholder:'', onSubmit:null });
    const procForm = reactive({ values:{}, files:[] });
    function openProcDlg(opts, row){
      const fields = opts.fields || [
        { name:opts.descLabel, type:'textarea', required:true, placeholder:opts.placeholder },
        { name:opts.fileLabel, type:'upload' },
      ];
      procForm.values = {};
      procForm.files = [];
      Object.assign(procDlg, opts, { fields, row, visible:true, okText: opts.okText || '提交' });
    }
    function submitProcDlg(){
      if(!procDlg.row || !procDlg.onSubmit) return;
      const vals = {};
      for(const f of procDlg.fields){
        if(f.type==='upload'){
          if(f.required && !(procForm.files||[]).length){ ElMessage.warning('请上传'+f.name); return; }
          continue;
        }
        vals[f.name] = String(procForm.values[f.name]||'').trim();
        if(f.required && !vals[f.name]){ ElMessage.warning('请输入'+f.name); return; }
      }
      const files = (procForm.files||[]).map(f=> f.name).filter(Boolean);
      const first = procDlg.fields.find(f=> f.type!=='upload');
      procDlg.onSubmit(procDlg.row, first ? vals[first.name] : '', files.join('、') || '—', vals);
      procDlg.visible = false;
      selectedIds.value = [];
      bumpStore();
    }
    function openCipProcess(row){
      openProcDlg({ title:'改进处理', keys:CIP_INFO_KEYS, full:CIP_INFO_FULL, descLabel:'改进说明', fileLabel:'改进附件', placeholder:'请输入改进措施及完成情况', onSubmit:submitCipProcess }, row);
    }
    function submitCipProcess(row, desc, files){
      const p = ciRows().find(x=> x['提案编号']===row['提案编号']);
      if(!p || p['改进状态']!=='执行中' || cipDoneSet().has(cipKey(row['提案编号'], row['责任部门']))){
        ElMessage.warning('该数据已处理或持续改进已关闭，请刷新后重试');
        return;
      }
      const rec = { id:'cip-'+Date.now(), 处理状态:'已完成', 责任部门: row['责任部门'] };
      CIP_KEYS.forEach(k=>{ rec[k] = p[k]; });
      Object.assign(rec, { 改进说明: desc, 改进附件: files, 改进提交时间: nowStamp(), 改进提交人: CI_OPERATOR });
      cipDoneRows().unshift(rec);
      const finished = ciSyncStatus(p) && p['改进状态']==='已完成';
      ElMessage.success(finished ? '已提交；提案 '+p['提案编号']+' 的所有责任部门均已完成，持续改进状态更新为【已完成】' : '改进处理已提交');
    }
    function cipRelQuery(){
      const rows = tableData.value.filter(r=> selectedIds.value.includes(r.id));
      if(!rows.length){ ElMessage.warning('请先勾选数据'); return; }
      const nos = [...new Set(rows.map(r=> r['提案编号']))];
      loadPage(CI_PAGE);
      setTimeout(()=>{
        query['提案编号'] = nos.join('、');
        pageNum.value = 1;
        ElMessage.success('已跳转持续改进，按所选 '+nos.length+' 个提案编号过滤');
      }, 0);
    }
    function onCipToolbar(btn){
      if(btn.name==='关联查询'){ cipRelQuery(); return true; }
      if(btn.name==='导出数据'){ exportVisible.value = true; return true; }
      return false;
    }

    /** 变更处理：新增后进入待处理（执行中）；变更处理提交后移入已完成 */
    const CHG_PAGE = 'np-0210-01';
    const CHG_FIELDS = ['变更编号','变更类型','变更来源','变更项目名称','变更涉及产品','变更等级','变更时效','是否需要验证','变更附件','变更说明及技术依据','变更备注','申请人','申请部门','申请日期'];
    const CHG_REQUIRED = ['变更编号','变更类型','变更来源','变更项目名称','变更说明及技术依据','申请人','申请部门','申请日期'];
    const CHG_SELECTS = ['变更类型','变更来源','申请人','申请部门','申请日期'];
    const CHG_INFO_KEYS = ['变更编号','变更类型','变更来源','变更等级','变更时效','是否需要验证','申请人','申请部门','申请日期','变更项目名称','变更涉及产品','变更附件','变更说明及技术依据','变更备注'];
    const CHG_INFO_FULL = ['变更项目名称','变更涉及产品','变更附件','变更说明及技术依据','变更备注'];
    function chgTab(t){
      const bag = MOCK[CHG_PAGE] = MOCK[CHG_PAGE] || {};
      if(!Array.isArray(bag[t])) bag[t] = [];
      return bag[t];
    }
    function chgAllRows(){ return [...chgTab('tab-1'), ...chgTab('tab-2')]; }
    function nextChgNo(){
      const max = chgAllRows().reduce((m, r)=> Math.max(m, parseInt(String(r['变更编号']||'').replace(/\D/g,''), 10) || 0), 0);
      return String(max + 1).padStart(6, '0');
    }
    function chgFormOptions(f){
      if(f.name==='申请人') return CI_USERS.map(u=> ({ value:u.姓名, label:u.工号+' / '+u.姓名 }));
      if(f.name==='申请部门') return ciDeptsOf(formModel['申请人']).map(d=> ({ value:d, label:d }));
      return null;
    }
    function onChgApplicantChange(){
      const ds = ciDeptsOf(formModel['申请人']);
      formModel['申请部门'] = ds.length===1 ? ds[0] : (ds.includes(formModel['申请部门']) ? formModel['申请部门'] : '');
    }
    function openChgForm(mode, row){
      openForm(mode);
      if(mode==='edit'){
        CHG_FIELDS.forEach(k=>{ formModel[k] = row[k]==='—' ? '' : (row[k]||''); });
        formModel._editId = row.id;
        return;
      }
      Object.assign(formModel, { 变更编号: nextChgNo(), 申请人: CI_OPERATOR, 申请日期: nowStamp().slice(0,10) });
      onChgApplicantChange();
    }
    function saveChgForm(){
      const miss = CHG_REQUIRED.find(k=> !String(formModel[k]||'').trim());
      if(miss){ ElMessage.warning((CHG_SELECTS.includes(miss) ? '请选择' : '请输入') + miss); return; }
      const no = String(formModel['变更编号']).trim();
      if(chgAllRows().some(r=> r['变更编号']===no && r.id!==formModel._editId)){ ElMessage.warning('变更编号已存在，请刷新后重新生成'); return; }
      const payload = {};
      CHG_FIELDS.forEach(k=>{ payload[k] = String(formModel[k]||'').trim(); });
      if(formMode.value==='add'){
        chgTab('tab-1').unshift({ id:'chg-'+Date.now(), 变更状态:'执行中', ...payload, 创建时间: nowStamp(), 创建人: CI_OPERATOR });
        ElMessage.success('变更已新增');
      } else {
        const cur = chgTab('tab-1').find(r=> r.id===formModel._editId);
        if(!cur){ ElMessage.warning('未找到待编辑的数据'); return; }
        Object.assign(cur, payload);
        ElMessage.success('保存成功');
      }
      formVisible.value = false;
      bumpStore();
    }
    function openChgProcess(row){
      openProcDlg({ title:'变更处理', keys:CHG_INFO_KEYS, full:CHG_INFO_FULL, descLabel:'变更处理说明', fileLabel:'变更处理附件', placeholder:'请输入变更执行及验证情况', onSubmit:submitChgProcess }, row);
    }
    function submitChgProcess(row, desc, files){
      const pending = chgTab('tab-1');
      const cur = pending.find(r=> r.id===row.id);
      if(!cur){ ElMessage.warning('该变更已处理，请刷新后重试'); return; }
      MOCK[CHG_PAGE]['tab-1'] = pending.filter(r=> r!==cur);
      chgTab('tab-2').unshift(Object.assign({}, cur, { 变更状态:'已完成', 变更处理说明: desc, 变更处理附件: files, 变更处理提交人: CI_OPERATOR, 变更处理提交时间: nowStamp() }));
      ElMessage.success('变更 '+cur['变更编号']+' 已处理完成');
    }
    function onChgToolbar(btn){
      if(btn.name==='新增'){ openChgForm('add'); return true; }
      if(btn.name==='导出数据'){ exportVisible.value = true; return true; }
      return false;
    }

    /** 客户质量（客户抱怨 / 客户投诉）：新增后进入待处理；处理提交后移入已处理 */
    function makeCsPage(o){
      function tab(t){
        const bag = MOCK[o.page] = MOCK[o.page] || {};
        if(!Array.isArray(bag[t])) bag[t] = [];
        return bag[t];
      }
      const LIST = o.listTab || 'tab-1';
      const ST = o.statusKey || '处理状态';
      const ST_PENDING = o.pendingStatus || '待处理';
      const ST_DONE = o.doneStatus || '已处理';
      const NEW_WHO = o.newWhoKey || '制单人';
      const NEW_WHEN = o.newWhenKey || '制单时间';
      const DONE_WHO = o.doneWhoKey || '处理人';
      const DONE_WHEN = o.doneWhenKey || '处理时间';
      const MULTI = o.multiFields || [];
      const allRows = ()=> [...tab(LIST), ...(LIST==='tab-1' ? tab('tab-2') : [])];
      function nextNo(){
        const max = allRows().reduce((m, r)=> Math.max(m, parseInt(String(r[o.noKey]||'').replace(/\D/g,''), 10) || 0), 0);
        return String(max + 1).padStart(6, '0');
      }
      function fillFrom(row){
        o.fields.forEach(k=>{
          let v = row[k]==='—' ? '' : (row[k]||'');
          if(MULTI.includes(k)) v = String(v).split(/[、,，]/).map(s=> s.trim()).filter(Boolean);
          formModel[k] = v;
        });
      }
      function openEdit(mode, row){
        openForm(mode==='copy' ? 'add' : mode);
        if(mode==='edit'){
          fillFrom(row);
          formModel._editId = row.id;
          return;
        }
        if(mode==='copy'){
          fillFrom(row);
          formModel[o.noKey] = nextNo();
          return;
        }
        Object.assign(formModel, { [o.noKey]: nextNo() }, o.dateKey ? { [o.dateKey]: nowStamp().slice(0,10) } : {}, o.addDefaults || {});
      }
      function save(){
        const miss = o.required.find(k=> !String(formModel[k]||'').trim());
        if(miss){ ElMessage.warning((o.selects.includes(miss) ? '请选择' : '请输入') + miss); return; }
        const no = String(formModel[o.noKey]).trim();
        if(allRows().some(r=> r[o.noKey]===no && r.id!==formModel._editId)){ ElMessage.warning(o.noKey+'已存在，请刷新后重新生成'); return; }
        const payload = {};
        o.fields.forEach(k=>{
          const v = formModel[k];
          payload[k] = Array.isArray(v) ? v.join('、') : String(v||'').trim();
        });
        if(o.fields.includes('客户信息') && !payload['客户名称']){
          const [code, name] = payload['客户信息'].split(' / ');
          Object.assign(payload, { 客户编码: name ? code : '', 客户名称: name || code });
        }
        if(o.normalize) o.normalize(payload);
        if(formMode.value==='add'){
          const row = { id:o.idPrefix+Date.now(), ...(o.procOp || o.statusKey ? { [ST]: ST_PENDING } : {}), ...payload, [NEW_WHEN]: nowStamp(), [NEW_WHO]: CI_OPERATOR };
          if(o.page===SR_PAGE) Object.assign(row, { 主题:'供应商在线整改', 密码: srRandPwd(), 分享人: CI_OPERATOR, 在线填写链接: srLinkOf(row) });
          tab(LIST).unshift(row);
          ElMessage.success(o.addOkTip || (o.title+'已新增'));
        } else {
          const cur = tab(LIST).find(r=> r.id===formModel._editId);
          if(!cur){ ElMessage.warning('该'+o.docName+'已处理，不可编辑'); return; }
          if(o.page===SR_PAGE && cur['单据状态']!=='待处理'){ ElMessage.warning('仅待处理的整改单可编辑'); return; }
          Object.assign(cur, payload);
          ElMessage.success('保存成功');
        }
        if(o.onSaved) o.onSaved(payload);
        formVisible.value = false;
        bumpStore();
      }
      function batchDelete(){
        const rows = tab(LIST).filter(r=> selectedIds.value.includes(r.id));
        if(!rows.length){ ElMessage.warning('请先勾选数据'); return; }
        const blocked = o.deleteBlock ? rows.filter(o.deleteBlock) : [];
        if(blocked.length){ ElMessage.warning(o.noKey+' '+blocked.map(r=> r[o.noKey]).join('、')+' '+o.deleteBlockTip); return; }
        ElementPlus.ElMessageBox.confirm('确定删除所选 '+rows.length+' 条'+o.docName+'吗？删除后不可恢复。', '提示', { type:'warning', confirmButtonText:'确定', cancelButtonText:'取消' }).then(()=>{
          const ids = new Set(rows.map(r=> r.id));
          MOCK[o.page][LIST] = tab(LIST).filter(r=> !ids.has(r.id));
          selectedIds.value = [];
          if(o.onDeleted) o.onDeleted(rows.map(r=> r[o.noKey]));
          bumpStore();
          ElMessage.success('已删除 '+rows.length+' 条数据');
        }).catch(()=>{});
      }
      function submitProcess(row, desc, files, vals){
        const pending = tab('tab-1');
        const cur = pending.find(r=> r.id===row.id);
        if(!cur){ ElMessage.warning('该'+o.docName+'已处理，请刷新后重试'); return; }
        MOCK[o.page]['tab-1'] = pending.filter(r=> r!==cur);
        const rec = Object.assign({}, cur, { [ST]: ST_DONE, [DONE_WHO]: CI_OPERATOR, [DONE_WHEN]: nowStamp() });
        o.procFields.forEach(f=>{ rec[f.key || f.name] = f.type==='upload' ? files : (vals[f.name] || ''); });
        if(o.onProcess) o.onProcess(rec, vals);
        tab('tab-2').unshift(rec);
        ElMessage.success(o.procOkTip ? o.procOkTip(cur) : (o.docName+' '+cur[o.noKey]+' 已处理'));
      }
      function openProcess(row){
        openProcDlg({ title:o.procOp, keys:o.infoKeys, full:o.infoFull, fields:o.procFields, onSubmit:submitProcess }, row);
      }
      function onToolbar(btn){
        if(btn.name==='新增'){ openEdit('add'); return true; }
        if(btn.name==='批量删除'){ batchDelete(); return true; }
        if(btn.name==='导出数据'){ exportVisible.value = true; return true; }
        return false;
      }
      function onRowOp(op, row){
        if(op.name==='编辑'){ openEdit('edit', row); return true; }
        if(op.name==='复制'){ openEdit('copy', row); return true; }
        if(o.procOp && op.name===o.procOp){ openProcess(row); return true; }
        return false;
      }
      function onRefresh(f){
        if(!f || f.name!==o.noKey) return false;
        formModel[o.noKey] = nextNo();
        ElMessage.success('已刷新'+o.noKey);
        return true;
      }
      function rows(list, done){
        if(o.decorate) list = list.map(r=> Object.assign({}, r, o.decorate(r)));
        list = applyContainsExactQuery(list, query, [...o.containsKeys, ...(done ? [DONE_WHO] : [])], o.exactKeys);
        [...o.dateKeys, ...(done ? [DONE_WHEN] : [])].forEach(k=>{ list = applyDateRangeQuery(list, query, k); });
        const sortKey = done ? DONE_WHEN : NEW_WHEN;
        return list.slice().sort((a,b)=> String(b[sortKey]||'').localeCompare(String(a[sortKey]||'')));
      }
      return { page:o.page, nextNo, save, onToolbar, onRowOp, onRefresh, rows };
    }
    /** 品质专项任务·逾期状态：当前时间≤计划完成时间为正常，否则逾期（按日期比较，当天不算逾期） */
    function qtOverdueState(r){
      const done = r['任务状态']==='已完成';
      const plan = String(r['计划完成时间']||'').slice(0,10);
      if(!plan) return r['逾期状态'] || '—';
      if(done) return r['逾期状态'] || (String(r['完成时间']||'').slice(0,10) > plan ? '逾期' : '正常');
      return nowStamp().slice(0,10) > plan ? '逾期' : '正常';
    }
    /** 客诉单保存/删除后，把客诉单号反写到发货OQC台账的「客诉单号」；同一OQC多单关联以「，」拼接 */
    function ctSyncOqcLink(ctNo, oqcNo){
      const bag = MOCK[OQC_PAGE] || {};
      const norm = v=> String(v||'').split(/[，,、]/).map(s=> s.trim()).filter(s=> s && s!=='—');
      const link = String(oqcNo||'').trim();
      ['tab-1','tab-2'].forEach(t=>{
        (bag[t]||[]).forEach(r=>{
          const list = norm(r['客诉单号']);
          const kept = list.filter(x=> x!==ctNo);
          if(link && r['单据号']===link && !kept.includes(ctNo)) kept.push(ctNo);
          if(kept.length!==list.length || kept.some((x,i)=> x!==list[i])) r['客诉单号'] = kept.join('，');
        });
      });
    }
