    function hmWriteLib(row){
      if(!row || !hmDone(row)) return;
      const list = hmLibRows();
      if(list.some(x=> x['来源申请单号']===row['申请单号'] || x['文件编号']===row['文件编号'])) return;
      const applyDate = String(row['创建时间']||nowStamp()).slice(0,10);
      const archNodes = (CFG.pages[HM_ARCH_PAGE] && CFG.pages[HM_ARCH_PAGE].treeNodes) || [];
      const matCat = String(row['物料类'] || '').trim() || archNodes[0] || '';
      if(!matCat){ ElMessage.warning('导入单缺少物料类，无法写入文件库'); return; }
      const rec = {
        id: 'hmlib-'+Date.now().toString(36)+Math.random().toString(36).slice(2,5),
        物料类: matCat,
        文件编号: row['文件编号'] || '',
        文件名称: row['文件名称'] || '',
        文件: row['文件'] || '',
        内容描述: row['内容描述'] || '',
        文件类型: hmFileTypeName(row['文件类型']) || '',
        客户编码: row['客户编码'] || '',
        客户名称: row['客户名称'] || '—',
        法规名称: row['法规名称'] || '—',
        使用期限类型: row['使用期限类型'] || '',
        生效日期: row['生效日期'] || '—',
        使用周期: row['使用周期'] || '—',
        提前预警: row['提前预警'] || '—',
        提前预警单位: row['提前预警单位'] || '天',
        失效日期: row['失效日期'] || '—',
        备注: row['备注'] || '',
        来源申请单号: row['申请单号'] || '',
        创建人: row['创建人'] || CI_OPERATOR,
        创建时间: nowStamp(),
        _history: [{ 操作类型:'导入', 申请人: row['创建人']||CI_OPERATOR, 申请日期: applyDate, 申请单号: row['申请单号']||'', _srcPage: HM_IMP_PAGE }]
      };
      rec['使用状态'] = hmLibStatus(rec);
      list.unshift(rec);
    }
    function hmSyncLibFromImp(){
      hmLibBag();
      hmImpRows().filter(hmDone).forEach(hmWriteLib);
      hmLibRows().forEach(r=>{ r['使用状态'] = hmLibStatus(r); });
      hmSyncVoid();
      hmSyncChg();
    }
    const HM_FLOW_HEAD = ['申请单号','文件编号','文件名称','物料类','文件类型','客户名称','法规名称','使用期限类型','生效日期','使用周期','提前预警','失效日期','内容描述','备注','审核单号','创建人','创建时间'];
    const HM_FLOW_LINE = ['标准编号','标准名称','测试值','单位','比对结果'];
    function hmFlowRows(){
      const out = [];
      hmImpRows().filter(r=> hmDone(r) && String(r['文件类型']||'').trim()==='厂内文件').forEach(r=>{
        (r._entryLines||[]).forEach((l,i)=>{
          const rec = { id: r.id+'-f'+(l.id||i), _srcPage: HM_IMP_PAGE, _srcId: r.id };
          HM_FLOW_HEAD.forEach(k=>{ rec[k] = r[k]==null?'':r[k]; });
          HM_FLOW_LINE.forEach(k=>{ rec[k] = l[k]==null?'':l[k]; });
          out.push(rec);
        });
      });
      return out;
    }
