    function kpiSchemeInUse(name){
      if(!name) return false;
      return ((MOCK['lg-kpi-plan']||{}).main||[]).some(r=> r['方案名称']===name)
        || ((MOCK['lg-kpi-record']||{}).main||[]).some(r=> r['方案名称']===name);
    }
    function kpiSchemeByName(name){
      return ((MOCK['lg-kpi-scheme']||{}).main||[]).find(r=> r['方案名称']===name) || null;
    }
    function kpiGradeOf(score, schemeOrPlan){
      let grades = schemeOrPlan && schemeOrPlan._grades;
      if(!grades || !grades.length){
        const sch = kpiSchemeByName(schemeOrPlan && schemeOrPlan['方案名称']);
        grades = (sch && sch._grades) || defaultKpiGrades();
      }
      const n = Number(score);
      for(const g of grades){
        const lo = Number(g['总分下限']), hi = Number(g['总分上限']);
        if(!Number.isNaN(n) && n>=lo && n<=hi) return g['对应结果']||'';
      }
      return '';
    }
    function cloneKpi(obj){ return JSON.parse(JSON.stringify(obj||[])); }
    function openKpiCfg(row){
      kpiCfgRow.value = row;
      kpiGrades.value = cloneKpi(row._grades && row._grades.length ? row._grades : defaultKpiGrades());
      kpiProjects.value = cloneKpi(row._projects && row._projects.length ? row._projects : defaultKpiProjects());
      kpiGradeSel.value = [];
      kpiProjSel.value = [];
      kpiCfgVisible.value = true;
    }
    function addKpiGrade(){ kpiGrades.value.push({ 总分下限:'', 总分上限:'', 对应结果:'合格', 备注:'' }); }
    function delKpiGrades(){
      const set = new Set(kpiGradeSel.value);
      kpiGrades.value = kpiGrades.value.filter(r=> !set.has(r));
      kpiGradeSel.value = [];
    }
    function addKpiProject(){ kpiProjects.value.push({ 考评项目:'', 评价部门:'物流部', 负责人:'张三', _indicators:[] }); }
    function delKpiProjects(){
      const set = new Set(kpiProjSel.value);
      kpiProjects.value = kpiProjects.value.filter(r=> !set.has(r));
      kpiProjSel.value = [];
    }
    function addKpiIndicator(proj){
      const n = (proj._indicators||[]).length + 1;
      (proj._indicators = proj._indicators || []).push({ 代号:'IND'+String(n).padStart(2,'0'), 考评内容:'', 配分:'', 评分标准:'', 备注:'' });
    }
    function delKpiIndicators(proj){
      if(!(proj._indicators||[]).length) return;
      proj._indicators.pop();
    }
    function moveKpiProject(i, dir){
      const j = i + dir;
      if(j<0 || j>=kpiProjects.value.length) return;
      const arr = kpiProjects.value.slice();
      [arr[i], arr[j]] = [arr[j], arr[i]];
      kpiProjects.value = arr;
    }
    function moveKpiIndicator(proj, i, dir){
      const arr = proj._indicators || [];
      const j = i + dir;
      if(j<0 || j>=arr.length) return;
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    function onKpiCfgOk(){
      const grades = kpiGrades.value || [];
      if(grades.some(g=> !String(g['对应结果']||'').trim())){ ElMessage.warning('请填写对应结论结果'); return; }
      const ranges = grades.map(g=>[Number(g['总分下限']), Number(g['总分上限'])]).filter(x=> !Number.isNaN(x[0]) && !Number.isNaN(x[1]));
      ranges.sort((a,b)=> a[0]-b[0]);
      for(let i=1;i<ranges.length;i++){
        if(ranges[i][0] <= ranges[i-1][1]){ ElMessage.warning('结论配置的总分上下限区间不能交叉重叠'); return; }
      }
      if(kpiProjects.value.some(p=> !String(p['考评项目']||'').trim())){ ElMessage.warning('请输入考评项目名称'); return; }
      let sum = 0;
      for(const p of kpiProjects.value){
        for(const ind of (p._indicators||[])){
          const n = Number(ind['配分']);
          if(!(n>0)){ ElMessage.warning('考评指标配分必须为大于0的数值'); return; }
          sum += n;
        }
      }
      if(sum && Math.abs(sum-100)>0.01){
        ElMessage.warning('考评指标配分总和建议为100分，当前总计为 '+sum.toFixed(2)+' 分，请检查');
        return;
      }
      const row = kpiCfgRow.value;
      if(row){
        row._grades = cloneKpi(kpiGrades.value);
        row._projects = cloneKpi(kpiProjects.value);
      }
      kpiCfgVisible.value = false;
      bumpStore();
      ElMessage.success('分数项配置已成功保存');
    }
    function kpiProjectScore(proj){
      return (proj && proj._indicators || []).reduce((s,i)=> s + (Number(i['得分']||0)||0), 0);
    }
    function openKpiScore(vendor, readonly){
      kpiScoreReadonly.value = !!readonly;
      kpiScoreVendor.value = vendor || {};
      const sch = kpiSchemeByName(detailRow.value?.['方案名称']);
      kpiCfgRow.value = sch || detailRow.value;
      const scores = cloneKpi(vendor._scores || []);
      const projects = cloneKpi((sch && sch._projects) || defaultKpiProjects());
      const byCode = Object.fromEntries(scores.map(s=>[s['代号']||s['考评内容'], s]));
      projects.forEach(p=>{
        (p._indicators||[]).forEach(ind=>{
          const hit = byCode[ind['代号']] || byCode[ind['考评内容']] || {};
          ind['得分'] = hit['得分'] ?? '';
          ind['备注'] = hit['备注'] ?? '';
        });
      });
      kpiScoreProjects.value = projects;
      kpiScoreExplain.value = vendor['考评说明'] || (detailRow.value?.['内容描述'] || '');
      kpiScoreRemark.value = vendor['备注'] && vendor['备注']!=='—' ? vendor['备注'] : '';
      kpiScoreVisible.value = true;
    }
    function onKpiScoreOk(){
      for(const p of kpiScoreProjects.value){
        for(const ind of (p._indicators||[])){
          if(ind['得分']==='' || ind['得分']===undefined || ind['得分']===null){
            ElMessage.warning('请完整填写所有指标的考核得分'); return;
          }
          const n = Number(ind['得分']);
          const max = Number(ind['配分']);
          if(Number.isNaN(n) || n<0){ ElMessage.warning('指标得分不能为负数'); return; }
          if(n>max){ ElMessage.warning('指标得分不能超过最大配分 ('+max+'分)'); return; }
        }
      }
      const vendor = kpiScoreVendor.value;
      const scores = [];
      (kpiScoreProjects.value||[]).forEach(p=>{
        (p._indicators||[]).forEach(ind=>{
          scores.push({ 代号:ind['代号'], 考评内容:ind['考评内容'], 配分:ind['配分'], 评分标准:ind['评分标准'], 得分:Number(ind['得分']).toFixed(2), 备注:ind['备注']||'' });
          vendor[ind['考评内容']] = Number(ind['得分']).toFixed(2);
        });
      });
      vendor._scores = scores;
      vendor['总得分'] = kpiScoreTotal.value.toFixed(2);
      vendor['评定结果'] = kpiScoreGrade.value || '—';
      vendor['考评说明'] = kpiScoreExplain.value || '';
      vendor['备注'] = kpiScoreRemark.value || '—';
      const plan = ((MOCK['lg-kpi-plan']||{}).main||[]).find(r=> r.id===detailRow.value?.id) || detailRow.value;
      if(plan && (plan['复核状态']==='置空' || !plan['复核状态'])){
        plan['复核状态'] = '待复核';
        if(detailRow.value) detailRow.value['复核状态'] = '待复核';
      }
      kpiScoreVisible.value = false;
      bumpStore();
      ElMessage.success('考评分数已提交，状态变更为待复核');
    }
    function onKpiVendorDelete(){
      const set = new Set(kpiVendorSel.value);
      const plan = ((MOCK['lg-kpi-plan']||{}).main||[]).find(r=> r.id===detailRow.value?.id) || detailRow.value;
      if(!plan) return;
      plan._vendors = (plan._vendors||[]).filter(v=> !set.has(v));
      if(detailRow.value) detailRow.value._vendors = plan._vendors;
      kpiVendorSel.value = [];
      bumpStore();
      ElMessage.success('选中的供应商考评明细已删除');
    }
    function openKpiFlow(row){
      kpiFlowRow.value = row || {};
      kpiFlowNodes.value = cloneKpi(row._flow || []);
      kpiFlowVisible.value = true;
    }
    function addrNorm(s){
      const t = String(s||'').trim();
      const desc = t.includes(' / ') ? t.split(' / ').slice(1).join(' / ') : t;
      return desc.replace(/\s+/g,'').toLowerCase();
    }
    function addrMatch(a, b){
      const x = addrNorm(a), y = addrNorm(b);
      if(!x || !y) return false;
      return x===y || x.includes(y) || y.includes(x);
    }
    function lookupFreightPrice(from, to){
      const rows = ((MOCK.freight||{}).main||[]).filter(r => r['启用状态']!=='禁用');
      const hit = rows.find(r => addrMatch(r['发货地'], from) && addrMatch(r['收货地'], to));
      return hit ? String(hit['运费单价']||'') : '';
    }
    function onMergeShipOk(){
      if(!mergeForm.承运商名称){ ElMessage.warning('请选择承运商'); return; }
      if(!mergeForm.计划装货时间){ ElMessage.warning('请选择计划装货时间'); return; }
      if(!mergeForm.运输类型){ ElMessage.warning('请选择运输类型'); return; }
      const rows = mergeShipRows.value || [];
      if(!rows.length){ ElMessage.warning('请勾选待调度发货单'); return; }
      const d = new Date();
      const ymd = `${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}`;
      const pad = n => String(n).padStart(2,'0');
      const wb = (MOCK['lg-waybill'] = MOCK['lg-waybill'] || { main: [] });
      wb.main = wb.main || [];
      const wayNo = 'YD' + ymd + String(wb.main.length + 1).padStart(4,'0');
      const dns = rows.map(r=> r['发货单号']).filter(Boolean);
      const first = rows[0] || {};
      const qtySum = rows.reduce((s,r)=> s + (Number(String(r['发货数量']||'').replace(/[^\d.]/g,''))||0), 0);
      const planTime = mergeForm.计划装货时间;
      wb.main.unshift({
        id: String(wb.main.length+1),
        运单号: wayNo,
        状态: '待派车',
        结算状态: '/',
        关联发货单: dns.join('、'),
        关联订单类型: (()=>{
          const ord = String(first['订单号']||first['关联订单号']||'');
          if(/^SO/i.test(ord) || first['用车类型']==='发货') return '销售订单';
          if(/^PO/i.test(ord) || first['用车类型']==='提货') return '采购订单';
          if(/^WW/i.test(ord)) return '委外订单';
          return first['关联订单类型'] || '—';
        })(),
        关联订单号: (()=>{
          const ord = String(first['关联订单号']||first['订单号']||'');
          return (ord.split(/\s*\/\s*/)[0]||'').trim() || '—';
        })(),
        关联出库单号: first['关联出库单号'] || first['出/入库单号'] || '—',
        物料信息: [...new Set(rows.map(r=> r['物料信息']).filter(Boolean))].join('；'),
        总数量: String(qtySum),
        申请部门: first['申请部门']||'',
        申请人: first['申请人']||'',
        用车类型: first['用车类型']||'',
        仓库业务类型: resolveWhBizType(first),
        运输类型: mergeForm.运输类型,
        '运费单价（元）': mergeForm.运费单价===undefined || mergeForm.运费单价===null ? '' : String(mergeForm.运费单价).trim(),
        装货点: [...new Set(rows.map(r=> r['装货点']).filter(v=> v && v!=='—'))].join('、') || '—',
        装货联系人: first['装货联系人'] || rows.map(r=> r['装货联系人']).find(v=> v && v!=='—') || '',
        装货联系电话: first['装货联系电话'] || rows.map(r=> r['装货联系电话']).find(v=> v && v!=='—') || '',
        卸货点: [...new Set(rows.map(r=> r['卸货点']).filter(v=> v && v!=='—'))].join('、') || '—',
        卸货联系人: first['卸货联系人'] || rows.map(r=> r['卸货联系人']).find(v=> v && v!=='—') || '',
        卸货联系电话: first['卸货联系电话'] || rows.map(r=> r['卸货联系电话']).find(v=> v && v!=='—') || '',
        车型要求: first['车型要求']||'',
        是否带托盘: first['是否带托盘']||'',
        特殊要求: first['特殊要求']||'—',
        计划装货时间: planTime,
        实际装货时间: '—',
        要求送达时间: rows.map(r=> r['要求送达时间']).filter(Boolean).sort()[0] || '—',
        预计到货时间: '—',
        实际到货时间: '—',
        客户名称: (String(first['订单号']||'').split(/\s*\/\s*/)[1]||'').trim() || '—',
        '出/入库单号': '—',
        订单号: first['订单号']||'',
        合同号: first['合同号']||'',
        采购订单: first['采购订单']||'',
        承运商名称: mergeForm.承运商名称,
        车牌号: '—',
        车挂号: '—',
        司机姓名: '—',
        司机电话: '—',
        驾驶证号: '—',
        从业资格证号: '—',
        押运员姓名: '—',
        押运员资格证号: '—',
        创建时间: `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`,
        _lines: rows.map(r=>{
          const thNo = buildPickupFromShip(r, wayNo, {
            创建时间: `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`
          });
          return {
            关联发货单号: r['发货单号']||'',
            关联仓储通知单: r['关联仓储通知单']||'—',
            装货点: r['装货点']||'',
            卸货点: r['卸货点']||'',
            物料信息: r['物料信息']||'',
            发货数量: r['发货数量']||'',
            关联提货单: thNo,
            关联签收单: '—'
          };
        })
      });
      rows.forEach((r, idx)=>{
        const whBiz = resolveWhBizType(r);
        const notice = whBiz === '无' || whBiz === '—' ? '—' : noticeNoByWhBiz(whBiz, ymd, wb.main.length + idx + 1);
        const cur = ((MOCK['lg-ship']||{}).main||[]).find(s=> s.id===r.id || s['发货单号']===r['发货单号']);
        if(cur){
          cur['状态'] = '已调度';
          cur['关联运单'] = wayNo;
          cur['关联仓储通知单'] = notice;
          if(!cur['仓库业务类型']) cur['仓库业务类型'] = whBiz;
        }
        r['状态'] = '已调度';
        r['关联运单'] = wayNo;
        r['关联仓储通知单'] = notice;
        // 通知单延至运单「确认派车」后生成，以便带入承运信息与行默认值
      });
      if(wb.main[0] && Array.isArray(wb.main[0]._lines)){
        wb.main[0]._lines.forEach(l=>{
          const ship = rows.find(s=> s['发货单号']===l['关联发货单号']);
          if(ship) l['关联仓储通知单'] = ship['关联仓储通知单'] || '—';
        });
      }
      const srcNos = [...new Set(rows.map(r=> r['来源派车单号']).filter(Boolean))];
      srcNos.forEach(no=> refreshDispatchProgress(findDispatchByNo(no)));
      selectedIds.value = [];
      mergeVisible.value = false;
      bumpStore();
      ElMessage.success(`发货单合并下发成功，已生成运单 (${wayNo})；仓储通知单将在运单确认派车后生成`);
    }
    /* ===== 质量闭环：检验完成 → 待复核 → 复核（不合格 → 不合格处置 / 异常 → 偏差处置）→ MRB评审 → 回写处置单；内部整改 → 整改处理 ===== */
    const QC_UQ = { 'tab-pi':'unqual-pi', 'tab-pp':'unqual-pp', 'tab-pm':'unqual-pm', 'tab-rd':'unqual-rd' };
    const QC_DV = { 'tab-pi':'dev-pi', 'tab-pp':'dev-pp', 'tab-pm':'dev-pm', 'tab-rd':'dev-rd' };
    const QC_SRC_TYPE = { 'unqual-pi':'采购来料不合格', 'unqual-pp':'生产过程不合格', 'unqual-pm':'生产物料不合格', 'unqual-rd':'研发不合格处置', 'dev-pi':'采购来料偏差', 'dev-pp':'生产过程偏差', 'dev-pm':'生产物料偏差', 'dev-rd':'研发偏差' };
    const QC_CAPA_SRC = { 采购来料不合格:['unqual-pi','tab-done'], 生产过程不合格:['unqual-pp','tab-done'], 生产物料不合格:['unqual-pm','tab-done'], 研发不合格处置:['unqual-rd','tab-done'], 采购来料偏差:['dev-pi','tab-done'], 生产过程偏差:['dev-pp','tab-done'], 生产物料偏差:['dev-pm','tab-done'], 研发偏差:['dev-rd','tab-done'], 客户投诉:[CT_PAGE,'tab-1'] };
    const QC_ADD_DEFAULTS = { 'np-0201-01':{ 单据状态:'待审批' }, 'np-0201-02':{ 单据状态:'未完成' }, 'capa-internal':{ 整改状态:'待发起' }, 'np-0215-05':{ 审核状态:'/', 审核单号:'—' } };
    const CAPA_LAUNCHABLE = '待发起';
    function capaInternalPicked(){ return (tableData.value||[]).filter(r=> selectedIds.value.includes(r.id)); }
    function capaAllLaunchable(rows){ return !!(rows||[]).length && rows.every(r=> r['整改状态']===CAPA_LAUNCHABLE); }
    const canCapaClose = computed(()=> pageId.value==='capa-internal' && capaAllLaunchable(capaInternalPicked()));
    const canCapaBatchDelete = computed(()=> pageId.value==='capa-internal' && capaAllLaunchable(capaInternalPicked()));
    const MRB_WB_KEY = 'dingcai-qms-mrb-writeback';
    /** 只改行上已有的字段：源码 Mock 行多出字段会被判为结构变化，刷新后整页缓存被丢弃 */
    function qcSetKnown(row, obj){ Object.keys(obj).forEach(k=>{ if(k.startsWith('_') || k in row) row[k] = obj[k]; }); }
    function qcAllRows(pid){ return Object.values(MOCK[pid]||{}).filter(Array.isArray).flat(); }
    /** 取已有单号中数字最大的一个 +1，保持原前缀和位数 */
    function qcNextNo(rows, key, fallbackPrefix){
      let prefix = '', max = -1, width = 0;
      (rows||[]).forEach(r=>{
        const m = /^(.*?)(\d+)$/.exec(String(r[key]||''));
        if(!m) return;
        const n = parseInt(m[2], 10);
        if(n > max){ max = n; prefix = m[1]; width = m[2].length; }
      });
      if(max < 0){
        const d = new Date();
        return (fallbackPrefix||'') + d.getFullYear() + String(d.getMonth()+1).padStart(2,'0') + String(d.getDate()).padStart(2,'0') + '001';
      }
      return prefix + String(max + 1).padStart(width, '0');
    }
    function qcEmpty(v){ return Array.isArray(v) ? !v.length : !String(v==null ? '' : v).trim() || v==='—'; }
    function qcCheckRequired(fields){
      for(const f of (fields||[])){
        if(!f || f.type==='readonly' || f.type==='switch') continue;
        if(!isFormFieldRequired(f)) continue;
        if(qcEmpty(formModel[f.name])){
          ElMessage.warning((['select','picker','date','daterange','datetime','upload','radio','number-unit'].includes(f.type) ? '请选择' : '请填写') + f.name);
          return false;
        }
      }
      return true;
    }
    function qcFormVals(fields){
      const o = {};
      (fields||[]).forEach(f=>{
        if(!f || !f.name) return;
        if(f.type==='switch'){
          const on = formSwitch[f.name]!==false;
          o[f.name] = f.name==='启用状态' ? (on ? '启用' : '禁用') : (on ? '是' : '否');
          return;
        }
        const v = formModel[f.name];
        if(v===undefined || v===null) return;
        o[f.name] = Array.isArray(v) ? (f.type==='daterange' ? v.join(' ~ ') : joinDun(v)) : (String(v).trim() || '—');
      });
      return o;
    }
    function qcMoveRow(pid, from, to, row, patch){
      const src = flowBag(pid, from);
      const i = src.indexOf(row);
      if(i >= 0) src.splice(i, 1);
      const next = Object.assign(flowPick(flowCols(pid, to), [patch, row]), { id: row.id + '-' + Date.now().toString(36) });
      flowBag(pid, to).unshift(next);
      return next;
    }
    function qcCurTab(){ return (tabView.value||{}).name || activeTab.value; }
    /** 待复核报检单 = 已完成且未复核的报检单 */
    function qcSyncRecheck(){
      FLOW_TABS.forEach(({ name })=>{
        const bag = flowBag('recheck', name);
        const cols = flowCols('recheck', name);
        const have = new Set(bag.map(r=> r['报检单号']));
        flowBag(FLOW_ORDER, name).forEach(o=>{
          if(o['单据状态']!=='已完成' || flowHas(o['复核结论']) || have.has(o['报检单号'])) return;
          const r = { id: 'rc-'+o['报检单号'], 单据状态: '待复核', 复核结论: '—' };
          cols.forEach(k=>{ r[k] = flowHas(o[k]) ? o[k] : '—'; });
          bag.unshift(r);
        });
        for(let i = bag.length - 1; i >= 0; i--){
          const f = flowOrderOf(bag[i]['报检单号']);
          if(f && (flowHas(f.row['复核结论']) || f.row['单据状态']==='已关闭')) bag.splice(i, 1);
        }
      });
    }
    watch(()=> pageId.value, v=>{ if(v==='recheck'){ flowSyncAll(); qcSyncRecheck(); storeTick.value += 1; } });
    function qcOrderSamples(no, tab){
      const lg = flowBag(FLOW_LEDGER, tab).filter(r=> r['报检单号']===no);
      return lg.map(r=>{
        const s = flowSplitRow(r['样品编号']) || {};
        const pick = k=> flowHas(s[k]) ? s[k] : (flowHas(r[k]) ? r[k] : '—');
        return { 样品状态: r['样品状态'], 检验结论: r['检验结论'] || '—', 偏差结论: r['偏差结论'] || '—', 样品编号: r['样品编号'],
          样品来源: pick('样品来源'), 检验方案: pick('检验方案'), 方案项目: pick('方案项目'), 临时项目: pick('临时项目'),
          取样备注: pick('取样备注'), 取样时间: pick('取样时间'), 取样人: pick('取样人') };
      });
    }
    function qcOpenRecheck(rows){
      const tab = qcCurTab();
      openForm('recheck');
      const samples = rows.flatMap(r=> qcOrderSamples(r['报检单号'], tab));
      if(samples.length) recheckSampleRows.value = samples;
      formModel['复核结论'] = samples.some(s=> s['检验结论']==='不合格') ? '不合格' : (samples.some(s=> flowHas(s['偏差结论'])) ? '异常' : '合格');
      formModel['复核说明'] = '';
      formModel._recheckIds = rows.map(r=> r.id);
      formModel._editId = rows[0] && rows[0].id;
    }
    function qcCreateDispose(pid, r, o, rv, tab){
      const lg = flowBag(FLOW_LEDGER, tab).filter(x=> x['报检单号']===r['报检单号']);
      const bad = lg.filter(x=> x['检验结论']==='不合格').length;
      const desc = [...new Set(lg.map(x=> x['异常描述']).filter(flowHas))].join('；');
      const pre = (pid.startsWith('unqual') ? 'UQ-' : 'DV-') + pid.split('-')[1].toUpperCase() + '-';
      const row = flowPick(flowCols(pid, 'tab-wait'), [r, o], {
        处置单号: qcNextNo(qcAllRows(pid), '处置单号', pre), 检验结论: '不合格', 偏差结论: '偏差', MRB状态: '未评审',
        异常描述: desc || rv.复核说明, 取样件数: (o||r)['已取样件数'] || '—',
        合格样品件数: String(lg.length - bad), 不合格样品件数: String(bad),
        复核说明: rv.复核说明, 复核时间: rv.复核时间, 复核人: rv.复核人
      });
      row.id = pid + '-w-' + Date.now().toString(36);
      flowBag(pid, 'tab-wait').unshift(row);
      return row['处置单号'];
    }
    function qcSaveRecheck(){
      const res = formModel['复核结论'];
      if(!res){ ElMessage.warning('请选择复核结论'); return; }
      const tab = qcCurTab();
      const ids = formModel._recheckIds || [formModel._editId];
      const bag = flowBag('recheck', tab);
      const rows = bag.filter(r=> ids.includes(r.id));
      if(!rows.length){ ElMessage.warning('未找到待复核报检单'); return; }
      const rv = { 复核结论: res, 复核时间: nowStamp(), 复核人: '管理员', 复核说明: String(formModel['复核说明']||'').trim() || '—' };
      const made = [];
      rows.forEach(r=>{
        qcSetKnown(r, rv);
        const f = flowOrderOf(r['报检单号']);
        if(f) qcSetKnown(f.row, rv);
        const pid = res==='不合格' ? QC_UQ[tab] : (res==='异常' ? QC_DV[tab] : '');
        if(pid) made.push(QC_SRC_TYPE[pid] + ' ' + qcCreateDispose(pid, r, f && f.row, rv, tab));
        bag.splice(bag.indexOf(r), 1);
      });
      selectedIds.value = [];
      formVisible.value = false;
      bumpStore();
      ElMessage.success('已复核 ' + rows.length + ' 张报检单，复核结论「' + res + '」已回写报检单' + (made.length ? '；已生成处置单：' + made.join('、') : ''));
    }
    function qcSaveDispose(){
      const pid = pageId.value;
      const fields = activeFormFields.value || [];
      if(!qcCheckRequired(fields)) return;
      const src = flowBag(pid, 'tab-wait').find(r=> r.id===formModel._editId);
      if(!src){ ElMessage.warning('未找到待处理的处置单'); return; }
      if(src['MRB状态']==='评审中'){ ElMessage.warning('处置单 '+src['处置单号']+' 正在 MRB 评审中，请在 MRB 评审完成后处置'); return; }
      const vals = qcFormVals(fields);
      qcMoveRow(pid, 'tab-wait', 'tab-done', src, Object.assign({}, vals, { 处置时间: nowStamp(), 处置人: '管理员' }));
      formVisible.value = false;
      bumpStore();
      ElMessage.success('处置单 ' + src['处置单号'] + ' 已处置，已转入「已处理」');
    }
    function qcCreateMrb(src, srcType, vals){
      const row = flowPick(flowCols('mrb-review', 'tab-doing'), [vals, src], {
        MRB单号: vals['MRB单号'] && vals['MRB单号']!=='—' ? vals['MRB单号'] : qcNextNo(qcAllRows('mrb-review'), 'MRB单号', 'MRB-'),
        来源处置类型: srcType, 来源处置单号: src['处置单号'], 创建备注: vals['备注'] && vals['备注']!=='—' ? vals['备注'] : '',
        创建时间: nowStamp(), 创建人: '管理员'
      });
      row.id = 'mrb-' + Date.now().toString(36);
      flowBag('mrb-review', 'tab-doing').unshift(row);
      qcSetKnown(src, { MRB状态: '评审中' });
      return row;
    }
    function qcSaveMrbAudit(){
      const pid = pageId.value;
      const fields = activeFormFields.value || [];
      if(!qcCheckRequired(fields)) return;
      const src = flowBag(pid, 'tab-wait').find(r=> r.id===formModel._editId);
      if(!src){ ElMessage.warning('未找到待处理的处置单'); return; }
      if(src['MRB状态']!=='未评审'){ ElMessage.warning('处置单 '+src['处置单号']+' 已发起 MRB 评审，不可重复发起'); return; }
      const row = qcCreateMrb(src, QC_SRC_TYPE[pid], qcFormVals(fields));
      formVisible.value = false;
      bumpStore();
      ElMessage.success('已生成 MRB 评审单 ' + row['MRB单号'] + '，处置单 ' + src['处置单号'] + ' 进入评审中');
    }
    function qcMrbSrcPid(type){ return Object.keys(QC_SRC_TYPE).find(k=> QC_SRC_TYPE[k]===type && k.startsWith('unqual')); }
    function qcSaveMrbAdd(){
      const fields = activeFormFields.value || [];
      if(!qcCheckRequired(fields)) return;
      const type = formModel['来源处置类型'];
      const spid = qcMrbSrcPid(type);
      const src = spid && flowBag(spid, 'tab-wait').find(r=> r['处置单号']===formModel['来源处置单号']);
      if(!src){ ElMessage.warning('来源处置单号须为「'+type+'」待处理的处置单'); return; }
      if(src['MRB状态']!=='未评审'){ ElMessage.warning('处置单 '+src['处置单号']+' 已发起 MRB 评审，不可重复发起'); return; }
      const row = qcCreateMrb(src, type, qcFormVals(fields));
      formVisible.value = false;
      bumpStore();
      ElMessage.success('MRB 评审单 ' + row['MRB单号'] + ' 已新增，处置单 ' + src['处置单号'] + ' 进入评审中');
    }
    function qcWriteback(){
      try { return Object.assign({ 采购来料不合格:true, 生产过程不合格:true, 生产物料不合格:true, 研发不合格处置:true }, JSON.parse(localStorage.getItem(MRB_WB_KEY) || '{}')); }
      catch(e){ return { 采购来料不合格:true, 生产过程不合格:true, 生产物料不合格:true, 研发不合格处置:true }; }
    }
    function openMrbWriteback(){
      Object.assign(mrbWriteback, qcWriteback());
      mrbWritebackVisible.value = true;
    }
    function saveMrbWriteback(){
      try { localStorage.setItem(MRB_WB_KEY, JSON.stringify(Object.assign({}, mrbWriteback))); } catch(e){ /* ignore */ }
      mrbWritebackVisible.value = false;
      const on = Object.keys(mrbWriteback).filter(k=> mrbWriteback[k]);
      ElMessage.success(on.length ? 'MRB 评审完成后将自动回写：' + on.join('、') : '已关闭回写，MRB 评审完成后需在处置单手动处置');
    }
    const MRB_SRC_PAGES = [
      { type:'采购来料不合格', page:'unqual-pi' },
      { type:'生产过程不合格', page:'unqual-pp' },
      { type:'生产物料不合格', page:'unqual-pm' },
      { type:'研发不合格处置', page:'unqual-rd' }
    ];
    const mrbLinkVisible = ref(false);
    const mrbLinkPick = ref([]);
    const mrbLinkNos = computed(()=> [...new Set(mrbLinkPick.value.map(p=> p.no))]);
    const mrbLinkRows = computed(()=>{
      void storeTick.value;
      const pick = mrbLinkPick.value;
      return MRB_SRC_PAGES.map(s=>{
        const nos = [...new Set(pick.filter(p=> p.type===s.type).map(p=> p.no))];
        const bag = MOCK[s.page] || {};
        const n = ['tab-wait','tab-done'].reduce((m, t)=> m + ((bag[t]||[]).filter(r=> nos.includes(r['处置单号'])).length), 0);
        return { 关联单据: s.type, page: s.page, nos, 关联记录数: n };
      }).filter(r=> r.nos.length);
    });
    function openMrbLink(){
      const rows = (tableData.value||[]).filter(r=> selectedIds.value.includes(r.id));
      if(!rows.length){ ElMessage.warning('请先勾选数据'); return; }
      const pick = rows.map(r=> ({ type: r['来源处置类型'], no: r['来源处置单号'] })).filter(p=> p.no && p.no!=='—');
      if(!pick.length){ ElMessage.warning('所选数据没有来源处置单'); return; }
      mrbLinkPick.value = pick;
      mrbLinkVisible.value = true;
    }
    function goMrbLink(row){
      mrbLinkVisible.value = false;
      const nos = (row.nos||[]).slice();
      onSelectMenu(row.page);
      setTimeout(()=>{
        const bag = MOCK[row.page] || {};
        if(!(bag['tab-wait']||[]).some(r=> nos.includes(r['处置单号']))) activeTab.value = 'tab-done';
        resetQueryModel();
        query['处置单号'] = nos.join('、');
        pageNum.value = 1;
        ElMessage.success('已按处置单号 '+nos.join('、')+' 跳转至「'+row['关联单据']+'」');
      }, 80);
    }
    const DISPOSE_LINK_PAGES = ['unqual-pi','unqual-pp','unqual-pm','unqual-rd','dev-pi','dev-pp','dev-pm','dev-rd'];
    const disposeLinkVisible = ref(false);
    const disposeLinkNos = ref([]);
    function disposeLinkCount(page, tabs, field, nos){
      const bag = MOCK[page] || {};
      return (tabs||[]).reduce((n, t)=> n + ((bag[t]||[]).filter(r=> nos.includes(r[field])).length), 0);
    }
    const disposeLinkRows = computed(()=>{
      void storeTick.value;
      const nos = disposeLinkNos.value || [];
      if(!nos.length) return [];
      return [
        { 关联单据:'MRB评审', page:'mrb-review', field:'来源处置单号', tabs:['tab-doing','tab-done'], nos, 关联记录数: disposeLinkCount('mrb-review', ['tab-doing','tab-done'], '来源处置单号', nos) },
        { 关联单据:'整改处理', page:'capa-handle', field:'来源单号', tabs:['tab-wait','tab-done'], nos, 关联记录数: disposeLinkCount('capa-handle', ['tab-wait','tab-done'], '来源单号', nos) }
      ];
    });
    function openDisposeLink(){
      const rows = (tableData.value||[]).filter(r=> selectedIds.value.includes(r.id));
      if(!rows.length){ ElMessage.warning('请先勾选数据'); return; }
      const nos = [...new Set(rows.map(r=> r['处置单号']).filter(n=> n && n!=='—'))];
      if(!nos.length){ ElMessage.warning('所选数据没有处置单号'); return; }
      disposeLinkNos.value = nos;
      disposeLinkVisible.value = true;
    }
    function goDisposeLink(row){
      disposeLinkVisible.value = false;
      const nos = (row.nos||[]).slice();
      onSelectMenu(row.page);
      setTimeout(()=>{
        if(row.tabs){
          const bag = MOCK[row.page] || {};
          const hit = row.tabs.find(t=> (bag[t]||[]).some(r=> nos.includes(r[row.field])));
          if(hit) activeTab.value = hit;
        }
        resetQueryModel();
        query[row.field] = nos.join('、');
        pageNum.value = 1;
        ElMessage.success('已按'+row.field+' '+nos.join('、')+' 跳转至「'+row['关联单据']+'」');
      }, 80);
    }
    function mrbBatchAudit(){
      const rows = (tableData.value||[]).filter(r=> selectedIds.value.includes(r.id));
      if(!rows.length){ ElMessage.warning('请先勾选要发起审核的数据'); return; }
      ElementPlus.ElMessageBox.confirm('确认对所选 '+rows.length+' 条 MRB 评审单发起审核？', '批量发起审核', { type:'warning' }).then(()=>{
        ElMessage.success('已对 '+rows.length+' 条 MRB 评审单发起审核');
      }).catch(()=>{});
    }
    function mrbLaunchAudit(row){
      if(!row){ ElMessage.warning('未找到要发起审批的数据'); return; }
      const no = row['MRB单号'] || '';
      ElementPlus.ElMessageBox.confirm('确认对 MRB 评审单「'+no+'」发起审批？', '发起审批', { type:'warning' }).then(()=>{
        ElMessage.success('已对 MRB 评审单「'+no+'」发起审批');
      }).catch(()=>{});
    }
    function capaConfirmLaunch(row){
      if(!row){ ElMessage.warning('未找到要确认发起的数据'); return; }
      if(row['整改状态']!==CAPA_LAUNCHABLE){ ElMessage.warning('仅待发起状态可确认发起'); return; }
      const no = row['整改单号'] || '';
      ElementPlus.ElMessageBox.confirm('确认对整改单「'+no+'」发起？', '确认发起', { type:'warning' }).then(()=>{
        const list = flowBag('capa-internal', 'main');
        const cur = list.find(r=> r.id===row.id) || row;
        qcSetKnown(cur, { 整改状态: '执行中' });
        let h = flowBag('capa-handle', 'tab-wait').find(x=> x['整改单号']===cur['整改单号']);
        if(!h){
          h = flowPick(flowCols('capa-handle', 'tab-wait'), [cur], { 超时状态: qcCapaOverdue(cur['计划整改完成日期']) });
          h.id = 'capa-w-' + Date.now().toString(36);
          flowBag('capa-handle', 'tab-wait').unshift(h);
        }
        bumpStore();
        ElMessage.success('整改单「'+no+'」已确认发起，状态为执行中，已生成整改处理待办');
      }).catch(()=>{});
    }
    const CAPA_LINK_SRC = {
      '采购来料不合格': { page:'unqual-pi', field:'处置单号', tabs:['tab-wait','tab-done'] },
      '生产过程不合格': { page:'unqual-pp', field:'处置单号', tabs:['tab-wait','tab-done'] },
      '生产物料不合格': { page:'unqual-pm', field:'处置单号', tabs:['tab-wait','tab-done'] },
      '研发不合格处置': { page:'unqual-rd', field:'处置单号', tabs:['tab-wait','tab-done'] },
      '采购来料偏差': { page:'dev-pi', field:'处置单号', tabs:['tab-wait','tab-done'] },
      '生产过程偏差': { page:'dev-pp', field:'处置单号', tabs:['tab-wait','tab-done'] },
      '生产物料偏差': { page:'dev-pm', field:'处置单号', tabs:['tab-wait','tab-done'] },
      '研发偏差': { page:'dev-rd', field:'处置单号', tabs:['tab-wait','tab-done'] },
      '客户投诉': { page:'np-0212-02', field:'客诉单号', tabs:['tab-1','tab-2'] }
    };
    const capaLinkVisible = ref(false);
    const capaLinkPick = ref([]);
    const capaLinkNos = computed(()=> [...new Set(capaLinkPick.value.map(p=> p.no))]);
    function capaCount(page, tabs, field, nos){
      const bags = tabs ? tabs.map(t=> ((MOCK[page]||{})[t])||[]) : [((MOCK[page]||{}).main)||[]];
      return bags.reduce((n, list)=> n + list.filter(r=> nos.includes(r[field])).length, 0);
    }
    const capaLinkRows = computed(()=>{
      void storeTick.value;
      const pick = capaLinkPick.value;
      const rows = [];
      const nos = [...new Set(pick.map(p=> p.no).filter(n=> n && n!=='—'))];
      if(nos.length) rows.push({ 关联单据:'内部整改', page:'capa-internal', field:'整改单号', tabs:null, nos, 关联记录数: capaCount('capa-internal', null, '整改单号', nos) });
      const types = [...new Set(pick.map(p=> p.type).filter(t=> CAPA_LINK_SRC[t]))];
      types.forEach(t=>{
        const src = CAPA_LINK_SRC[t];
        const srcNos = [...new Set(pick.filter(p=> p.type===t).map(p=> p.src).filter(n=> n && n!=='—'))];
        if(!srcNos.length) return;
        rows.push({ 关联单据:t, page:src.page, field:src.field, tabs:src.tabs, nos:srcNos, 关联记录数: capaCount(src.page, src.tabs, src.field, srcNos) });
      });
      return rows;
    });
    function openCapaLink(){
      const rows = (tableData.value||[]).filter(r=> selectedIds.value.includes(r.id));
      if(!rows.length){ ElMessage.warning('请先勾选数据'); return; }
      capaLinkPick.value = rows.map(r=> ({ no:r['整改单号'], type:r['事件类型'], src:r['来源单号'] }));
      capaLinkVisible.value = true;
    }
    function goCapaLink(row){
      capaLinkVisible.value = false;
      const nos = (row.nos||[]).slice();
      onSelectMenu(row.page);
      setTimeout(()=>{
        if(row.tabs){
          const bag = MOCK[row.page] || {};
          const hit = row.tabs.find(t=> (bag[t]||[]).some(r=> nos.includes(r[row.field])));
          if(hit) activeTab.value = hit;
        }
        resetQueryModel();
        query[row.field] = nos.join('、');
        pageNum.value = 1;
        ElMessage.success('已按'+row.field+' '+nos.join('、')+' 跳转至「'+row['关联单据']+'」');
      }, 80);
    }
    const hcExecVisible = ref(false);
    const hcExec = reactive({ order:{}, dir:'入库', noKey:'入库单号', qtyKey:'入库数量', locKey:'入库库位编码', lines:[], selected:[], procs:[], locOpts:[] });
    const hcExecFile = ref(null);
    const hcPickVisible = ref(false);
    const hcPickQ = reactive({ code:'', name:'' });
    const hcPickKw = reactive({ code:'', name:'' });
    const hcPickSelected = ref([]);
    const hcJobVisible = ref(false);
    const hcJob = reactive({ name:'', fields:[], model:{}, targets:[] });
    const hcExecSum = computed(()=> (hcExec.lines||[]).reduce((s,r)=> s + (parseFloat(r[hcExec.qtyKey])||0), 0));
    const hcPickRows = computed(()=>{
      void storeTick.value;
      const code = String(hcPickKw.code||'').trim();
      const name = String(hcPickKw.name||'').trim();
      return (((MOCK.consumable||{}).main)||[]).filter(r=> r['启用状态']!=='禁用')
        .filter(r=> !code || String(r['耗材编码']||'').includes(code))
        .filter(r=> !name || String(r['耗材名称']||'').includes(name));
    });
    function hcCountStock(code, locCode){
      if(!code || !locCode) return 0;
      let n = 0;
      (((MOCK['np-0405-01']||{})['tab-2'])||[]).forEach(r=>{
        if(r['流水状态']==='已完成' && r['耗材编码']===code && r['入库库位编码']===locCode) n += parseFloat(r['入库数量'])||0;
      });
      (((MOCK['np-0405-02']||{})['tab-2'])||[]).forEach(r=>{
        if(r['流水状态']==='已完成' && r['耗材编码']===code && r['出库库位编码']===locCode) n -= parseFloat(r['出库数量'])||0;
      });
      return Math.round(n*1000)/1000;
    }
    function hcExecStock(row){
      const loc = row[hcExec.locKey];
      if(!row['耗材编码'] || !loc) return '0';
      return String(hcCountStock(row['耗材编码'], loc));
    }
    function hcWhCode(locCode){
      const loc = (((MOCK.warehouse||{}).tab2)||[]).find(r=> r['库位编码']===locCode);
      if(!loc) return '';
      const name = String(loc['所属仓库']||'').split(/[、,，]/)[0].trim();
      const wh = (((MOCK.warehouse||{}).tab1)||[]).find(r=> r['仓库名称']===name);
      return wh ? (wh['仓库编码']||'') : '';
    }
    function hcExecLoadProcs(order){
      const doc = '耗材'+hcExec.dir;
      const type = order['单据类型'];
      const forms = (((MOCK['lab-io-form']||{}).main)||[]);
      const hit = forms.find(f=> f['启用状态']==='启用' && f['适用业务单据']===doc && splitDun(f['适用单据类型']).includes(type));
      return ((hit && hit._procs) || []).map(p=> typeof p==='string' ? { name:p, fields:[] } : { name: p.name || p['工序名称'] || '', fields: p.fields || p['字段'] || [] }).filter(p=> p.name);
    }
    function hcExecLoadLines(order){
      const procs = hcExec.procs;
      const first = procs[0] ? procs[0].name : '/';
      if(Array.isArray(order._execLines)){
        return JSON.parse(JSON.stringify(order._execLines)).map(line=>{
          line['当前工序'] = line['当前工序'] || first;
          line._green = procs.length>0 && line['当前工序']==='/';
          line._jobs = line._jobs || {};
          return line;
        });
      }
      const no = order[hcExec.noKey];
      const flows = (((MOCK[pageId.value]||{})['tab-2'])||[]).filter(r=> r[hcExec.noKey]===no && r['流水状态']!=='已关闭');
      return flows.map(r=> ({
        id: r.id,
        耗材编码: r['耗材编码']||'',
        耗材名称: r['耗材名称']||'',
        耗材规格: r['耗材规格']||'',
        耗材种类: r['耗材种类']||'',
        计量单位: r['计量单位']||'',
        条码号: r['条码号']||'',
        批号: r['批号']||'',
        [hcExec.qtyKey]: r[hcExec.qtyKey]||'',
        [hcExec.locKey]: r[hcExec.locKey]||'',
        当前工序: first,
        _jobs: {},
        _green: false
      }));
    }
    function openHcExec(row){
      const dir = pageId.value==='np-0405-02' ? '出库' : '入库';
      const list = ((MOCK[pageId.value]||{})['tab-1'])||[];
      const order = list.find(r=> r.id===row.id) || row;
      hcExec.dir = dir;
      hcExec.noKey = dir+'单号';
      hcExec.qtyKey = dir+'数量';
      hcExec.locKey = dir+'库位编码';
      hcExec.order = order;
      hcExec.procs = hcExecLoadProcs(order);
      hcExec.locOpts = (((MOCK.warehouse||{}).tab2)||[]).filter(r=> r['启用状态']!=='禁用').map(r=> ({ value:r['库位编码'], label: r['库位编码']+' '+(r['库位名称']||'') }));
      hcExec.lines = hcExecLoadLines(order);
      hcExec.selected = [];
      hcExecVisible.value = true;
    }
    function hcExecSel(rows){ hcExec.selected = rows || []; }
    function hcExecRowClass({ row }){ return row && row._green ? 'hc-exec-done' : ''; }
    function hcExecAdd(){
      hcPickQ.code = ''; hcPickQ.name = ''; hcPickKw.code = ''; hcPickKw.name = '';
      hcPickSelected.value = [];
      hcPickVisible.value = true;
    }
    function hcPickQuery(){ hcPickKw.code = hcPickQ.code; hcPickKw.name = hcPickQ.name; }
    function hcPickReset(){ hcPickQ.code = ''; hcPickQ.name = ''; hcPickKw.code = ''; hcPickKw.name = ''; }
    function hcPickConfirm(){
      const rows = hcPickSelected.value || [];
      if(!rows.length){ ElMessage.warning('请选择耗材'); return; }
      const first = hcExec.procs[0] ? hcExec.procs[0].name : '/';
      rows.forEach((r,i)=>{
        hcExec.lines.push({
          id: 'hcl-'+Date.now()+'-'+i+'-'+Math.random().toString(36).slice(2,6),
          耗材编码: r['耗材编码']||'',
          耗材名称: r['耗材名称']||'',
          耗材规格: r['耗材规格']||'',
          耗材种类: r['耗材种类']||'',
          计量单位: r['计量单位']||'',
          [hcExec.qtyKey]: '',
          [hcExec.locKey]: '',
          当前工序: first,
          _jobs: {},
          _green: false
        });
      });
      hcPickVisible.value = false;
      ElMessage.success('已添加 '+rows.length+' 行耗材');
    }
    function hcExecDel(){
      if(!hcExec.selected.length){ ElMessage.warning('请先勾选要删除的耗材'); return; }
      const ids = new Set(hcExec.selected.map(r=> r.id));
      hcExec.lines = hcExec.lines.filter(r=> !ids.has(r.id));
      hcExec.selected = [];
      ElMessage.success('已删除所选耗材');
    }
    function hcExecImport(){ if(hcExecFile.value) hcExecFile.value.click(); }
    function hcExecOnFile(e){
      const f = e.target.files && e.target.files[0];
      if(e.target) e.target.value = '';
      if(!f) return;
      ElMessage.info('已选择文件「'+f.name+'」，演示环境不解析导入明细');
    }
    function hcExecBindOrder(){
      const list = ((MOCK[pageId.value]||{})['tab-1'])||[];
      const id = hcExec.order && hcExec.order.id;
      const live = list.find(r=> r.id===id);
      if(live) hcExec.order = live;
      return hcExec.order;
    }
    function hcExecSyncFlows(status){
      const order = hcExecBindOrder();
      const no = order[hcExec.noKey];
      const bag = (MOCK[pageId.value] = MOCK[pageId.value] || {});
      const prev = bag['tab-2'] = bag['tab-2'] || [];
      const keep = new Set(hcExec.lines.map(l=> l.id));
      const flows = prev.filter(r=> !(r[hcExec.noKey]===no && r['流水状态']==='执行中' && !keep.has(r._lineId) && !keep.has(r.id)));
      bag['tab-2'] = flows;
      const stamp = nowStamp();
      const extra = {};
      hcExec.lines.forEach(line=>{
        const locCode = line[hcExec.locKey] || '';
        const qty = parseFloat(line[hcExec.qtyKey])||0;
        const key = (line['耗材编码']||'')+'|'+locCode;
        const stock = hcCountStock(line['耗材编码'], locCode) + (extra[key]||0);
        const delta = hcExec.dir==='入库' ? qty : -qty;
        extra[key] = (extra[key]||0) + delta;
        const cum = stock + delta;
        const fid = 'hcex-'+order.id+'-'+line.id;
        let flow = flows.find(r=> r._lineId===line.id || r.id===line.id || r.id===fid);
        const patch = {
          流水状态: status,
          检查结果: (flow && flow['检查结果'] && flow['检查结果']!=='/') ? flow['检查结果'] : '/',
          条码号: line['条码号'] || (flow && flow['条码号']) || '—',
          耗材编码: line['耗材编码']||'',
          耗材名称: line['耗材名称']||'',
          耗材规格: line['耗材规格']||'—',
          耗材种类: line['耗材种类']||'—',
          批号: line['批号'] || (flow && flow['批号']) || '—',
          [hcExec.qtyKey]: String(line[hcExec.qtyKey]||''),
          累计库存: String(Math.round(cum*1000)/1000),
          计量单位: line['计量单位']||'—',
          [hcExec.dir+'仓库编码']: hcWhCode(locCode),
          [hcExec.locKey]: locCode,
          备注: order['备注'] || '—',
          [hcExec.noKey]: no,
          单据类型: order['单据类型']||'',
          操作时间: stamp,
          操作人: '管理员',
          _lineId: line.id,
          _job: JSON.parse(JSON.stringify(line._jobs||{}))
        };
        if(flow) Object.assign(flow, patch);
        else flows.unshift(Object.assign({ id: fid }, patch));
      });
      const done = flows.filter(r=> r[hcExec.noKey]===no && r['流水状态']==='已完成').reduce((s,r)=> s+(parseFloat(r[hcExec.qtyKey])||0), 0);
      order['已完成数量'] = String(Math.round(done*1000)/1000);
      order._execLines = JSON.parse(JSON.stringify(hcExec.lines));
    }
    function hcExecSave(){
      if(!hcExec.lines.length){ ElMessage.warning('请先添加耗材'); return; }
      hcExecBindOrder();
      hcExec.order['单据状态'] = '执行中';
      hcExecSyncFlows('执行中');
      bumpStore();
      ElMessage.success('已保存，单据状态为执行中');
    }
    function hcExecSubmit(){
      hcExecBindOrder();
      if(!hcExec.lines.length){ ElMessage.warning('请先添加耗材'); return; }
      for(const line of hcExec.lines){
        if(!(parseFloat(line[hcExec.qtyKey])>0)){ ElMessage.warning('请填写'+hcExec.qtyKey); return; }
        if(!line[hcExec.locKey]){ ElMessage.warning('请选择'+hcExec.dir+'库位'); return; }
      }
      if(hcExec.procs.length && hcExec.lines.some(l=> l['当前工序']!=='/')){
        ElMessage.warning('工序未全部完成，不可提交'); return;
      }
      hcExec.order['单据状态'] = '已完成';
      hcExecSyncFlows('已完成');
      bumpStore();
      hcExecVisible.value = false;
      ElMessage.success('已提交，单据状态为已完成');
    }
    function openHcJob(name, fields, targets){
      const saved = (targets[0] && targets[0]._jobs && targets[0]._jobs[name]) || {};
      hcJob.name = name;
      hcJob.fields = (fields && fields.length) ? fields.slice() : ['作业说明'];
      hcJob.model = {};
      hcJob.fields.forEach(f=> { hcJob.model[f] = saved[f] || ''; });
      hcJob.targets = targets;
      hcJobVisible.value = true;
    }
    function hcExecLineAct(line){
      if(!hcExec.procs.length){ ElMessage.warning('当前无工序'); return; }
      const name = line['当前工序'];
      if(!name || name==='/'){ ElMessage.warning('该行工序已完成'); return; }
      const proc = hcExec.procs.find(p=> p.name===name);
      openHcJob(name, proc && proc.fields, [line]);
    }
    function hcExecProcAct(proc){
      const name = proc.name;
      const targets = hcExec.lines.filter(l=> l['当前工序']===name);
      if(!targets.length){ ElMessage.warning('数据列表内没有当前工序为「'+name+'」的数据，不可批量作业'); return; }
      openHcJob(name, proc.fields, targets);
    }
    function confirmHcJob(){
      const name = hcJob.name;
      const names = hcExec.procs.map(p=> p.name);
      const idx = names.indexOf(name);
      const next = idx>=0 && idx<names.length-1 ? names[idx+1] : '/';
      (hcJob.targets||[]).forEach(line=>{
        line._jobs = line._jobs || {};
        line._jobs[name] = Object.assign({}, hcJob.model);
        if(line['当前工序']===name){
          line['当前工序'] = next;
          line._green = next==='/' && hcExec.procs.length>0;
        }
      });
      hcJobVisible.value = false;
      ElMessage.success('已保存工序「'+name+'」');
    }
    function qcSaveMrbRec(){
      const fields = activeFormFields.value || [];
      if(!qcCheckRequired(fields)) return;
      const src = flowBag('mrb-review', 'tab-doing').find(r=> r.id===formModel._editId);
      if(!src){ ElMessage.warning('未找到评审中的 MRB 单'); return; }
      const vals = qcFormVals(fields);
      const stamp = nowStamp();
      qcMoveRow('mrb-review', 'tab-doing', 'tab-done', src, Object.assign({}, vals, { 处置时间: stamp, 处置人: '管理员' }));
      const type = src['来源处置类型'];
      const spid = qcMrbSrcPid(type);
      const u = spid && flowBag(spid, 'tab-wait').find(x=> x['处置单号']===src['来源处置单号']);
      let tip = '';
      if(u){
        if(qcWriteback()[type]!==false){
          qcMoveRow(spid, 'tab-wait', 'tab-done', u, {
            处置方式: vals['处置方式'], 问题大类: src['问题大类'], 问题小类: src['问题小类'], 问题描述: src['问题描述'],
            处置说明: vals['处置说明'], 处置报告: vals['处置报告'], 处置时间: stamp, 处置人: '管理员', MRB状态: '已评审'
          });
          tip = '，已回写' + type + '处置单 ' + u['处置单号'] + '（已处理）';
        } else {
          qcSetKnown(u, { MRB状态: '已评审' });
          tip = '，' + type + '处置单 ' + u['处置单号'] + ' 待手动处置';
        }
      }
      formVisible.value = false;
      bumpStore();
      ElMessage.success('MRB 单 ' + src['MRB单号'] + ' 评审完成' + tip);
    }
    function qcCapaOverdue(d){ return d && d!=='—' && String(d).slice(0, 10) < nowStamp().slice(0, 10) ? '超期' : '正常'; }
    function qcSaveCapa(){
      const fields = activeFormFields.value || [];
      if(!qcCheckRequired(fields)) return;
      if(formModel['事件类型']!=='其他' && qcEmpty(formModel['来源单号'])){ ElMessage.warning('请选择来源单号'); return; }
      const list = flowBag('capa-internal', 'main');
      const isAdd = formMode.value!=='edit';
      const cur = isAdd ? null : list.find(r=> r.id===formModel._editId);
      if(!isAdd && !cur){ ElMessage.warning('未找到待编辑整改单'); return; }
      const vals = qcFormVals(fields);
      ['物料编码','物料名称','物料规格','物料种类','客户编码','客户名称'].forEach(k=>{ if(!qcEmpty(formModel[k])) vals[k] = formModel[k]; });
      if(isAdd) vals['整改单号'] = qcNextNo(list, '整改单号', 'CA-');
      else delete vals['整改单号'];
      if(isAdd){
        const row = flowPick(flowCols('capa-internal', 'main'), [vals], { 整改状态: '待发起', 创建时间: nowStamp(), 创建人: '管理员' });
        row.id = 'capa-i-' + Date.now().toString(36);
        list.unshift(row);
      } else {
        if(cur['整改状态']!==CAPA_LAUNCHABLE){ ElMessage.warning('仅待发起状态可编辑'); return; }
        qcSetKnown(cur, vals);
        const h = flowBag('capa-handle', 'tab-wait').find(x=> x['整改单号']===cur['整改单号']);
        if(h) qcSetKnown(h, Object.assign({}, vals, { 超时状态: qcCapaOverdue(vals['计划整改完成日期']) }));
      }
      formVisible.value = false;
      bumpStore();
      ElMessage.success(isAdd ? '整改单已新增，状态为待发起' : '整改单已保存');
    }
    function qcSaveCapaProcess(){
      const fields = activeFormFields.value || [];
      if(!qcCheckRequired(fields)) return;
      const src = flowBag('capa-handle', 'tab-wait').find(r=> r.id===formModel._editId);
      if(!src){ ElMessage.warning('未找到待处理的整改单'); return; }
      const vals = qcFormVals(fields);
      const rec = { 原因分析: vals['原因分析'], 整改措施: vals['整改措施'], 整改说明: vals['整改说明'] || '—', 整改报告: vals['附件'] || '—', 整改人: '管理员', 整改完成时间: nowStamp() };
      qcMoveRow('capa-handle', 'tab-wait', 'tab-done', src, rec);
      const ci = flowBag('capa-internal', 'main').find(x=> x['整改单号']===src['整改单号']);
      if(ci && ci['整改状态']==='执行中') qcSetKnown(ci, Object.assign({}, rec, { 整改状态: '已完成' }));
      formVisible.value = false;
      bumpStore();
      ElMessage.success('整改单 ' + src['整改单号'] + ' 已处理' + (ci ? '，内部整改状态更新为已完成' : ''));
    }
    function qcSaveAddSample(){
      const fields = activeFormFields.value || [];
      if(!qcCheckRequired(fields)) return;
      const raw = String(formModel['本次加样件数']||'').trim();
      if(!/^\d+$/.test(raw) || parseInt(raw, 10) <= 0){ ElMessage.warning('本次加样件数须为正整数'); return; }
      const f = flowOrderOf(formModel['报检单号']);
      if(!f || !['待执行','执行中'].includes(f.row['单据状态'])){ ElMessage.warning('报检单须为待执行 / 执行中'); return; }
      const before = flowInt(f.row['应取样件数']);
      const after = before + parseInt(raw, 10);
      f.row['应取样件数'] = String(after);
      f.row._flow = true;
      f.row._sampEnd = false;
      formModel['原应取样件数'] = String(before);
      formModel['现应取样件数'] = String(after);
      flowSyncAll();
      genericSaveForm(true);
      ElMessage.success('加样申请已保存，报检单 ' + f.row['报检单号'] + ' 应取样件数 ' + before + ' → ' + after + '，已进入待取样任务');
    }
    function qcSaveSpcReport(){
      const fields = activeFormFields.value || [];
      if(!qcCheckRequired(fields)) return;
      const list = flowBag('spc-report-ledger', 'main');
      const name = String(formModel['报告名称']||'').trim();
      if(list.some(r=> r['报告名称']===name)){ ElMessage.warning('报告名称「'+name+'」已存在'); return; }
      const v = qcFormVals(fields);
      const q = k=> qcEmpty(query[k]) ? '—' : (Array.isArray(query[k]) ? query[k].join(' ~ ') : query[k]);
      const row = flowPick(flowCols('spc-report-ledger', 'main'), [{
        报告名称: name, 开具方式: '手动开具', 方案编码: '—', 来源类型: String((tabView.value||{}).label||'').replace(/检$/, ''), 日期维度: q('日期维度'), 日期范围: v['日期范围'],
        物料信息: q('物料信息'), 采样点: q('采样点'), 供应商信息: q('供应商信息'), 客户信息: q('客户信息'), 检验方案: q('检验方案'), 检验项: q('检验项'),
        备注: v['备注'], 创建人: '管理员', 创建时间: nowStamp()
      }]);
      row.id = 'rl-' + Date.now().toString(36);
      list.unshift(row);
      formVisible.value = false;
      bumpStore();
      ElMessage.success('SPC 报告「' + name + '」已保存，可在 SPC报告台账查看');
    }
    /** 没有专属保存逻辑的新增 / 复制 / 编辑：按弹窗字段校验必填、编码唯一，写入当前页签数据 */
    function genericSaveForm(silent){
      const pid = pageId.value, tv = tabView.value || {}, tab = qcCurTab() || 'main';
      const fields = (activeFormFields.value||[]).filter(f=> f && f.name);
      if(!silent && !qcCheckRequired(fields)) return;
      const vals = qcFormVals(fields);
      const cols = (tv.columns||[]).map(c=> c.field).filter(k=> k && k!=='操作' && k!=='_actions');
      if(pid==='np-0201-01'){
        const mi = joinMatInfoSlash(formModel);
        if(mi) vals['物料信息'] = mi;
      }
      if(pid==='np-0201-02'){
        if(!(formLineRows.value||[]).length){ ElMessage.warning('请添加委托项目'); return; }
        vals['委托项目'] = formLineRows.value.map(r=> r['检验项名称']).filter(Boolean).join('、');
        const sample = oeAllSamples().find(r=> r['样品编号']===formModel['样品编号']);
        vals['检验方案'] = formModel._schemeName || (sample && sample['检验方案']) || '';
      }
      cols.forEach(k=>{
        if(k in vals) return;
        const v = formModel[k];
        if(!qcEmpty(v)) vals[k] = Array.isArray(v) ? joinDun(v) : v;
      });
      const bag = (MOCK[pid] = MOCK[pid] || {});
      const list = (bag[tab] = bag[tab] || []);
      const isAdd = formMode.value!=='edit';
      const cur = isAdd ? null : list.find(r=> r.id===formModel._editId);
      if(!isAdd && !cur){ ElMessage.warning('未找到待编辑数据'); return; }
      const fieldNames = new Set(fields.map(f=> f.name));
      for(const f of fields){
        if(!/(编码|单号|编号)$/.test(f.name) || ['readonly','picker','select'].includes(f.type) || !cols.includes(f.name)) continue;
        const v = String(vals[f.name]||'').trim();
        if(v && v!=='—' && list.some(r=> r!==cur && String(r[f.name]||'')===v)){ ElMessage.warning(f.name+'「'+v+'」已存在，不可重复'); return; }
      }
      const stamp = nowStamp();
      if(isAdd){
        fields.filter(f=> f.type==='readonly' && /(编码|单号|编号)$/.test(f.name) && qcEmpty(vals[f.name]) && cols.includes(f.name))
          .forEach(f=>{ vals[f.name] = qcNextNo(list, f.name, ''); });
        const own = cols.find(k=> /单号$/.test(k) && !fieldNames.has(k) && list.length && list.every(r=> flowHas(r[k])) && new Set(list.map(r=> r[k])).size===list.length);
        if(own && qcEmpty(vals[own])) vals[own] = qcNextNo(list, own, '');
        const row = { id: pid.replace(/[^a-z0-9]/gi, '').slice(0, 8) + '-' + Date.now().toString(36) };
        cols.forEach(k=>{ row[k] = '—'; });
        Object.assign(row, QC_ADD_DEFAULTS[pid] || {}, vals);
        if(cols.includes('启用状态') && qcEmpty(vals['启用状态'])) row['启用状态'] = '启用';
        ['创建时间','制单时间'].forEach(k=>{ if(cols.includes(k)) row[k] = stamp; });
        ['创建人','制单人'].forEach(k=>{ if(cols.includes(k)) row[k] = '管理员'; });
        if((page.value?.formLineFields||[]).length && (formLineRows.value||[]).length) row._lines = JSON.parse(JSON.stringify(formLineRows.value));
        list.unshift(row);
      } else {
        fields.filter(f=> f.type==='readonly').forEach(f=>{ if(qcEmpty(vals[f.name])) delete vals[f.name]; });
        qcSetKnown(cur, vals);
        if((page.value?.formLineFields||[]).length && (formLineRows.value||[]).length) cur._lines = JSON.parse(JSON.stringify(formLineRows.value));
        if(pid==='ledger') Object.assign(cur, ledgerEditItemTexts());
      }
      if(pid==='np-0201-02'){ oeUpsertFromEntrust(isAdd ? list[0] : cur); flowSyncAll(); }
      formVisible.value = false;
      bumpStore();
      if(!silent) ElMessage.success(isAdd ? (formMode.value==='copy' ? '复制新增成功' : '新增成功') : '保存成功');
    }
    const TREE_NODE_KEY = 'dingcai-qms-tree-nodes';
    const TREE_NODE_DESC_KEY = 'dingcai-qms-tree-node-descs';
    const TREE_NAME_KEYS = ['数据源名称','数据源','标签类型名称','资源','表单类型','物料类名称'];
    let qcTreeEditNode = '';
    function qcTreeSaved(){
      try{ return JSON.parse(localStorage.getItem(TREE_NODE_KEY) || '{}') || {}; }catch(e){ return {}; }
    }
    function qcTreeDescSaved(){
      try{ return JSON.parse(localStorage.getItem(TREE_NODE_DESC_KEY) || '{}') || {}; }catch(e){ return {}; }
    }
    function qcTreePersist(pid){
      const all = qcTreeSaved();
      all[pid] = (CFG.pages[pid] || {}).treeNodes || [];
      try{ localStorage.setItem(TREE_NODE_KEY, JSON.stringify(all)); }catch(e){}
      const descsAll = qcTreeDescSaved();
      descsAll[pid] = (CFG.pages[pid] || {}).treeNodeDescs || {};
      try{ localStorage.setItem(TREE_NODE_DESC_KEY, JSON.stringify(descsAll)); }catch(e){}
    }
    Object.entries(qcTreeSaved()).forEach(([pid, nodes])=>{
      if(CFG.pages[pid] && Array.isArray(nodes)) CFG.pages[pid].treeNodes = nodes.slice();
    });
    Object.entries(qcTreeDescSaved()).forEach(([pid, descs])=>{
      if(CFG.pages[pid] && descs && typeof descs==='object') CFG.pages[pid].treeNodeDescs = Object.assign({}, descs);
    });
    function qcSaveTreeNode(){
      const p = page.value, pid = pageId.value;
      const fields = activeFormFields.value || [];
      if(!qcCheckRequired(fields)) return;
      const key = [...TREE_NAME_KEYS, p?.treeField].find(k=> k && fields.some(f=> f.name===k));
      const name = String(formModel[key] || '').trim();
      if(!name){ ElMessage.warning('请填写' + (key || '名称')); return; }
      if(!p || !Array.isArray(p.treeNodes)){ formVisible.value = false; return; }
      const isEdit = /^编辑/.test(formMode.value);
      const old = isEdit ? qcTreeEditNode : '';
      if(p.treeNodes.includes(name) && name!==old){ ElMessage.warning('「' + name + '」已存在，不可重复'); return; }
      if(isEdit && old && old!==name){
        p.treeNodes = p.treeNodes.map(n=> n===old ? name : n);
        if(p.treeField){
          qcAllRows(pid).forEach(r=>{ if(r[p.treeField]===old) r[p.treeField] = name; });
          bumpStore();
        }
      } else if(!isEdit){
        p.treeNodes = p.treeNodes.concat([name]);
      }
      if(fields.some(f=> f && f.name==='说明')){
        const desc = String(formModel['说明'] || '').trim();
        const descs = Object.assign({}, p.treeNodeDescs || {});
        if(isEdit && old && old!==name) delete descs[old];
        if(desc) descs[name] = desc; else delete descs[name];
        p.treeNodeDescs = descs;
      }
      qcTreePersist(pid);
      treeListId.value = name;
      formVisible.value = false;
      storeTick.value += 1;
      ElMessage.success(isEdit ? '已保存「' + name + '」' : '已新增「' + name + '」');
    }
    function qcInitDsSetting(){
      const p = page.value, pid = pageId.value;
      if(!(p?.settingLineFields||[]).length) return;
      formLineRows.value = qcAllRows(pid).filter(r=> r[p.treeField]===treeListId.value).map(r=> ({
        _srcId: r.id, 数据类型: r['字段注释'] || '', 字段: r['字段名'] || '', 字段描述: r['字段描述'] || ''
      }));
    }
    const QC_API_SRC = [['样品', FLOW_LEDGER, 'tab-pi'], ['钢瓶', FLOW_ORDER, 'tab-pi'], ['物料', 'mat-list', '']];
    function qcParseApi(){
      if(!String(formModel['Api地址']||'').trim()){ ElMessage.warning('请先填写Api地址'); return; }
      const node = String(formModel['数据源'] || treeListId.value || '');
      const hit = QC_API_SRC.find(([kw])=> node.includes(kw)) || QC_API_SRC[0];
      const p = CFG.pages[hit[1]] || {};
      const tv = (p.tabViews||[]).find(t=> !hit[2] || t.name===hit[2]) || {};
      const fields = (tv.columns||p.columns||[]).map(c=> c.field).filter(k=> k && k!=='操作' && k!=='_actions' && !k.startsWith('_'));
      const have = new Set((formLineRows.value||[]).flatMap(l=> [String(l['字段']||'').trim(), String(l['字段描述']||'').trim()]).filter(Boolean));
      const add = fields.filter(k=> !have.has(k)).map(k=> ({ 数据类型: /时间|日期/.test(k) ? 'datetime' : (/(数|量)$/.test(k) ? 'number' : 'varchar'), 字段: k, 字段描述: k }));
      formLineRows.value = (formLineRows.value||[]).filter(l=> String(l['字段']||'').trim()).concat(add);
      ElMessage.success('已解析 ' + fields.length + ' 个字段' + (add.length ? '，新增 ' + add.length + ' 个' : '，无新增字段'));
    }
    function qcSaveDsSetting(){
      const p = page.value, pid = pageId.value, node = String(formModel['数据源'] || treeListId.value || '').trim();
      if(!node){ ElMessage.warning('请先选择左侧数据源'); return; }
      if((p?.settingLineFields||[]).length){
        const lines = (formLineRows.value || []).filter(l=> String(l['字段']||'').trim());
        const seen = new Set();
        for(const l of lines){
          const k = String(l['字段']).trim();
          if(seen.has(k)){ ElMessage.warning('字段「' + k + '」重复'); return; }
          seen.add(k);
        }
        const bag = (MOCK[pid] = MOCK[pid] || {});
        const list = (bag.main = bag.main || []);
        const olds = list.filter(r=> r[p.treeField]===node);
        const kept = lines.map(l=>{
          const o = olds.find(r=> r.id===l._srcId);
          const vals = { 字段名: String(l['字段']).trim(), 字段注释: l['数据类型'] || '', 字段描述: l['字段描述'] || '' };
          if(o){ qcSetKnown(o, vals); return o; }
          return Object.assign({ id: 'tds-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6), [p.treeField]: node, 检验状态: '待检验' }, vals);
        });
        bag.main = list.filter(r=> r[p.treeField]!==node).concat(kept);
        bumpStore();
        formVisible.value = false;
        ElMessage.success('数据源「' + node + '」已保存，共 ' + kept.length + ' 个字段');
        return;
      }
      formVisible.value = false;
      ElMessage.success('数据源「' + node + '」设置已保存');
    }
    const qcView = reactive({ visible:false, title:'', width:'900px', desc:[], cols:[], rows:[], btns:[] });
    function qcShowView(o){ Object.assign(qcView, { width:'900px', desc:[], cols:[], rows:[], btns:[] }, o, { visible:true }); }
    const qcEsc = s=> String(s==null ? '' : s).replace(/[&<>"]/g, c=> ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;' }[c]));
    const qcYmd = v=>{
      if(!(v instanceof Date)) return String(v||'').slice(0, 10);
      return v.getFullYear() + '-' + String(v.getMonth()+1).padStart(2, '0') + '-' + String(v.getDate()).padStart(2, '0');
    };
    const qcCodeOf = s=> String(s||'').split(' / ')[0].trim();
    function qcRowDesc(row){
      const cols = ((tabView.value||{}).columns||[]).map(c=> c.field).filter(k=> k && k!=='操作' && k!=='_actions');
      return cols.map(k=> ({ k, v: flowHas(row[k]) ? row[k] : '—' }));
    }
    function qcQueryDesc(){
      return Object.keys(query).filter(k=> !qcEmpty(query[k])).map(k=> ({ k, v: Array.isArray(query[k]) ? query[k].map(qcYmd).join(' ~ ') : query[k] }));
    }
    function qcSampleResult(no){
      const s = flowSplitRow(no), lg = flowLedgerRow(no) || {};
      const ent = ((s||{})._entry||{}).items || {};
      return flowSampleItems(s || lg).map(n=> ({ 检验项: n, 实测值: (ent[n]||{}).实测值 || '—', 检验结论: (ent[n]||{}).结论 || '—' }));
    }
    const cmp = reactive({
      visible:false, more:false, page:1, pageSize:20, selected:[], rows:[], itemCols:[],
      fixed:['样品状态','检验结论','偏差结论','样品编号','样品来源','物料编码','物料名称','物料规格','物料种类','报检批号','检验方案','检验完成时间','检验人'],
      query:{ 样品状态:'', 检验结论:'', 样品编号:'', 报检批号:'' }
    });
    const cmpFiltered = computed(()=> cmp.rows.filter(r=>{
      const q = cmp.query;
      if(q.样品状态 && r['样品状态']!==q.样品状态) return false;
      if(q.检验结论 && r['检验结论']!==q.检验结论) return false;
      if(String(q.样品编号||'').trim() && !String(r['样品编号']||'').includes(String(q.样品编号).trim())) return false;
      if(String(q.报检批号||'').trim() && !String(r['报检批号']||'').includes(String(q.报检批号).trim())) return false;
      return true;
    }));
    const cmpPageRows = computed(()=>{
      const i = (cmp.page - 1) * cmp.pageSize;
      return cmpFiltered.value.slice(i, i + cmp.pageSize);
    });
    const cmpPageSelected = computed(()=>{
      const ids = new Set(cmpPageRows.value.map(r=> r.id));
      return cmp.selected.filter(r=> ids.has(r.id)).length;
    });
    function cmpIndex(i){ return (cmp.page - 1) * cmp.pageSize + i + 1; }
    function onCmpSelect(rows){ cmp.selected = rows || []; }
    function cmpReset(){
      Object.assign(cmp.query, { 样品状态:'', 检验结论:'', 样品编号:'', 报检批号:'' });
      cmp.page = 1;
    }
    function cmpItemText(row, it){
      if(!it || row['样品状态']!=='已完成') return '';
      const v = it['检验项类型']==='定性' ? it['检验结果'] : (it['检验报出值'] || it['检验结果值']);
      return v && v!=='—' ? v : '';
    }
    function openLedgerCompare(){
      const tab = activeTab.value || 'tab-pi';
      const src = ((MOCK.ledger||{})[tab]) || [];
      const names = [];
      cmp.rows = src.map(r=>{
        const demo = buildLedgerInspDemo(r);
        const items = (demo.qual||[]).concat(demo.quant||[]);
        const o = { id: r.id || r['样品编号'] };
        cmp.fixed.forEach(k=>{
          if(k==='偏差结论'){ o[k] = ledgerDevTag(r); return; }
          const v = r[k];
          o[k] = (v==null || v==='—') ? '' : v;
        });
        items.forEach(it=>{
          const n = String(it['检验项名称']||'').trim();
          if(!n || n==='—') return;
          if(!names.includes(n)) names.push(n);
          o[n] = cmpItemText(r, it);
          if(r['样品状态']==='已完成' && (it['偏差结论']==='OOS' || it['检验结论']==='不合格')) o['_bad_'+n] = true;
        });
        return o;
      });
      cmp.itemCols = names;
      cmp.selected = [];
      cmp.page = 1;
      cmp.more = false;
      cmpReset();
      cmp.visible = true;
    }
    function cmpExport(){
      const cols = cmp.fixed.concat(cmp.itemCols);
      const lines = [cols.join(',')].concat(cmpFiltered.value.map(r=> cols.map(c=> '"'+String(r[c]==null?'':r[c]).replace(/"/g,'""')+'"').join(',')));
      const blob = new Blob(['\ufeff'+lines.join('\n')], { type:'text/csv;charset=utf-8' });
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = '数据比对.csv';
      a.click();
      URL.revokeObjectURL(a.href);
      ElMessage.success('已导出 ' + cmpFiltered.value.length + ' 条');
    }
    function qcCompare(){
      if(pageId.value==='ledger'){ openLedgerCompare(); return; }
      const picked = (tableData.value||[]).filter(r=> selectedIds.value.includes(r.id));
      const isRecheck = pageId.value==='recheck';
      if(!picked.length){ ElMessage.warning(isRecheck ? '请先勾选报检单' : '请先勾选样品'); return; }
      const nos = isRecheck ? picked.flatMap(r=> qcOrderSamples(r['报检单号'], qcCurTab()).map(x=> x['样品编号'])) : picked.map(r=> r['样品编号']);
      const list = [...new Set(nos.filter(Boolean))];
      if(list.length < 2){ ElMessage.warning(isRecheck ? '所选报检单不足 2 个样品，无法比对' : '请至少勾选 2 个样品进行比对'); return; }
      const res = Object.fromEntries(list.map(no=> [no, qcSampleResult(no)]));
      const items = [...new Set(list.flatMap(no=> res[no].map(x=> x['检验项'])))];
      const rows = items.map(n=>{
        const o = { 检验项: n };
        list.forEach(no=>{
          const x = res[no].find(y=> y['检验项']===n);
          o[no] = !x ? '—' : (x['检验结论']!=='—' && x['实测值']!=='—' ? x['实测值'] + '（' + x['检验结论'] + '）' : (x['实测值']!=='—' ? x['实测值'] : x['检验结论']));
        });
        return o;
      });
      qcShowView({ title:'数据比对', width: Math.min(1200, 360 + list.length * 160) + 'px', cols: ['检验项', ...list], rows });
    }
    function qcSpcSamples(){
      const tab = qcCurTab();
      let lg = (FLOW_TABS.some(t=> t.name===tab) ? flowBag(FLOW_LEDGER, tab) : []).slice();
      const mat = qcCodeOf(query['物料信息']), sup = qcCodeOf(query['供应商信息']), plan = qcCodeOf(query['检验方案']), item = qcCodeOf(query['检验项']);
      if(mat) lg = lg.filter(r=> r['物料编码']===mat || String(r['物料名称']||'').includes(mat));
      if(sup) lg = lg.filter(r=> r['供应商编码']===sup || String(r['供应商名称']||'').includes(sup));
      if(!qcEmpty(query['采样点'])) lg = lg.filter(r=> String(r['采样点']||'').includes(String(query['采样点'])));
      if(plan) lg = lg.filter(r=> String(r['检验方案']||'').includes(plan));
      const dr = query['日期范围'];
      if(Array.isArray(dr) && dr[0]) lg = lg.filter(r=>{ const d = String(r['取样时间']||'').slice(0, 10); return d >= qcYmd(dr[0]) && d <= qcYmd(dr[1]); });
      return lg.flatMap(r=> qcSampleResult(r['样品编号']).filter(x=> !item || x['检验项'].includes(item)).map(x=> ({
        样品编号: r['样品编号'], 报检批号: r['报检批号'] || '—', 物料编码: r['物料编码'] || '—', 物料名称: r['物料名称'] || '—',
        采样点: r['采样点'] || '—', 取样时间: r['取样时间'] || '—', 检验项: x['检验项'], 实测值: x['实测值'], 检验结论: x['检验结论']
      })));
    }
    function qcOpenSpcSamples(){
      const rows = qcSpcSamples();
      qcShowView({ title:'I图样本数据', width:'1100px', desc: qcQueryDesc(), rows,
        cols: ['样品编号','报检批号','物料编码','物料名称','采样点','取样时间','检验项','实测值','检验结论'] });
    }
    const clDevVisible = ref(false);
    const clDevRule = ref(null);
    const clDevForm = reactive({ UCL运算符:'≤', UCL偏差上限:'', LCL运算符:'≤', LCL偏差上限:'' });
    const clDevOpts = computed(()=> (window.WMS_DICT && window.WMS_DICT.enabledNames('CL_DEV_TH', MOCK.dict)) || []);
    function openClDev(){
      const r = clDevRule.value || {};
      Object.assign(clDevForm, {
        UCL运算符: r.uclOp || '≤',
        UCL偏差上限: r.ucl || '',
        LCL运算符: r.lclOp || '≤',
        LCL偏差上限: r.lcl || ''
      });
      clDevVisible.value = true;
    }
    function confirmClDev(){
      if(!clDevForm.UCL偏差上限 || !clDevForm.LCL偏差上限){ ElMessage.warning('请选择 UCL偏差上限和 LCL偏差上限'); return; }
      clDevRule.value = {
        uclOp: clDevForm.UCL运算符 || '≤',
        ucl: clDevForm.UCL偏差上限,
        lclOp: clDevForm.LCL运算符 || '≤',
        lcl: clDevForm.LCL偏差上限
      };
      clDevVisible.value = false;
      ElMessage.success('已设置偏差阈值');
    }
    const CL_FLOW_KEYS = ['样本总数','D.L','MAX','MIN','Average','σ','UCL相对偏差','LCL相对偏差','UCL(计算)','LCL(计算)','MR-UCL(计算)','MR-LCL(计算)','Xbar(R)-UCL(计算)','Xbar(R)-LCL(计算)','Xbar(S)-UCL(计算)','Xbar(S)-LCL(计算)','R-UCL(计算)','R-LCL(计算)','S-UCL(计算)','S-LCL(计算)','UCL(固定)','LCL(固定)','MR-UCL(固定)','MR-LCL(固定)','Xbar(R)-UCL(固定)','Xbar(R)-LCL(固定)','Xbar(S)-UCL(固定)','Xbar(S)-LCL(固定)','R-UCL(固定)','R-LCL(固定)','S-UCL(固定)','S-LCL(固定)'];
    function clRecordBag(){
      const bag = MOCK['cl-record'] = MOCK['cl-record'] || {};
      if(!Array.isArray(bag['tab-rec'])) bag['tab-rec'] = [];
      if(!Array.isArray(bag['tab-flow'])) bag['tab-flow'] = [];
      return bag;
    }
    function clNextRecordNo(){
      const nums = clRecordBag()['tab-rec'].map(r=> parseInt(String(r['记录编号']||'').replace(/\D/g,''), 10)).filter(n=> !isNaN(n));
      return String((nums.length ? Math.max.apply(null, nums) : 0) + 1).padStart(6, '0');
    }
    function saveClCalcRecord(){
      const rows = tableData.value || [];
      if(!rows.length){ ElMessage.warning('暂无计算结果'); return; }
      const tab = activeTab.value || 'tab-pi';
      const label = ((page.value?.tabs||[]).find(t=> t.name===tab)||{}).label || '采购来料';
      const bag = clRecordBag();
      const no = clNextRecordNo();
      const uniq = (k)=> [...new Set(rows.map(r=> r[k]).filter(v=> v && v!=='—'))];
      const metrics = Array.isArray(query['计算指标']) && query['计算指标'].length ? query['计算指标'].join('、') : 'UCL、LCL';
      const dr = query['日期范围'];
      const range = Array.isArray(dr) && dr[0] ? (qcYmd(dr[0])+'~'+qcYmd(dr[1]||dr[0])) : '—';
      const show = v=> (v==null || v==='') ? '' : String(v);
      bag['tab-rec'].unshift({
        id: 'clr-'+Date.now(),
        记录编号: no,
        业务类型: label,
        日期范围: range,
        物料信息: show(query['物料信息']),
        采样点: show(query['采样点']),
        供应商信息: label==='采购来料' ? show(query['供应商信息']) : '',
        客户信息: label==='生产物料' ? show(query['客户信息']) : '',
        最少样本数: show(query['最少样本数']) || '25',
        检验方案: uniq('检验方案').join('、'),
        检验项: uniq('检验项').join('、'),
        计算指标: metrics,
        来源: '手动',
        方案编码: '',
        创建时间: nowStamp(),
        创建人: '管理员'
      });
      rows.forEach((r, i)=>{
        const line = {
          id: 'clf-'+Date.now()+'-'+i,
          检验方案: r['检验方案'] || '',
          检验项: r['检验项'] || '',
          单位: r['单位'] || '',
          记录编号: no
        };
        CL_FLOW_KEYS.forEach(k=>{ line[k] = r[k]==null || r[k]==='' ? '' : String(r[k]); });
        bag['tab-flow'].unshift(line);
      });
      bumpStore();
      ElMessage.success('已保存，已在控限计算记录生成一条记录');
    }
