            当前数量: '0',
            库存单位: '—',
            供应商信息: '—',
            生产厂家: '—',
            生产日期: '—',
            有效期: '—',
            失效日期: '—',
            当前步骤: '—',
            当前单据号: '—',
            所属阶段: '—',
            最新操作人: '—',
            最新操作时间: '—',
